INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u1-C1','sci',3,2,'u1',1,'물체의 뜻 — 책상, 의자, 연필처럼 모양이 있고 공간을 차지하는 것을 물체라고 함 · 색깔·냄새·소리는 물체가 아님',ARRAY['[4과05-01] 물체를 이루는 물질을 구별하고, 물질의 성질을 비교하여 물질의 종류에 따라 물체를 분류한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u1-C2','sci',3,2,'u1',1,'단서로 물체 알아맞히기(물체 탐정놀이) — 생김새 단서만 들을 때보다 물체를 만든 재료와 재료의 특징 단서를 들으면 더 잘 알아맞힘 · 눈(색깔·모양)·손(만진 느낌)·귀(소리) 등 여러 감각으로 단서를 찾음 · 단서는 어려운 단서부터 하나씩, 친구 말은 끝까지 듣기 · 이기고 지는 놀이가 아니라 물체와 재료를 살펴보는 놀이',ARRAY['[4과05-01] 물체를 이루는 물질을 구별하고, 물질의 성질을 비교하여 물질의 종류에 따라 물체를 분류한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u1-C3','sci',3,2,'u1',2,'물체와 물질 — 물체를 이루는 재료를 물질이라고 함 · 윷은 물체, 윷을 이루는 나무는 물질 · 집게·구슬·자처럼 한 가지 물질로 된 물체 · 물질의 종류: 나무, 철, 유리, 플라스틱(고무, 섬유도 있음)',ARRAY['[4과05-01] 물체를 이루는 물질을 구별하고, 물질의 성질을 비교하여 물질의 종류에 따라 물체를 분류한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u1-C4','sci',3,2,'u1',2,'여러 가지 물질로 이루어진 물체 — 한 물체도 여러 물질로 이루어질 수 있음 — 가위(손잡이 플라스틱·날 철), 액자(틀 나무·앞면 유리), 자전거(몸체 철·바구니 플라스틱·타이어 고무), 필통(몸통 섬유·지퍼 철) · 부분마다 가리키며 어떤 물질인지 살펴봄',ARRAY['[4과05-01] 물체를 이루는 물질을 구별하고, 물질의 성질을 비교하여 물질의 종류에 따라 물체를 분류한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u1-C5','sci',3,2,'u1',3,'물질의 성질을 관찰하는 방법 — 물질은 무늬, 광택, 냄새, 만졌을 때의 느낌, 투명한 정도, 단단한 정도 같은 성질이 있음 · 눈(무늬·광택·투명한 정도)·코(냄새)·손(느낌·단단한 정도)으로 관찰 · 무게는 같은 나무라도 크기와 모양에 따라 달라져 물질의 성질이라 하기 어려움',ARRAY['[4과05-01] 물체를 이루는 물질을 구별하고, 물질의 성질을 비교하여 물질의 종류에 따라 물체를 분류한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u1-C6','sci',3,2,'u1',3,'여러 가지 물질의 성질과 쓰임새 — 나무는 고유한 향과 무늬, 철은 광택이 있고 단단함, 유리는 투명하지만 깨지기 쉬움, 플라스틱은 색깔과 모양을 다양하게 만들 수 있고 가벼운 편 · 물체나 물체의 각 부분은 쓰임새에 알맞은 성질의 물질로 만듦(창문은 투명한 유리)',ARRAY['[4과05-01] 물체를 이루는 물질을 구별하고, 물질의 성질을 비교하여 물질의 종류에 따라 물체를 분류한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u1-C7','sci',3,2,'u1',4,'물질의 종류에 따른 물체의 분류 — 물질의 성질을 바탕으로 물체가 어떤 물질인지 알아보고 물질의 종류에 따라 분류함(북채·나무 숟가락-나무, 트라이앵글·클립-철, 꽃병·비커-유리, 탁구공·바구니-플라스틱) · 누가 나누어도 같은 결과가 나오는 기준(「예쁜가?」는 안 됨) · 나눈 까닭을 함께 말함 · 분리배출도 물질의 종류에 따라 함(유리병류·캔류·플라스틱류)',ARRAY['[4과05-01] 물체를 이루는 물질을 구별하고, 물질의 성질을 비교하여 물질의 종류에 따라 물체를 분류한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u1-C8','sci',3,2,'u1',5,'부피와 고체의 성질 — 물질이 차지하는 공간의 크기를 부피라고 함 · 고체는 담는 용기에 관계없이 모양과 부피가 변하지 않고 손으로 잡을 수 있음 · 종이·스펀지처럼 단단하지 않은 고체도 있음 · 모래 알갱이 하나하나는 모양과 부피가 그대로라 고체',ARRAY['[4과05-02] 고체, 액체, 기체의 성질을 관찰하고 비교하여 물질의 상태를 구분한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u1-C9','sci',3,2,'u1',5,'액체의 성질 — 액체는 흐르는 성질이 있어 손으로 잡을 수 없고, 담는 용기에 따라 모양은 변하지만 부피는 변하지 않음 · 물 높이를 유성펜으로 표시하고 다른 용기에 옮겼다가 처음 용기에 다시 부으면 높이가 같음 · 넓은 그릇에서 낮아 보이고 길쭉한 병에서 높아 보일 뿐 · 물·우유·간장·주스·참기름',ARRAY['[4과05-02] 고체, 액체, 기체의 성질을 관찰하고 비교하여 물질의 상태를 구분한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u1-C10','sci',3,2,'u1',6,'공기가 공간을 차지하는지 알아보는 실험 — 수조 물 높이 표시 → 탁구공을 띄우고 뚜껑을 닫은 아랫부분 잘린 페트병으로 덮음 → 바닥까지 밀어 넣으면 탁구공이 바닥 쪽으로 내려가고 물 높이가 처음보다 높아짐 → 뚜껑을 열면 탁구공이 떠올라 처음 위치·처음 높이와 같아짐 · 페트병 속 공기가 공간을 차지해 물을 밀어냄 · 잘린 부분은 절연 테이프로 감쌈',ARRAY['[4과05-02] 고체, 액체, 기체의 성질을 관찰하고 비교하여 물질의 상태를 구분한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u1-C11','sci',3,2,'u1',6,'기체의 성질과 이용 — 공기는 눈에 보이지 않고 손으로 잡을 수 없지만 공간을 차지함 · 담는 용기에 따라 모양이 변하고 그 공간을 가득 채우는 상태가 기체 · 기체는 물질의 상태이고 공기는 기체의 한 가지 · 공·튜브·고무보트·바람 인형은 공기를 넣어, 이불 압축 팩은 공기를 빼내어 씀 · 지퍼 백이 부풀지 않으면 구멍',ARRAY['[4과05-02] 고체, 액체, 기체의 성질을 관찰하고 비교하여 물질의 상태를 구분한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u1-C12','sci',3,2,'u1',7,'고체, 액체, 기체의 성질 비교 — 고체·액체·기체는 모두 공간을 차지함 · 고체·액체는 보이고 공기는 보이지 않음 · 고체만 손으로 잡을 수 있음 · 고체는 모양·부피 그대로, 액체는 모양만 변함, 기체는 모양과 부피가 변하며 용기를 가득 채움 · 참기름·식용유처럼 물이 들어 있지 않은 액체도 있음 · 한 물체에 여러 상태가 함께 있음(타이어와 타이어 속 공기) · 나뭇잎이 흔들리면 공기가 있음',ARRAY['[4과05-02] 고체, 액체, 기체의 성질을 관찰하고 비교하여 물질의 상태를 구분한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u1-C13','sci',3,2,'u1',8,'물질의 성질을 이용한 물체 설계 — 생활에서 필요한 물체와 쓰임새 찾기 → 쓰임새에 알맞은 물질의 성질 고르기 → 설계도 그리고 소개하기 · 독서대: 받침대 철(단단함), 몸통 플라스틱(가벼움), 바닥 고무(미끄러지지 않음), 앞판 유리(투명함), 책 받침 판 나무(무늬) · 좋은 점은 물질의 성질과 이어서 말함 · 친구 설계는 잘한 점을 먼저, 보완할 점은 대안과 함께 · 비싼 물질보다 쓰임새에 알맞은 물질',ARRAY['[4과05-03] 물질의 성질을 이용하여 쓰임새 있는 물체를 설계한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC3-2-u1-C14','sci',3,2,'u1',9,'3D 프린터 — 3D 프린터는 컴퓨터에 넣은 설계도에 따라 액체나 가루 물질을 정해진 두께만큼 겹겹이 쌓아 물체를 만듦 · 설계도와 물질이 꼭 있어야 함 · 재료: 플라스틱, 금속, 식재료 · 운동화·옷·도자기·과자·건축물·자동차 부품·인공 치아 · 의료·건축·자동차 등 여러 분야 · 3D 프린팅 전문가는 제품을 디자인해 인쇄하고 다듬음',ARRAY['[4과05-03] 물질의 성질을 이용하여 쓰임새 있는 물체를 설계한다(차시 머리 주석 코드 기준 · 문구 W7 확인)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X01','sci',3,'u1',ARRAY['SC3-2-u1-C1']::text[],'물체의 뜻을 잘못 안다(색깔·냄새·소리를 물체로 여기거나, 모양이 없어도 물체라고 여기는 등)','모양이 있고 공간을 차지해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X02','sci',3,'u1',ARRAY['SC3-2-u1-C2']::text[],'생김새 단서만으로 충분하다고 여겨, 재료와 재료의 특징 단서가 물체를 알아맞히는 데 도움이 됨을 놓친다','재료를 들으면 더 잘 맞혀요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X03','sci',3,'u1',ARRAY['SC3-2-u1-C2','SC3-2-u1-C5']::text[],'단서나 성질을 알아낸 감각을 뒤바꾼다(색깔을 손으로, 냄새를 눈으로, 단단한 정도를 귀로 등)','눈 · 코 · 손 · 귀') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X04','sci',3,'u1',ARRAY['SC3-2-u1-C2']::text[],'탐정놀이 방법과 태도를 잘못 안다(쉬운 단서부터, 한꺼번에, 친구 말 끊기, 이기고 지는 놀이로 여기기 등)','어려운 단서부터 · 끝까지 듣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X05','sci',3,'u1',ARRAY['SC3-2-u1-C3']::text[],'물체와 물질을 뒤바꾼다(윷을 물질로, 나무를 물체로 여기는 등)','물질은 물체를 이루는 재료') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X06','sci',3,'u1',ARRAY['SC3-2-u1-C3','SC3-2-u1-C4']::text[],'모든 물체는 한 가지 물질로만 이루어진다고 여긴다','가위 · 액자 · 자전거') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X07','sci',3,'u1',ARRAY['SC3-2-u1-C3','SC3-2-u1-C4']::text[],'물체나 물체의 부분이 어떤 물질로 이루어졌는지 잘못 안다(집게를 나무로, 가위 날을 플라스틱으로 등)','부분마다 가리키며 살펴요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X08','sci',3,'u1',ARRAY['SC3-2-u1-C5']::text[],'무게를 물질마다 정해진 성질로 여긴다','크기에 따라 무게가 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X09','sci',3,'u1',ARRAY['SC3-2-u1-C5','SC3-2-u1-C6']::text[],'물질의 성질을 뒤바꾼다(유리에 광택과 무늬, 철이 투명함, 나무가 깨지기 쉬움 등)','나무 무늬 · 철 광택 · 유리 투명') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X10','sci',3,'u1',ARRAY['SC3-2-u1-C6']::text[],'물체를 그 물질로 만든 까닭을 성질과 잇지 못한다(창문을 유리로 만든 까닭을 향이나 무게로 드는 등)','쓰임새에 알맞은 성질') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X11','sci',3,'u1',ARRAY['SC3-2-u1-C6']::text[],'플라스틱의 성질을 잘못 안다(한 가지 색으로만 만든다, 매우 무겁다, 고유한 향이 있다 등)','색깔·모양이 다양, 가벼운 편') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X12','sci',3,'u1',ARRAY['SC3-2-u1-C7']::text[],'사람마다 다른 기준(예쁜가, 좋아하는가)이나 색깔로 나누고 물질의 종류에 따른 분류라고 여긴다','누가 나누어도 같게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X13','sci',3,'u1',ARRAY['SC3-2-u1-C7']::text[],'물체를 잘못된 물질의 무리에 분류한다(요구르트병을 유리로, 탁구공을 유리로 등)','성질을 떠올려 물질을 찾아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X14','sci',3,'u1',ARRAY['SC3-2-u1-C7']::text[],'분류할 때 까닭을 말하지 않거나, 분리배출을 물질의 종류와 관계없이 해도 된다고 여긴다','나눈 까닭 · 분리배출') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X15','sci',3,'u1',ARRAY['SC3-2-u1-C8']::text[],'부피의 뜻을 잘못 안다(무게, 높이, 물체의 색깔 등으로)','차지하는 공간의 크기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X16','sci',3,'u1',ARRAY['SC3-2-u1-C8']::text[],'고체의 성질을 잘못 안다(담는 용기에 따라 모양이 변한다, 손으로 잡을 수 없다 등)','모양과 부피가 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X17','sci',3,'u1',ARRAY['SC3-2-u1-C8']::text[],'모든 고체는 단단하다고 여겨 종이·스펀지 같은 것을 고체가 아니라고 한다','단단하지 않은 고체도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X18','sci',3,'u1',ARRAY['SC3-2-u1-C8']::text[],'모래 같은 가루는 컵에 따라 모양이 변하니 액체라고 여긴다','알갱이 하나는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X19','sci',3,'u1',ARRAY['SC3-2-u1-C9']::text[],'액체를 다른 용기에 옮기면 높이가 달라지니 부피도 변한다고 여긴다','처음 용기에 다시 부어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X20','sci',3,'u1',ARRAY['SC3-2-u1-C9']::text[],'액체의 성질을 잘못 안다(손으로 잡을 수 있다, 모양이 그대로다, 흐르지 않는다 등)','흐르고 모양이 변해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X21','sci',3,'u1',ARRAY['SC3-2-u1-C10','SC3-2-u1-C11']::text[],'공기는 눈에 보이지 않으니 공간을 차지하지 않는다고 여긴다','보이지 않아도 공간을 차지해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X22','sci',3,'u1',ARRAY['SC3-2-u1-C10']::text[],'탁구공·페트병 실험의 결과를 뒤바꾸거나 그 까닭을 공기와 잇지 못한다','공기가 물을 밀어내요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X23','sci',3,'u1',ARRAY['SC3-2-u1-C10']::text[],'페트병 실험의 방법과 안전을 잘못 안다(뚜껑을 연 채 밀어 넣기, 높이를 표시하지 않기, 잘린 부분을 그대로 두기 등)','뚜껑 닫고 · 높이 표시 · 테이프') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X24','sci',3,'u1',ARRAY['SC3-2-u1-C11']::text[],'기체와 공기를 같은 말로 여긴다','공기는 기체의 한 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X25','sci',3,'u1',ARRAY['SC3-2-u1-C11']::text[],'기체의 성질을 잘못 안다(모양이 그대로다, 용기의 일부만 채운다, 손으로 잡을 수 있다 등)','용기를 가득 채워요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X26','sci',3,'u1',ARRAY['SC3-2-u1-C11']::text[],'공기를 넣어 쓰는 물체와 빼내어 쓰는 물체를 뒤바꾸거나 생활 속 기체 이용을 잘못 안다','튜브는 넣고 압축 팩은 빼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X27','sci',3,'u1',ARRAY['SC3-2-u1-C12']::text[],'세 가지 상태의 공통점과 차이점을 뒤바꾼다(세 상태 모두 보인다, 액체만 공간을 차지한다 등)','모두 공간을 차지해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X28','sci',3,'u1',ARRAY['SC3-2-u1-C12']::text[],'모든 액체에는 물이 들어 있다고 여긴다','참기름 · 식용유') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X29','sci',3,'u1',ARRAY['SC3-2-u1-C12']::text[],'한 물체를 한 가지 상태로만 보아 물체와 그 속의 물질을 섞는다(타이어와 타이어 속 공기를 같은 상태로 등)','부분마다 따로 따져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X30','sci',3,'u1',ARRAY['SC3-2-u1-C12','SC3-2-u1-C8','SC3-2-u1-C9','SC3-2-u1-C11']::text[],'물질을 고체·액체·기체로 잘못 가른다','모양과 부피를 따져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X31','sci',3,'u1',ARRAY['SC3-2-u1-C13']::text[],'설계의 좋은 점을 물질의 성질과 잇지 않거나(그냥 마음에 들어서), 비싼 물질이면 좋은 설계라고 여긴다','성질과 이어서 말해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X32','sci',3,'u1',ARRAY['SC3-2-u1-C13']::text[],'쓰임새에 맞지 않는 물질을 고른다(들고 다닐 독서대를 무거운 철로만, 미끄럼 막기에 유리 등)','쓰임새에 알맞은 성질') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X33','sci',3,'u1',ARRAY['SC3-2-u1-C13']::text[],'친구 설계에 보완할 점을 흉보듯 말하거나 대안 없이 말한다','잘한 점 먼저 · 대안과 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X34','sci',3,'u1',ARRAY['SC3-2-u1-C14']::text[],'3D 프린터가 물체를 만드는 방법을 잘못 안다(깎아 없앤다, 설계도나 재료 없이 만든다 등)','설계도 · 물질 · 겹겹이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X35','sci',3,'u1',ARRAY['SC3-2-u1-C14']::text[],'3D 프린터로 만들 수 있는 것과 쓰는 재료를 잘못 안다(살아 있는 생물, 한 가지 재료만 등)','플라스틱 · 금속 · 식재료') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-2-u1-X36','sci',3,'u1',ARRAY['SC3-2-u1-C14']::text[],'3D 프린터가 쓰이는 분야와 3D 프린팅 전문가가 하는 일을 잘못 안다','의료 · 건축 · 자동차') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_basic#1','sci',3,2,'u1','L01','g3_2_sci_u1_L01_basic','lesson_basic','SC3-2-u1-C1',1,'mc','auto','책상, 의자처럼 모양이 있고 공간을 차지하는 것을 무엇이라고 하나요?',ARRAY['SC3-2-u1-X01']::text[],false,'{"seq":1,"concept":"SC3-2-u1-C1","difficulty":1,"kind":"mc","stem":"책상, 의자처럼 모양이 있고 공간을 차지하는 것을 무엇이라고 하나요?","options":[{"t":"물체","correct":true},{"t":"색깔","mis":"SC3-2-u1-X01"},{"t":"냄새","mis":"SC3-2-u1-X01"},{"t":"소리","mis":"SC3-2-u1-X01"}],"explanation":["책상, 의자를 떠올려요.","모양이 있고 공간을 차지해요.","물체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_basic#2','sci',3,2,'u1','L01','g3_2_sci_u1_L01_basic','lesson_basic','SC3-2-u1-C2',1,'sa','auto','단서를 듣고 어떤 물체인지 알아맞히는 놀이를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u1-C2","difficulty":1,"kind":"sa","stem":"단서를 듣고 어떤 물체인지 알아맞히는 놀이를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["탐정놀이","탐정 놀이"],"explanation":["탐정처럼 해요.","단서를 들어요.","탐정놀이예요."],"mis":"SC3-2-u1-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_basic#3','sci',3,2,'u1','L01','g3_2_sci_u1_L01_basic','lesson_basic','SC3-2-u1-C1',1,'ox','auto','연필은 물체예요.',ARRAY['SC3-2-u1-X01']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C1","difficulty":1,"kind":"ox","stem":"연필은 물체예요.","answer":"O","reason_options":[{"t":"연필은 모양이 있고 공간을 차지하기 때문에","correct":true},{"t":"색깔이 있는 것만 물체이기 때문에","mis":"SC3-2-u1-X01"}],"mis":"SC3-2-u1-X01","explanation":["연필을 떠올려요.","모양이 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_basic#4','sci',3,2,'u1','L01','g3_2_sci_u1_L01_basic','lesson_basic','SC3-2-u1-C2',1,'mc','auto','탐정 카드의 단서가 가리키는 물체는 무엇인가요?',ARRAY['SC3-2-u1-X02']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C2","difficulty":1,"kind":"mc","stem":"탐정 카드의 단서가 가리키는 물체는 무엇인가요?","options":[{"t":"플라스틱 컵","correct":true},{"t":"유리구슬","mis":"SC3-2-u1-X02"},{"t":"숟가락","mis":"SC3-2-u1-X02"},{"t":"지우개","mis":"SC3-2-u1-X02"}],"explanation":["단서 ②를 봐요.","단서 ③을 봐요.","플라스틱 컵이에요."],"asset":{"type":"passage","lines":["단서 ① 가볍고 색깔이 있어요.","단서 ② 플라스틱으로 되어 있어요.","단서 ③ 무언가를 담아 마실 수 있어요."],"title":"탐정 카드 하나"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_basic#5','sci',3,2,'u1','L01','g3_2_sci_u1_L01_basic','lesson_basic','SC3-2-u1-C2',2,'match','auto','단서와 물체를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u1-C2","difficulty":2,"kind":"match","stem":"단서와 물체를 알맞게 이으세요.","pairs":[{"l":"종이로 되어 있고 글자가 가득해요","r":"책"},{"l":"고무로 되어 있고 글씨를 지워요","r":"지우개"},{"l":"철로 되어 있고 국을 떠먹어요","r":"숟가락"}],"mis":"SC3-2-u1-X02","explanation":["재료를 봐요.","쓰임새도 봐요.","종이-책, 고무-지우개, 철-숟가락이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_basic#6','sci',3,2,'u1','L01','g3_2_sci_u1_L01_basic','lesson_basic','SC3-2-u1-C2',2,'mc','auto','탐정놀이에서 단서를 말하는 알맞은 차례는 무엇인가요?',ARRAY['SC3-2-u1-X04']::text[],false,'{"seq":6,"concept":"SC3-2-u1-C2","difficulty":2,"kind":"mc","stem":"탐정놀이에서 단서를 말하는 알맞은 차례는 무엇인가요?","options":[{"t":"어려운 단서부터 하나씩 말한다","correct":true},{"t":"정답을 먼저 말한다","mis":"SC3-2-u1-X04"},{"t":"가장 쉬운 단서를 먼저 말한다","mis":"SC3-2-u1-X04"},{"t":"단서를 한꺼번에 모두 말한다","mis":"SC3-2-u1-X04"}],"explanation":["쉬운 단서를 먼저 주면 금방 끝나요.","하나씩 말해요.","어려운 단서부터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_basic#7','sci',3,2,'u1','L01','g3_2_sci_u1_L01_basic','lesson_basic','SC3-2-u1-C2',2,'mc','auto','「흔들면 달그락 소리가 나요」는 어떤 감각으로 찾은 단서인가요?',ARRAY['SC3-2-u1-X03']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C2","difficulty":2,"kind":"mc","stem":"「흔들면 달그락 소리가 나요」는 어떤 감각으로 찾은 단서인가요?","options":[{"t":"귀","correct":true},{"t":"눈","mis":"SC3-2-u1-X03"},{"t":"코","mis":"SC3-2-u1-X03"},{"t":"손","mis":"SC3-2-u1-X03"}],"explanation":["소리를 들어요.","듣는 것은 귀예요.","귀예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_basic#8','sci',3,2,'u1','L01','g3_2_sci_u1_L01_basic','lesson_basic','SC3-2-u1-C2',2,'blank','auto','생김새만 들을 때보다 물체를 만든 (    )와 그 특징을 들으면 더 잘 알아맞힐 수 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u1-X02']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C2","difficulty":2,"kind":"blank","stem":"생김새만 들을 때보다 물체를 만든 (    )와 그 특징을 들으면 더 잘 알아맞힐 수 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"재료","correct":true},{"t":"크기","mis":"SC3-2-u1-X02"},{"t":"색깔","mis":"SC3-2-u1-X02"},{"t":"소리","mis":"SC3-2-u1-X02"}],"explanation":["「나무로」, 「철로」를 떠올려요.","무엇으로 되어 있나요?","재료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_basic#9','sci',3,2,'u1','L01','g3_2_sci_u1_L01_basic','lesson_basic','SC3-2-u1-C2',2,'ox','auto','탐정놀이는 가장 많이 맞힌 사람이 앞서는 놀이예요.',ARRAY['SC3-2-u1-X04']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C2","difficulty":2,"kind":"ox","stem":"탐정놀이는 가장 많이 맞힌 사람이 앞서는 놀이예요.","answer":"X","reason_options":[{"t":"물체와 재료를 살펴보는 놀이이기 때문에","correct":true},{"t":"많이 맞혀야 잘한 놀이이기 때문에","mis":"SC3-2-u1-X04"}],"mis":"SC3-2-u1-X04","explanation":["놀이의 목적을 떠올려요.","살펴보는 놀이예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_basic#10','sci',3,2,'u1','L01','g3_2_sci_u1_L01_basic','lesson_basic','SC3-2-u1-C2',3,'mc','auto','「길쭉한 막대 모양이에요」, 「나무로 되어 있어요」, 「북을 두드려 소리를 내요」가 가리키는 물체는 무엇인가요?',ARRAY['SC3-2-u1-X02']::text[],false,'{"seq":10,"concept":"SC3-2-u1-C2","difficulty":3,"kind":"mc","stem":"「길쭉한 막대 모양이에요」, 「나무로 되어 있어요」, 「북을 두드려 소리를 내요」가 가리키는 물체는 무엇인가요?","options":[{"t":"북채","correct":true},{"t":"나무 숟가락","mis":"SC3-2-u1-X02"},{"t":"철 숟가락","mis":"SC3-2-u1-X02"},{"t":"플라스틱 자","mis":"SC3-2-u1-X02"}],"explanation":["막대 모양이에요.","나무예요.","북을 두드리는 북채예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_challenge#1','sci',3,2,'u1','L01','g3_2_sci_u1_L01_challenge','lesson_challenge','SC3-2-u1-C2',2,'sa','auto','탐정 카드의 단서가 가리키는 물체는 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u1-C2","difficulty":2,"kind":"sa","stem":"탐정 카드의 단서가 가리키는 물체는 무엇인가요? 두 글자로 쓰세요.","answer":["연필"],"explanation":["막대 모양이에요.","나무 몸통이에요.","연필이에요."],"asset":{"type":"passage","lines":["단서 ① 길쭉한 막대 모양이에요.","단서 ② 몸통이 나무로 되어 있어요.","단서 ③ 종이에 글씨를 쓸 수 있어요."],"title":"탐정 카드 둘"},"mis":"SC3-2-u1-X02"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_challenge#2','sci',3,2,'u1','L01','g3_2_sci_u1_L01_challenge','lesson_challenge','SC3-2-u1-C1',2,'mc','auto','다음 가운데 물체가 아닌 것은 무엇인가요?',ARRAY['SC3-2-u1-X01']::text[],false,'{"seq":2,"concept":"SC3-2-u1-C1","difficulty":2,"kind":"mc","stem":"다음 가운데 물체가 아닌 것은 무엇인가요?","options":[{"t":"노란색","correct":true},{"t":"책상","mis":"SC3-2-u1-X01"},{"t":"지우개","mis":"SC3-2-u1-X01"},{"t":"숟가락","mis":"SC3-2-u1-X01"}],"explanation":["모양이 있는지 봐요.","색깔은 모양이 없어요.","노란색이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_challenge#3','sci',3,2,'u1','L01','g3_2_sci_u1_L01_challenge','lesson_challenge','SC3-2-u1-C2',3,'mc','auto','두 단서 묶음 가운데 물체를 더 잘 알아맞히게 해 주는 묶음과 그 까닭은 무엇인가요?',ARRAY['SC3-2-u1-X02']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C2","difficulty":3,"kind":"mc","stem":"두 단서 묶음 가운데 물체를 더 잘 알아맞히게 해 주는 묶음과 그 까닭은 무엇인가요?","options":[{"t":"나 묶음 — 재료와 재료의 특징이 들어 있어서","correct":true},{"t":"가 묶음 — 단서가 짧아서","mis":"SC3-2-u1-X02"},{"t":"가 묶음 — 생김새만 말해서","mis":"SC3-2-u1-X02"},{"t":"두 묶음 모두 같다 — 둘 다 동그랗다고 해서","mis":"SC3-2-u1-X02"}],"explanation":["나 묶음에 무엇이 더 있나요?","유리, 속이 비쳐요가 있어요.","나 묶음이에요."],"asset":{"type":"passage","lines":["가 묶음 — 「작고 동그래요.」","나 묶음 — 「작고 동그래요. 유리로 되어 있어 속이 비쳐요.」"],"title":"두 단서 묶음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_challenge#4','sci',3,2,'u1','L01','g3_2_sci_u1_L01_challenge','lesson_challenge','SC3-2-u1-C2',3,'error','auto','탐정놀이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u1-X04']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C2","difficulty":3,"kind":"error","stem":"탐정놀이를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「쉬운 단서부터 말해야 금방 맞혀서 좋아.」","correct":true,"mis_target":"SC3-2-u1-X04"},{"t":"친구 나 — 「친구가 말할 때는 끝까지 들어.」","mis":"SC3-2-u1-X04"},{"t":"친구 다 — 「잘못 맞혀도 괜찮아. 다시 생각해 보자.」","mis":"SC3-2-u1-X04"}],"explanation":["단서 차례를 떠올려요.","어려운 단서부터예요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_challenge#5','sci',3,2,'u1','L01','g3_2_sci_u1_L01_challenge','lesson_challenge','SC3-2-u1-C2',3,'mc','auto','손으로 만져서 알게 된 단서는 무엇인가요?',ARRAY['SC3-2-u1-X03']::text[],false,'{"seq":5,"concept":"SC3-2-u1-C2","difficulty":3,"kind":"mc","stem":"손으로 만져서 알게 된 단서는 무엇인가요?","options":[{"t":"만지면 차갑고 매끈해요","correct":true},{"t":"노란색이에요","mis":"SC3-2-u1-X03"},{"t":"동그란 모양이에요","mis":"SC3-2-u1-X03"},{"t":"흔들면 달그락 소리가 나요","mis":"SC3-2-u1-X03"}],"explanation":["손으로 느끼는 것이에요.","차갑고 매끈해요.","만진 느낌 단서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_challenge#6','sci',3,2,'u1','L01','g3_2_sci_u1_L01_challenge','lesson_challenge','SC3-2-u1-C2',3,'mc','auto','플라스틱 컵을 알려 주는 단서로 알맞지 않은 것은 무엇인가요?',ARRAY['SC3-2-u1-X02']::text[],false,'{"seq":6,"concept":"SC3-2-u1-C2","difficulty":3,"kind":"mc","stem":"플라스틱 컵을 알려 주는 단서로 알맞지 않은 것은 무엇인가요?","options":[{"t":"떨어뜨리면 쉽게 깨져요","correct":true},{"t":"가벼워요","mis":"SC3-2-u1-X02"},{"t":"플라스틱으로 되어 있어요","mis":"SC3-2-u1-X02"},{"t":"무언가를 담아 마실 수 있어요","mis":"SC3-2-u1-X02"}],"explanation":["플라스틱 컵을 떠올려요.","잘 깨질까요?","쉽게 깨지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_challenge#7','sci',3,2,'u1','L01','g3_2_sci_u1_L01_challenge','lesson_challenge','SC3-2-u1-C2',3,'match','auto','단서와 단서를 찾은 감각을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SC3-2-u1-C2","difficulty":3,"kind":"match","stem":"단서와 단서를 찾은 감각을 알맞게 이으세요.","pairs":[{"l":"반짝반짝 빛나요","r":"눈"},{"l":"말랑말랑해요","r":"손"},{"l":"딸랑딸랑 소리가 나요","r":"귀"}],"mis":"SC3-2-u1-X03","explanation":["보는 것은 눈이에요.","느끼는 것은 손이에요.","듣는 것은 귀예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_challenge#8','sci',3,2,'u1','L01','g3_2_sci_u1_L01_challenge','lesson_challenge','SC3-2-u1-C2',4,'mc','auto','친구에게 지우개를 맞히게 하려고 단서를 만들었어요. 가장 알맞은 차례는 무엇인가요?',ARRAY['SC3-2-u1-X04']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C2","difficulty":4,"kind":"mc","stem":"친구에게 지우개를 맞히게 하려고 단서를 만들었어요. 가장 알맞은 차례는 무엇인가요?","options":[{"t":"「누르면 조금 말랑해요」 → 「고무로 되어 있어요」 → 「연필 글씨를 지울 수 있어요」","correct":true},{"t":"「연필 글씨를 지울 수 있어요」 → 「고무로 되어 있어요」 → 「누르면 조금 말랑해요」","mis":"SC3-2-u1-X04"},{"t":"「지우개예요」 → 「고무로 되어 있어요」 → 「누르면 조금 말랑해요」","mis":"SC3-2-u1-X04"},{"t":"세 단서를 한꺼번에 말한다","mis":"SC3-2-u1-X04"}],"explanation":["어려운 단서부터예요.","쓰임새는 쉬운 단서예요.","말랑함 → 고무 → 지우기 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_challenge#9','sci',3,2,'u1','L01','g3_2_sci_u1_L01_challenge','lesson_challenge','SC3-2-u1-C1',4,'mc','auto','물체끼리만 묶은 것은 무엇인가요?',ARRAY['SC3-2-u1-X01']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C1","difficulty":4,"kind":"mc","stem":"물체끼리만 묶은 것은 무엇인가요?","options":[{"t":"책, 연필, 유리구슬","correct":true},{"t":"책, 노란색, 연필","mis":"SC3-2-u1-X01"},{"t":"소리, 냄새, 지우개","mis":"SC3-2-u1-X01"},{"t":"숟가락, 색깔, 의자","mis":"SC3-2-u1-X01"}],"explanation":["하나씩 따져요.","모양이 있고 공간을 차지하나요?","책, 연필, 유리구슬이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L01_challenge#10','sci',3,2,'u1','L01','g3_2_sci_u1_L01_challenge','lesson_challenge','SC3-2-u1-C2',4,'essay','teacher','교실에 있는 물체 하나를 골라 탐정 카드를 만드세요. 단서 세 개를 어려운 단서부터 쓰고, 재료를 알려 주는 단서를 꼭 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u1-C2","difficulty":4,"kind":"essay","stem":"교실에 있는 물체 하나를 골라 탐정 카드를 만드세요. 단서 세 개를 어려운 단서부터 쓰고, 재료를 알려 주는 단서를 꼭 넣으세요.","answer_guide":{"answer":"예: 물체는 책상이다. 단서 ① 만지면 조금 차갑고 매끈해요. 단서 ② 다리는 철, 위판은 나무로 되어 있어요. 단서 ③ 그 위에서 공부를 해요.","scoring_points":["교실에 있는 물체를 골랐는가","어려운 단서부터 차례대로 썼는가","재료를 알려 주는 단서를 넣었는가"]},"explanation":["물체를 골라요.","어려운 단서부터 써요.","재료 단서를 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L02_basic#1','sci',3,2,'u1','L02','g3_2_sci_u1_L02_basic','lesson_basic','SC3-2-u1-C3',1,'mc','auto','물체를 이루는 재료를 무엇이라고 하나요?',ARRAY['SC3-2-u1-X05','SC3-2-u1-X01']::text[],false,'{"seq":1,"concept":"SC3-2-u1-C3","difficulty":1,"kind":"mc","stem":"물체를 이루는 재료를 무엇이라고 하나요?","options":[{"t":"물질","correct":true},{"t":"물체","mis":"SC3-2-u1-X05"},{"t":"모양","mis":"SC3-2-u1-X01"},{"t":"공간","mis":"SC3-2-u1-X01"}],"explanation":["나무, 철을 한 낱말로 불러요.","물체를 이루는 재료예요.","물질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L02_basic#2','sci',3,2,'u1','L02','g3_2_sci_u1_L02_basic','lesson_basic','SC3-2-u1-C3',1,'sa','auto','윷은 어떤 물질로 이루어져 있나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u1-C3","difficulty":1,"kind":"sa","stem":"윷은 어떤 물질로 이루어져 있나요? 두 글자로 쓰세요.","answer":["나무"],"explanation":["윷을 떠올려요.","나무 무늬가 보여요.","나무예요."],"mis":"SC3-2-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L02_basic#3','sci',3,2,'u1','L02','g3_2_sci_u1_L02_basic','lesson_basic','SC3-2-u1-C3',1,'ox','auto','나무는 물질이에요.',ARRAY['SC3-2-u1-X05']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C3","difficulty":1,"kind":"ox","stem":"나무는 물질이에요.","answer":"O","reason_options":[{"t":"윷 같은 물체를 이루는 재료이기 때문에","correct":true},{"t":"모양이 있는 것만 물질이기 때문에","mis":"SC3-2-u1-X05"}],"mis":"SC3-2-u1-X05","explanation":["윷을 떠올려요.","윷을 이루는 재료예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
