INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L02_basic#8','sci',3,2,'u1','L02','g3_2_sci_u1_L02_basic','lesson_basic','SC3-2-u1-C4',2,'ox','auto','모든 물체는 한 가지 물질로만 이루어져요.',ARRAY['SC3-2-u1-X06']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C4","difficulty":2,"kind":"ox","stem":"모든 물체는 한 가지 물질로만 이루어져요.","answer":"X","reason_options":[{"t":"액자처럼 두 가지 물질로 이루어진 물체도 있기 때문에","correct":true},{"t":"물체 하나에는 재료가 하나만 들어가기 때문에","mis":"SC3-2-u1-X06"}],"mis":"SC3-2-u1-X06","explanation":["액자를 떠올려요.","틀과 앞면이 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L02_basic#9','sci',3,2,'u1','L02','g3_2_sci_u1_L02_basic','lesson_basic','SC3-2-u1-C4',2,'mc','auto','두 가지 물질로 이루어진 물체는 무엇인가요?',ARRAY['SC3-2-u1-X06']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C4","difficulty":2,"kind":"mc","stem":"두 가지 물질로 이루어진 물체는 무엇인가요?","options":[{"t":"액자","correct":true},{"t":"집게","mis":"SC3-2-u1-X06"},{"t":"구슬","mis":"SC3-2-u1-X06"},{"t":"윷","mis":"SC3-2-u1-X06"}],"explanation":["부분마다 물질이 다른 것을 찾아요.","틀은 나무, 앞면은 유리예요.","액자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L02_basic#10','sci',3,2,'u1','L02','g3_2_sci_u1_L02_basic','lesson_basic','SC3-2-u1-C4',3,'mc','auto','자전거의 부분을 보고 알 수 있는 것은 무엇인가요?',ARRAY['SC3-2-u1-X06','SC3-2-u1-X07']::text[],false,'{"seq":10,"concept":"SC3-2-u1-C4","difficulty":3,"kind":"mc","stem":"자전거의 부분을 보고 알 수 있는 것은 무엇인가요?","options":[{"t":"한 물체가 여러 가지 물질로 이루어질 수 있다","correct":true},{"t":"자전거는 철로만 이루어져 있다","mis":"SC3-2-u1-X06"},{"t":"타이어는 플라스틱으로 이루어져 있다","mis":"SC3-2-u1-X07"},{"t":"바구니와 몸체는 같은 물질이다","mis":"SC3-2-u1-X07"}],"explanation":["부분마다 봐요.","철, 플라스틱, 고무가 있어요.","여러 물질이에요."],"asset":{"type":"passage","lines":["몸체 — 철","바구니 — 플라스틱","타이어 — 고무"],"title":"자전거의 부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
