INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L02_challenge#2','sci',3,2,'u1','L02','g3_2_sci_u1_L02_challenge','lesson_challenge','SC3-2-u1-C3',2,'mc','auto','물체와 물질의 차례로 바르게 쓴 것은 무엇인가요?',ARRAY['SC3-2-u1-X05']::text[],false,'{"seq":2,"concept":"SC3-2-u1-C3","difficulty":2,"kind":"mc","stem":"물체와 물질의 차례로 바르게 쓴 것은 무엇인가요?","options":[{"t":"유리구슬 — 유리","correct":true},{"t":"나무 — 윷","mis":"SC3-2-u1-X05"},{"t":"철 — 집게","mis":"SC3-2-u1-X05"},{"t":"플라스틱 — 자","mis":"SC3-2-u1-X05"}],"explanation":["앞이 물체예요.","뒤가 물질이에요.","유리구슬 — 유리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L02_challenge#3','sci',3,2,'u1','L02','g3_2_sci_u1_L02_challenge','lesson_challenge','SC3-2-u1-C4',3,'mc','auto','액자를 보고 바르게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X06','SC3-2-u1-X07']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C4","difficulty":3,"kind":"mc","stem":"액자를 보고 바르게 말한 것은 무엇인가요?","options":[{"t":"틀은 나무, 앞면은 유리로 이루어져 있다","correct":true},{"t":"액자 전체가 유리 한 가지로 이루어져 있다","mis":"SC3-2-u1-X06"},{"t":"틀은 철, 앞면은 플라스틱이다","mis":"SC3-2-u1-X07"},{"t":"틀은 유리, 앞면은 나무이다","mis":"SC3-2-u1-X07"}],"explanation":["틀을 봐요.","앞면을 봐요.","나무와 유리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L02_challenge#4','sci',3,2,'u1','L02','g3_2_sci_u1_L02_challenge','lesson_challenge','SC3-2-u1-C3',3,'error','auto','물체와 물질을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u1-X05','SC3-2-u1-X07','SC3-2-u1-X06']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C3","difficulty":3,"kind":"error","stem":"물체와 물질을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「나무는 물체이고 윷은 물질이야.」","correct":true,"mis_target":"SC3-2-u1-X05"},{"t":"친구 나 — 「집게는 철로 이루어져 있어.」","mis":"SC3-2-u1-X07"},{"t":"친구 다 — 「가위는 두 가지 물질로 이루어져 있어.」","mis":"SC3-2-u1-X06"}],"explanation":["물체와 물질을 떠올려요.","윷이 물체예요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L02_challenge#5','sci',3,2,'u1','L02','g3_2_sci_u1_L02_challenge','lesson_challenge','SC3-2-u1-C4',3,'mc','auto','「내 필통의 몸통은 천처럼 부드럽고, 여닫는 지퍼는 단단해요.」 필통의 물질로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u1-X07','SC3-2-u1-X06']::text[],false,'{"seq":5,"concept":"SC3-2-u1-C4","difficulty":3,"kind":"mc","stem":"「내 필통의 몸통은 천처럼 부드럽고, 여닫는 지퍼는 단단해요.」 필통의 물질로 알맞은 것은 무엇인가요?","options":[{"t":"몸통은 섬유, 지퍼는 철","correct":true},{"t":"몸통은 유리, 지퍼는 나무","mis":"SC3-2-u1-X07"},{"t":"모두 플라스틱","mis":"SC3-2-u1-X06"},{"t":"몸통은 철, 지퍼는 섬유","mis":"SC3-2-u1-X07"}],"explanation":["천처럼 부드러운 것을 떠올려요.","단단한 지퍼예요.","섬유와 철이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
