INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L02_challenge#7','sci',3,2,'u1','L02','g3_2_sci_u1_L02_challenge','lesson_challenge','SC3-2-u1-C3',3,'mc','auto','「철이 들어 있나요?」로 물체를 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶인 것은 무엇인가요?',ARRAY['SC3-2-u1-X07']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C3","difficulty":3,"kind":"mc","stem":"「철이 들어 있나요?」로 물체를 나누었을 때 ⭕ 쪽에 들어가는 것끼리 묶인 것은 무엇인가요?","options":[{"t":"집게, 가위","correct":true},{"t":"윷, 구슬","mis":"SC3-2-u1-X07"},{"t":"자, 액자","mis":"SC3-2-u1-X07"},{"t":"구슬, 자","mis":"SC3-2-u1-X07"}],"explanation":["철이 있는 물체를 찾아요.","가위 날이 철이에요.","집게와 가위예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L02_challenge#8','sci',3,2,'u1','L02','g3_2_sci_u1_L02_challenge','lesson_challenge','SC3-2-u1-C4',4,'mc','auto','자전거의 부분과 물질을 바르게 짝지은 것은 무엇인가요?',ARRAY['SC3-2-u1-X07','SC3-2-u1-X06']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C4","difficulty":4,"kind":"mc","stem":"자전거의 부분과 물질을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"몸체 — 철, 바구니 — 플라스틱, 타이어 — 고무","correct":true},{"t":"몸체 — 고무, 바구니 — 철, 타이어 — 플라스틱","mis":"SC3-2-u1-X07"},{"t":"몸체 — 철, 바구니 — 철, 타이어 — 철","mis":"SC3-2-u1-X06"},{"t":"몸체 — 유리, 바구니 — 나무, 타이어 — 고무","mis":"SC3-2-u1-X07"}],"explanation":["부분마다 봐요.","세 가지 물질이에요.","철, 플라스틱, 고무예요."],"asset":{"type":"passage","lines":["몸체 — 철","바구니 — 플라스틱","타이어 — 고무"],"title":"자전거의 부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L02_challenge#9','sci',3,2,'u1','L02','g3_2_sci_u1_L02_challenge','lesson_challenge','SC3-2-u1-C4',4,'mc','auto','「한 가지 물질로 이루어져 있나요?」로 물체를 바르게 나눈 것은 무엇인가요?',ARRAY['SC3-2-u1-X06']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C4","difficulty":4,"kind":"mc","stem":"「한 가지 물질로 이루어져 있나요?」로 물체를 바르게 나눈 것은 무엇인가요?","options":[{"t":"⭕ 윷, 구슬, 자 / ❌ 액자, 가위","correct":true},{"t":"⭕ 액자, 가위 / ❌ 윷, 구슬, 자","mis":"SC3-2-u1-X06"},{"t":"⭕ 윷, 가위 / ❌ 구슬, 자, 액자","mis":"SC3-2-u1-X06"},{"t":"⭕ 윷, 구슬, 자, 액자, 가위 / ❌ 없음","mis":"SC3-2-u1-X06"}],"explanation":["물체마다 물질 수를 세요.","액자, 가위는 둘이에요.","윷, 구슬, 자가 ⭕예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L02_challenge#10','sci',3,2,'u1','L02','g3_2_sci_u1_L02_challenge','lesson_challenge','SC3-2-u1-C4',4,'essay','teacher','내 주변 물체 하나를 골라 부분마다 어떤 물질로 이루어져 있는지 쓰세요. 그리고 오늘 알게 된 물체와 물질의 관계를 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u1-C4","difficulty":4,"kind":"essay","stem":"내 주변 물체 하나를 골라 부분마다 어떤 물질로 이루어져 있는지 쓰세요. 그리고 오늘 알게 된 물체와 물질의 관계를 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 내 의자는 앉는 판이 나무, 다리가 철, 다리 끝 받침이 고무로 이루어져 있다. 한 물체도 여러 가지 물질로 이루어질 수 있다.","scoring_points":["물체 하나를 골랐는가","부분마다 물질을 바르게 썼는가","한 물체가 여러 물질로 이루어질 수 있음을 썼는가"]},"explanation":["물체를 골라요.","부분마다 써요.","알게 된 것을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_basic#1','sci',3,2,'u1','L03','g3_2_sci_u1_L03_basic','lesson_basic','SC3-2-u1-C6',1,'mc','auto','투명하고 단단하지만 깨지기 쉬운 물질은 무엇인가요?',ARRAY['SC3-2-u1-X09']::text[],false,'{"seq":1,"concept":"SC3-2-u1-C6","difficulty":1,"kind":"mc","stem":"투명하고 단단하지만 깨지기 쉬운 물질은 무엇인가요?","options":[{"t":"유리","correct":true},{"t":"나무","mis":"SC3-2-u1-X09"},{"t":"철","mis":"SC3-2-u1-X09"},{"t":"플라스틱","mis":"SC3-2-u1-X09"}],"explanation":["창문을 떠올려요.","속이 보이고 잘 깨져요.","유리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
