INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_basic#3','sci',3,2,'u1','L03','g3_2_sci_u1_L03_basic','lesson_basic','SC3-2-u1-C6',1,'ox','auto','나무에는 고유한 향과 무늬가 있어요.',ARRAY['SC3-2-u1-X09']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C6","difficulty":1,"kind":"ox","stem":"나무에는 고유한 향과 무늬가 있어요.","answer":"O","reason_options":[{"t":"나무 블록에서 향이 나고 무늬가 보이기 때문에","correct":true},{"t":"향과 무늬는 철의 성질이기 때문에","mis":"SC3-2-u1-X09"}],"mis":"SC3-2-u1-X09","explanation":["나무 블록을 떠올려요.","향과 무늬가 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_basic#4','sci',3,2,'u1','L03','g3_2_sci_u1_L03_basic','lesson_basic','SC3-2-u1-C5',1,'mc','auto','물질의 냄새는 어떤 감각으로 살펴보나요?',ARRAY['SC3-2-u1-X03']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C5","difficulty":1,"kind":"mc","stem":"물질의 냄새는 어떤 감각으로 살펴보나요?","options":[{"t":"코","correct":true},{"t":"눈","mis":"SC3-2-u1-X03"},{"t":"손","mis":"SC3-2-u1-X03"},{"t":"귀","mis":"SC3-2-u1-X03"}],"explanation":["냄새를 맡아요.","맡는 것은 코예요.","코예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_basic#5','sci',3,2,'u1','L03','g3_2_sci_u1_L03_basic','lesson_basic','SC3-2-u1-C6',2,'match','auto','물질과 성질을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u1-C6","difficulty":2,"kind":"match","stem":"물질과 성질을 알맞게 이으세요.","pairs":[{"l":"유리","r":"투명하고 깨지기 쉬워요"},{"l":"철","r":"단단하고 광택이 있어요"},{"l":"나무","r":"무늬와 향이 있어요"},{"l":"플라스틱","r":"색깔을 다양하게 만들 수 있어요"}],"mis":"SC3-2-u1-X09","explanation":["물질마다 하나씩 떠올려요.","유리는 투명해요.","철 광택, 나무 무늬, 플라스틱 색깔이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_basic#6','sci',3,2,'u1','L03','g3_2_sci_u1_L03_basic','lesson_basic','SC3-2-u1-C6',2,'mc','auto','창문을 유리로 만든 까닭은 무엇인가요?',ARRAY['SC3-2-u1-X10','SC3-2-u1-X09']::text[],false,'{"seq":6,"concept":"SC3-2-u1-C6","difficulty":2,"kind":"mc","stem":"창문을 유리로 만든 까닭은 무엇인가요?","options":[{"t":"투명해서 바깥을 볼 수 있어서","correct":true},{"t":"향이 좋아서","mis":"SC3-2-u1-X10"},{"t":"가장 가벼워서","mis":"SC3-2-u1-X10"},{"t":"절대 깨지지 않아서","mis":"SC3-2-u1-X09"}],"explanation":["창문으로 무엇을 하나요?","바깥을 봐요.","투명해서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_basic#7','sci',3,2,'u1','L03','g3_2_sci_u1_L03_basic','lesson_basic','SC3-2-u1-C5',2,'blank','auto','물질은 무늬, 광택, 냄새, 만졌을 때의 느낌, 투명한 정도, 단단한 정도 같은 여러 가지 (    )이 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u1-X08','SC3-2-u1-X05','SC3-2-u1-X10']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C5","difficulty":2,"kind":"blank","stem":"물질은 무늬, 광택, 냄새, 만졌을 때의 느낌, 투명한 정도, 단단한 정도 같은 여러 가지 (    )이 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"성질","correct":true},{"t":"무게","mis":"SC3-2-u1-X08"},{"t":"이름","mis":"SC3-2-u1-X05"},{"t":"가격","mis":"SC3-2-u1-X10"}],"explanation":["물질마다 가진 특징이에요.","물질마다 달라요.","성질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_basic#8','sci',3,2,'u1','L03','g3_2_sci_u1_L03_basic','lesson_basic','SC3-2-u1-C6',2,'ox','auto','플라스틱은 한 가지 색으로만 만들 수 있어요.',ARRAY['SC3-2-u1-X11']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C6","difficulty":2,"kind":"ox","stem":"플라스틱은 한 가지 색으로만 만들 수 있어요.","answer":"X","reason_options":[{"t":"플라스틱은 색깔과 모양을 다양하게 만들 수 있기 때문에","correct":true},{"t":"플라스틱은 색깔이 하나로 정해져 있기 때문에","mis":"SC3-2-u1-X11"}],"mis":"SC3-2-u1-X11","explanation":["플라스틱 장난감을 떠올려요.","색깔이 많아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_basic#9','sci',3,2,'u1','L03','g3_2_sci_u1_L03_basic','lesson_basic','SC3-2-u1-C5',2,'mc','auto','철 캔을 손으로 만졌을 때의 느낌으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u1-X09']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C5","difficulty":2,"kind":"mc","stem":"철 캔을 손으로 만졌을 때의 느낌으로 알맞은 것은 무엇인가요?","options":[{"t":"매끈해요","correct":true},{"t":"거칠거칠해요","mis":"SC3-2-u1-X09"},{"t":"말랑말랑해요","mis":"SC3-2-u1-X09"},{"t":"끈적끈적해요","mis":"SC3-2-u1-X09"}],"explanation":["철 캔을 떠올려요.","표면이 반짝여요.","매끈해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_basic#10','sci',3,2,'u1','L03','g3_2_sci_u1_L03_basic','lesson_basic','SC3-2-u1-C5',3,'mc','auto','큰 통나무와 작은 나무 블록의 무게가 달라요. 알맞은 생각은 무엇인가요?',ARRAY['SC3-2-u1-X08']::text[],false,'{"seq":10,"concept":"SC3-2-u1-C5","difficulty":3,"kind":"mc","stem":"큰 통나무와 작은 나무 블록의 무게가 달라요. 알맞은 생각은 무엇인가요?","options":[{"t":"무게는 크기에 따라 달라서 물질의 성질이라고 하기 어렵다","correct":true},{"t":"통나무는 나무가 아니다","mis":"SC3-2-u1-X08"},{"t":"나무는 언제나 무거운 물질이다","mis":"SC3-2-u1-X08"},{"t":"나무 블록은 철로 되어 있다","mis":"SC3-2-u1-X08"}],"explanation":["둘 다 같은 나무예요.","크기가 달라요.","무게는 크기에 따라 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_challenge#1','sci',3,2,'u1','L03','g3_2_sci_u1_L03_challenge','lesson_challenge','SC3-2-u1-C6',2,'sa','auto','유리처럼 속이 비쳐 보이는 성질을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u1-C6","difficulty":2,"kind":"sa","stem":"유리처럼 속이 비쳐 보이는 성질을 두 글자로 쓰세요.","answer":["투명"],"explanation":["속이 보여요.","투◯이에요.","투명이에요."],"mis":"SC3-2-u1-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_challenge#2','sci',3,2,'u1','L03','g3_2_sci_u1_L03_challenge','lesson_challenge','SC3-2-u1-C5',2,'mc','auto','투명한 정도와 광택은 어떤 감각으로 살펴보나요?',ARRAY['SC3-2-u1-X03']::text[],false,'{"seq":2,"concept":"SC3-2-u1-C5","difficulty":2,"kind":"mc","stem":"투명한 정도와 광택은 어떤 감각으로 살펴보나요?","options":[{"t":"눈","correct":true},{"t":"코","mis":"SC3-2-u1-X03"},{"t":"손","mis":"SC3-2-u1-X03"},{"t":"귀","mis":"SC3-2-u1-X03"}],"explanation":["보아서 알아요.","보는 것은 눈이에요.","눈이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_challenge#3','sci',3,2,'u1','L03','g3_2_sci_u1_L03_challenge','lesson_challenge','SC3-2-u1-C5',3,'error','auto','물질의 성질을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u1-X08','SC3-2-u1-X09']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C5","difficulty":3,"kind":"error","stem":"물질의 성질을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「큰 통나무가 더 무거우니 무게는 나무의 성질이야.」","correct":true,"mis_target":"SC3-2-u1-X08"},{"t":"친구 나 — 「철은 광택이 있고 단단해.」","mis":"SC3-2-u1-X09"},{"t":"친구 다 — 「유리는 투명하지만 깨지기 쉬워.」","mis":"SC3-2-u1-X09"}],"explanation":["무게를 떠올려요.","크기에 따라 달라요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_challenge#4','sci',3,2,'u1','L03','g3_2_sci_u1_L03_challenge','lesson_challenge','SC3-2-u1-C6',3,'mc','auto','두 컵을 비교해 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X09']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C6","difficulty":3,"kind":"mc","stem":"두 컵을 비교해 알맞게 말한 것은 무엇인가요?","options":[{"t":"물질이 달라서 두 컵의 성질이 다르다","correct":true},{"t":"두 컵은 성질이 모두 같다","mis":"SC3-2-u1-X09"},{"t":"유리컵이 플라스틱 컵보다 잘 깨지지 않는다","mis":"SC3-2-u1-X09"},{"t":"플라스틱 컵은 속이 보이니 유리로 되어 있다","mis":"SC3-2-u1-X09"}],"explanation":["표를 봐요.","깨지는 정도가 달라요.","물질이 달라 성질이 달라요."],"asset":{"type":"passage","lines":["플라스틱 컵 — 색깔이 있고, 떨어뜨려도 잘 깨지지 않아요.","유리컵 — 투명해서 속이 보이지만, 떨어뜨리면 잘 깨져요."],"title":"두 컵 비교"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_challenge#5','sci',3,2,'u1','L03','g3_2_sci_u1_L03_challenge','lesson_challenge','SC3-2-u1-C6',3,'mc','auto','여러 색깔과 모양의 장난감 블록을 만들기에 알맞은 물질은 무엇인가요?',ARRAY['SC3-2-u1-X10']::text[],false,'{"seq":5,"concept":"SC3-2-u1-C6","difficulty":3,"kind":"mc","stem":"여러 색깔과 모양의 장난감 블록을 만들기에 알맞은 물질은 무엇인가요?","options":[{"t":"플라스틱","correct":true},{"t":"유리","mis":"SC3-2-u1-X10"},{"t":"나무","mis":"SC3-2-u1-X10"},{"t":"철","mis":"SC3-2-u1-X10"}],"explanation":["색깔과 모양이 여러 가지예요.","다양하게 만들 수 있어요.","플라스틱이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_challenge#6','sci',3,2,'u1','L03','g3_2_sci_u1_L03_challenge','lesson_challenge','SC3-2-u1-C5',3,'match','auto','살펴본 성질과 감각을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u1-C5","difficulty":3,"kind":"match","stem":"살펴본 성질과 감각을 알맞게 이으세요.","pairs":[{"l":"나무의 향","r":"코"},{"l":"철의 광택","r":"눈"},{"l":"단단한 정도","r":"손"}],"mis":"SC3-2-u1-X03","explanation":["향은 맡아요.","광택은 보아요.","단단함은 만져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_challenge#7','sci',3,2,'u1','L03','g3_2_sci_u1_L03_challenge','lesson_challenge','SC3-2-u1-C6',3,'mc','auto','열쇠를 철로 만든 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u1-X10','SC3-2-u1-X11']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C6","difficulty":3,"kind":"mc","stem":"열쇠를 철로 만든 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"단단해서 쉽게 휘거나 부러지지 않아서","correct":true},{"t":"투명해서 속이 보여서","mis":"SC3-2-u1-X10"},{"t":"고유한 향이 나서","mis":"SC3-2-u1-X10"},{"t":"색깔을 다양하게 만들 수 있어서","mis":"SC3-2-u1-X11"}],"explanation":["열쇠를 떠올려요.","튼튼해야 해요.","철이 단단해서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_challenge#8','sci',3,2,'u1','L03','g3_2_sci_u1_L03_challenge','lesson_challenge','SC3-2-u1-C6',4,'mc','auto','아이들이 들고 다니다 떨어뜨려도 잘 깨지지 않는 가벼운 컵을 고르려고 해요. 가장 알맞은 것과 까닭은 무엇인가요?',ARRAY['SC3-2-u1-X10','SC3-2-u1-X08']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C6","difficulty":4,"kind":"mc","stem":"아이들이 들고 다니다 떨어뜨려도 잘 깨지지 않는 가벼운 컵을 고르려고 해요. 가장 알맞은 것과 까닭은 무엇인가요?","options":[{"t":"플라스틱 컵 — 가벼운 편이고 잘 깨지지 않아서","correct":true},{"t":"유리컵 — 투명해서 속이 보이니까","mis":"SC3-2-u1-X10"},{"t":"철 컵 — 광택이 있어 반짝이니까","mis":"SC3-2-u1-X10"},{"t":"나무 컵 — 무게가 정해진 물질이니까","mis":"SC3-2-u1-X08"}],"explanation":["필요한 성질을 찾아요.","가볍고 잘 깨지지 않아야 해요.","플라스틱 컵이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_challenge#9','sci',3,2,'u1','L03','g3_2_sci_u1_L03_challenge','lesson_challenge','SC3-2-u1-C5',4,'mc','auto','물질의 성질로만 말한 것을 모은 것은 무엇인가요?',ARRAY['SC3-2-u1-X08','SC3-2-u1-X09','SC3-2-u1-X11']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C5","difficulty":4,"kind":"mc","stem":"물질의 성질로만 말한 것을 모은 것은 무엇인가요?","options":[{"t":"유리는 투명하다 · 철은 광택이 있다 · 나무는 무늬가 있다","correct":true},{"t":"통나무는 무겁다 · 철은 광택이 있다 · 나무는 무늬가 있다","mis":"SC3-2-u1-X08"},{"t":"유리는 투명하다 · 철은 투명하다 · 나무는 깨지기 쉽다","mis":"SC3-2-u1-X09"},{"t":"플라스틱은 한 가지 색이다 · 유리는 투명하다 · 철은 단단하다","mis":"SC3-2-u1-X11"}],"explanation":["하나씩 따져요.","무게는 성질이 아니에요.","첫째 묶음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L03_challenge#10','sci',3,2,'u1','L03','g3_2_sci_u1_L03_challenge','lesson_challenge','SC3-2-u1-C6',4,'essay','teacher','창문은 유리로 만들어요. 그 까닭을 유리의 성질로 쓰고, 유리로 된 물체를 쓸 때 조심할 점도 유리의 성질과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u1-C6","difficulty":4,"kind":"essay","stem":"창문은 유리로 만들어요. 그 까닭을 유리의 성질로 쓰고, 유리로 된 물체를 쓸 때 조심할 점도 유리의 성질과 이어 쓰세요.","answer_guide":{"answer":"예: 유리는 투명해서 창문을 통해 바깥을 볼 수 있기 때문에 창문을 유리로 만든다. 유리는 깨지기 쉬우므로 유리로 된 물체는 부딪치거나 떨어뜨리지 않게 조심해서 다룬다.","scoring_points":["유리의 성질(투명함)로 까닭을 썼는가","깨지기 쉬운 성질을 썼는가","조심할 점을 성질과 이어 썼는가"]},"explanation":["투명함을 써요.","깨지기 쉬움을 써요.","조심할 점과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_basic#1','sci',3,2,'u1','L04','g3_2_sci_u1_L04_basic','lesson_basic','SC3-2-u1-C7',1,'mc','auto','탁구공은 어떤 물질로 분류하나요?',ARRAY['SC3-2-u1-X13']::text[],false,'{"seq":1,"concept":"SC3-2-u1-C7","difficulty":1,"kind":"mc","stem":"탁구공은 어떤 물질로 분류하나요?","options":[{"t":"플라스틱","correct":true},{"t":"나무","mis":"SC3-2-u1-X13"},{"t":"철","mis":"SC3-2-u1-X13"},{"t":"유리","mis":"SC3-2-u1-X13"}],"explanation":["가볍고 색깔이 다양해요.","탁구공을 떠올려요.","플라스틱이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_basic#2','sci',3,2,'u1','L04','g3_2_sci_u1_L04_basic','lesson_basic','SC3-2-u1-C7',1,'sa','auto','트라이앵글은 어떤 물질로 분류하나요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u1-C7","difficulty":1,"kind":"sa","stem":"트라이앵글은 어떤 물질로 분류하나요? 한 글자로 쓰세요.","answer":["철"],"explanation":["단단하고 광택이 있어요.","반짝여요.","철이에요."],"mis":"SC3-2-u1-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_basic#3','sci',3,2,'u1','L04','g3_2_sci_u1_L04_basic','lesson_basic','SC3-2-u1-C7',1,'ox','auto','분리배출도 물질의 종류에 따라 해요.',ARRAY['SC3-2-u1-X14']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C7","difficulty":1,"kind":"ox","stem":"분리배출도 물질의 종류에 따라 해요.","answer":"O","reason_options":[{"t":"유리병류, 캔류, 플라스틱류처럼 물질의 종류로 나누기 때문에","correct":true},{"t":"분리배출은 물건의 크기에 따라 나누기 때문에","mis":"SC3-2-u1-X14"}],"mis":"SC3-2-u1-X14","explanation":["분리배출함을 떠올려요.","유리병류, 캔류가 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_basic#4','sci',3,2,'u1','L04','g3_2_sci_u1_L04_basic','lesson_basic','SC3-2-u1-C7',1,'mc','auto','꽃병을 유리로 분류한 까닭은 무엇인가요?',ARRAY['SC3-2-u1-X09']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C7","difficulty":1,"kind":"mc","stem":"꽃병을 유리로 분류한 까닭은 무엇인가요?","options":[{"t":"투명하고 깨질 수 있어서","correct":true},{"t":"광택이 있고 매우 단단해서","mis":"SC3-2-u1-X09"},{"t":"고유한 향과 무늬가 있어서","mis":"SC3-2-u1-X09"},{"t":"색깔이 다양하고 가벼워서","mis":"SC3-2-u1-X09"}],"explanation":["꽃병을 떠올려요.","속이 보여요.","투명하고 깨질 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_basic#5','sci',3,2,'u1','L04','g3_2_sci_u1_L04_basic','lesson_basic','SC3-2-u1-C7',2,'match','auto','물체와 분류할 물질을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u1-C7","difficulty":2,"kind":"match","stem":"물체와 분류할 물질을 알맞게 이으세요.","pairs":[{"l":"어항","r":"유리"},{"l":"물뿌리개","r":"플라스틱"},{"l":"북채","r":"나무"},{"l":"클립","r":"철"}],"mis":"SC3-2-u1-X13","explanation":["성질을 떠올려요.","투명한 것, 가벼운 것을 찾아요.","어항-유리, 물뿌리개-플라스틱, 북채-나무, 클립-철이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_basic#6','sci',3,2,'u1','L04','g3_2_sci_u1_L04_basic','lesson_basic','SC3-2-u1-C7',2,'mc','auto','누가 나누어도 같은 결과가 나오는 분류 기준은 무엇인가요?',ARRAY['SC3-2-u1-X12']::text[],false,'{"seq":6,"concept":"SC3-2-u1-C7","difficulty":2,"kind":"mc","stem":"누가 나누어도 같은 결과가 나오는 분류 기준은 무엇인가요?","options":[{"t":"철로 이루어져 있나요?","correct":true},{"t":"보기에 예쁜가요?","mis":"SC3-2-u1-X12"},{"t":"내가 좋아하나요?","mis":"SC3-2-u1-X12"},{"t":"색깔이 마음에 드나요?","mis":"SC3-2-u1-X12"}],"explanation":["사람마다 다른 기준은 빼요.","물질의 종류로 나눠요.","철로 이루어져 있나요?예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_basic#7','sci',3,2,'u1','L04','g3_2_sci_u1_L04_basic','lesson_basic','SC3-2-u1-C7',2,'blank','auto','분류는 (    )에 따라 나누어 무리 짓는 것이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u1-X12']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C7","difficulty":2,"kind":"blank","stem":"분류는 (    )에 따라 나누어 무리 짓는 것이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"특징","correct":true},{"t":"기분","mis":"SC3-2-u1-X12"},{"t":"가격","mis":"SC3-2-u1-X12"},{"t":"순서","mis":"SC3-2-u1-X12"}],"explanation":["누가 나누어도 같아야 해요.","물체가 가진 것이에요.","특징이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_basic#8','sci',3,2,'u1','L04','g3_2_sci_u1_L04_basic','lesson_basic','SC3-2-u1-C7',2,'ox','auto','요구르트병은 유리로 분류해요.',ARRAY['SC3-2-u1-X13']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C7","difficulty":2,"kind":"ox","stem":"요구르트병은 유리로 분류해요.","answer":"X","reason_options":[{"t":"가볍고 색깔과 모양이 다양한 플라스틱이기 때문에","correct":true},{"t":"속이 보이는 병은 모두 유리이기 때문에","mis":"SC3-2-u1-X13"}],"mis":"SC3-2-u1-X13","explanation":["요구르트병을 떠올려요.","가벼워요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_basic#9','sci',3,2,'u1','L04','g3_2_sci_u1_L04_basic','lesson_basic','SC3-2-u1-C7',2,'mc','auto','나무로 분류할 물체끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u1-X13']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C7","difficulty":2,"kind":"mc","stem":"나무로 분류할 물체끼리 묶은 것은 무엇인가요?","options":[{"t":"독서대, 야구 방망이","correct":true},{"t":"클립, 용수철","mis":"SC3-2-u1-X13"},{"t":"꽃병, 비커","mis":"SC3-2-u1-X13"},{"t":"탁구공, 플라스틱 바구니","mis":"SC3-2-u1-X13"}],"explanation":["향과 무늬를 떠올려요.","나무 무늬가 있어요.","독서대, 야구 방망이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_basic#10','sci',3,2,'u1','L04','g3_2_sci_u1_L04_basic','lesson_basic','SC3-2-u1-C7',3,'mc','auto','분리배출할 물건 가운데 플라스틱류에 넣을 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u1-X14','SC3-2-u1-X13']::text[],false,'{"seq":10,"concept":"SC3-2-u1-C7","difficulty":3,"kind":"mc","stem":"분리배출할 물건 가운데 플라스틱류에 넣을 것끼리 묶은 것은 무엇인가요?","options":[{"t":"플라스틱 컵, 페트병","correct":true},{"t":"빈 주스 유리병, 빈 철 캔","mis":"SC3-2-u1-X14"},{"t":"빈 주스 유리병, 페트병","mis":"SC3-2-u1-X13"},{"t":"빈 철 캔, 플라스틱 컵","mis":"SC3-2-u1-X13"}],"explanation":["물질의 종류를 봐요.","유리병, 철 캔은 빼요.","플라스틱 컵, 페트병이에요."],"asset":{"type":"passage","lines":["빈 주스 유리병","빈 철 캔","플라스틱 컵","페트병"],"title":"분리배출할 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
