INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_challenge#2','sci',3,2,'u1','L04','g3_2_sci_u1_L04_challenge','lesson_challenge','SC3-2-u1-C7',2,'mc','auto','장난감 블록을 플라스틱으로 분류한 까닭은 무엇인가요?',ARRAY['SC3-2-u1-X09']::text[],false,'{"seq":2,"concept":"SC3-2-u1-C7","difficulty":2,"kind":"mc","stem":"장난감 블록을 플라스틱으로 분류한 까닭은 무엇인가요?","options":[{"t":"가볍고 색깔과 모양이 다양해서","correct":true},{"t":"투명하고 깨지기 쉬워서","mis":"SC3-2-u1-X09"},{"t":"광택이 있고 매우 단단해서","mis":"SC3-2-u1-X09"},{"t":"고유한 향과 무늬가 있어서","mis":"SC3-2-u1-X09"}],"explanation":["플라스틱의 성질이에요.","여러 색깔이에요.","가볍고 다양해서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_challenge#3','sci',3,2,'u1','L04','g3_2_sci_u1_L04_challenge','lesson_challenge','SC3-2-u1-C7',3,'error','auto','분류를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u1-X12','SC3-2-u1-X14','SC3-2-u1-X13']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C7","difficulty":3,"kind":"error","stem":"분류를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「예쁜 것과 안 예쁜 것으로 나누면 물질의 종류로 나눈 거야.」","correct":true,"mis_target":"SC3-2-u1-X12"},{"t":"친구 나 — 「나눈 까닭도 함께 말해야 해.」","mis":"SC3-2-u1-X14"},{"t":"친구 다 — 「비커는 투명하고 깨질 수 있으니 유리야.」","mis":"SC3-2-u1-X13"}],"explanation":["기준을 떠올려요.","예쁜지는 사람마다 달라요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_challenge#4','sci',3,2,'u1','L04','g3_2_sci_u1_L04_challenge','lesson_challenge','SC3-2-u1-C7',3,'mc','auto','친구 가가 나눈 결과에서 잘못 놓인 물체를 바르게 고친 것은 무엇인가요?',ARRAY['SC3-2-u1-X13']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C7","difficulty":3,"kind":"mc","stem":"친구 가가 나눈 결과에서 잘못 놓인 물체를 바르게 고친 것은 무엇인가요?","options":[{"t":"탁구공은 플라스틱 무리로, 비커는 유리 무리로 옮긴다","correct":true},{"t":"북채는 철 무리로, 철 고리는 나무 무리로 옮긴다","mis":"SC3-2-u1-X13"},{"t":"꽃병은 플라스틱 무리로 옮긴다","mis":"SC3-2-u1-X13"},{"t":"고칠 것이 없다","mis":"SC3-2-u1-X13"}],"explanation":["무리마다 성질을 따져요.","탁구공과 비커를 봐요.","두 물체를 바꿔요."],"asset":{"type":"passage","lines":["나무 — 북채, 나무 숟가락","철 — 트라이앵글, 철 고리","유리 — 꽃병, 탁구공","플라스틱 — 비커, 플라스틱 바구니"],"title":"친구 가가 나눈 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_challenge#5','sci',3,2,'u1','L04','g3_2_sci_u1_L04_challenge','lesson_challenge','SC3-2-u1-C7',3,'mc','auto','「유리로 이루어져 있나요?」에서 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u1-X13']::text[],false,'{"seq":5,"concept":"SC3-2-u1-C7","difficulty":3,"kind":"mc","stem":"「유리로 이루어져 있나요?」에서 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"꽃병, 비커, 어항","correct":true},{"t":"꽃병, 탁구공, 어항","mis":"SC3-2-u1-X13"},{"t":"비커, 클립, 어항","mis":"SC3-2-u1-X13"},{"t":"요구르트병, 비커, 꽃병","mis":"SC3-2-u1-X13"}],"explanation":["투명하고 깨질 수 있는 것을 찾아요.","탁구공, 요구르트병은 플라스틱이에요.","꽃병, 비커, 어항이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_challenge#6','sci',3,2,'u1','L04','g3_2_sci_u1_L04_challenge','lesson_challenge','SC3-2-u1-C7',3,'match','auto','물건과 분리배출함을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u1-C7","difficulty":3,"kind":"match","stem":"물건과 분리배출함을 알맞게 이으세요.","pairs":[{"l":"빈 주스 유리병","r":"유리병류"},{"l":"빈 철 캔","r":"캔류"},{"l":"페트병","r":"플라스틱류"}],"mis":"SC3-2-u1-X14","explanation":["물질의 종류대로 넣어요.","유리는 유리병류예요.","철 캔은 캔류, 페트병은 플라스틱류예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_challenge#7','sci',3,2,'u1','L04','g3_2_sci_u1_L04_challenge','lesson_challenge','SC3-2-u1-C7',3,'mc','auto','같은 물질로 된 물체끼리 묶이지 않은 것은 무엇인가요?',ARRAY['SC3-2-u1-X13']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C7","difficulty":3,"kind":"mc","stem":"같은 물질로 된 물체끼리 묶이지 않은 것은 무엇인가요?","options":[{"t":"용수철, 독서대","correct":true},{"t":"클립, 철 고리","mis":"SC3-2-u1-X13"},{"t":"꽃병, 어항","mis":"SC3-2-u1-X13"},{"t":"탁구공, 물뿌리개","mis":"SC3-2-u1-X13"}],"explanation":["묶음마다 물질을 따져요.","용수철은 철이에요.","독서대는 나무라서 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_challenge#8','sci',3,2,'u1','L04','g3_2_sci_u1_L04_challenge','lesson_challenge','SC3-2-u1-C7',4,'mc','auto','색깔로 나누었더니 빨간 플라스틱 바구니와 빨간 철 캔이 한 무리가 되었어요. 알맞은 생각은 무엇인가요?',ARRAY['SC3-2-u1-X12','SC3-2-u1-X14']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C7","difficulty":4,"kind":"mc","stem":"색깔로 나누었더니 빨간 플라스틱 바구니와 빨간 철 캔이 한 무리가 되었어요. 알맞은 생각은 무엇인가요?","options":[{"t":"색깔로 나누면 물질의 종류로 나눈 것이 아니므로 물질의 성질을 바탕으로 다시 나눈다","correct":true},{"t":"같은 빨간색이니 같은 물질이다","mis":"SC3-2-u1-X12"},{"t":"색깔로 나누는 것이 물질의 종류로 나누는 방법이다","mis":"SC3-2-u1-X12"},{"t":"까닭은 말하지 않고 그대로 둔다","mis":"SC3-2-u1-X14"}],"explanation":["바구니와 캔의 물질을 봐요.","플라스틱과 철이에요.","성질로 다시 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_challenge#9','sci',3,2,'u1','L04','g3_2_sci_u1_L04_challenge','lesson_challenge','SC3-2-u1-C7',4,'mc','auto','「광택이 있고 단단한가요?」로 나눌 때 ⭕ 무리를 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X09']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C7","difficulty":4,"kind":"mc","stem":"「광택이 있고 단단한가요?」로 나눌 때 ⭕ 무리를 알맞게 말한 것은 무엇인가요?","options":[{"t":"트라이앵글, 클립처럼 철로 된 물체가 모인다","correct":true},{"t":"꽃병, 비커처럼 유리로 된 물체가 모인다","mis":"SC3-2-u1-X09"},{"t":"북채, 독서대처럼 나무로 된 물체가 모인다","mis":"SC3-2-u1-X09"},{"t":"탁구공, 바구니처럼 플라스틱으로 된 물체가 모인다","mis":"SC3-2-u1-X09"}],"explanation":["광택은 어느 물질일까요?","철이 반짝여요.","철로 된 물체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L04_challenge#10','sci',3,2,'u1','L04','g3_2_sci_u1_L04_challenge','lesson_challenge','SC3-2-u1-C7',4,'essay','teacher','북채, 클립, 비커, 탁구공을 물질의 종류에 따라 분류하고, 그렇게 분류한 까닭을 물질의 성질로 쓰세요. 누가 나누어도 같은 기준이 왜 필요한지도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u1-C7","difficulty":4,"kind":"essay","stem":"북채, 클립, 비커, 탁구공을 물질의 종류에 따라 분류하고, 그렇게 분류한 까닭을 물질의 성질로 쓰세요. 누가 나누어도 같은 기준이 왜 필요한지도 쓰세요.","answer_guide":{"answer":"예: 북채는 나무 — 고유한 향과 무늬가 있다. 클립은 철 — 광택이 있고 단단하다. 비커는 유리 — 투명하고 깨질 수 있다. 탁구공은 플라스틱 — 가볍고 색깔과 모양이 다양하다. 「예쁜가?」처럼 사람마다 다른 기준으로 나누면 결과가 달라지므로, 누가 나누어도 같은 결과가 나오는 기준이 필요하다.","scoring_points":["네 물체를 바르게 분류했는가","까닭을 물질의 성질로 썼는가","누가 나누어도 같은 기준이 필요한 까닭을 썼는가"]},"explanation":["물질별로 나눠요.","성질로 까닭을 써요.","기준을 설명해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_basic#1','sci',3,2,'u1','L05','g3_2_sci_u1_L05_basic','lesson_basic','SC3-2-u1-C8',1,'mc','auto','담는 용기에 관계없이 모양과 부피가 변하지 않는 물질의 상태는 무엇인가요?',ARRAY['SC3-2-u1-X16','SC3-2-u1-X01','SC3-2-u1-X15']::text[],false,'{"seq":1,"concept":"SC3-2-u1-C8","difficulty":1,"kind":"mc","stem":"담는 용기에 관계없이 모양과 부피가 변하지 않는 물질의 상태는 무엇인가요?","options":[{"t":"고체","correct":true},{"t":"액체","mis":"SC3-2-u1-X16"},{"t":"물체","mis":"SC3-2-u1-X01"},{"t":"부피","mis":"SC3-2-u1-X15"}],"explanation":["나무 블록을 떠올려요.","모양과 부피가 그대로예요.","고체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_basic#2','sci',3,2,'u1','L05','g3_2_sci_u1_L05_basic','lesson_basic','SC3-2-u1-C8',1,'sa','auto','물질이 차지하는 공간의 크기를 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u1-C8","difficulty":1,"kind":"sa","stem":"물질이 차지하는 공간의 크기를 두 글자로 쓰세요.","answer":["부피"],"explanation":["공간의 크기예요.","부◯예요.","부피예요."],"mis":"SC3-2-u1-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_basic#3','sci',3,2,'u1','L05','g3_2_sci_u1_L05_basic','lesson_basic','SC3-2-u1-C9',1,'ox','auto','물은 담는 용기에 따라 모양이 변해요.',ARRAY['SC3-2-u1-X20']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C9","difficulty":1,"kind":"ox","stem":"물은 담는 용기에 따라 모양이 변해요.","answer":"O","reason_options":[{"t":"물은 흐르는 성질이 있어 용기 모양을 따라 변하기 때문에","correct":true},{"t":"물은 어디에 담아도 모양이 그대로이기 때문에","mis":"SC3-2-u1-X20"}],"mis":"SC3-2-u1-X20","explanation":["물을 컵에 부어요.","컵 모양이 돼요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_basic#4','sci',3,2,'u1','L05','g3_2_sci_u1_L05_basic','lesson_basic','SC3-2-u1-C8',1,'mc','auto','고체인 것은 무엇인가요?',ARRAY['SC3-2-u1-X30']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C8","difficulty":1,"kind":"mc","stem":"고체인 것은 무엇인가요?","options":[{"t":"지우개","correct":true},{"t":"간장","mis":"SC3-2-u1-X30"},{"t":"우유","mis":"SC3-2-u1-X30"},{"t":"주스","mis":"SC3-2-u1-X30"}],"explanation":["손으로 잡을 수 있나요?","모양이 그대로예요.","지우개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_basic#5','sci',3,2,'u1','L05','g3_2_sci_u1_L05_basic','lesson_basic','SC3-2-u1-C9',2,'match','auto','설명과 알맞은 낱말을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u1-C9","difficulty":2,"kind":"match","stem":"설명과 알맞은 낱말을 이으세요.","pairs":[{"l":"용기가 바뀌어도 모양과 부피가 그대로","r":"고체"},{"l":"용기에 따라 모양은 변하고 부피는 그대로","r":"액체"},{"l":"물질이 차지하는 공간의 크기","r":"부피"}],"mis":"SC3-2-u1-X30","explanation":["나무 블록은 고체예요.","물은 액체예요.","공간의 크기는 부피예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_basic#6','sci',3,2,'u1','L05','g3_2_sci_u1_L05_basic','lesson_basic','SC3-2-u1-C9',2,'mc','auto','물을 여러 모양의 용기에 옮겨 담을 때 변하지 않는 것은 무엇인가요?',ARRAY['SC3-2-u1-X19','SC3-2-u1-X15']::text[],false,'{"seq":6,"concept":"SC3-2-u1-C9","difficulty":2,"kind":"mc","stem":"물을 여러 모양의 용기에 옮겨 담을 때 변하지 않는 것은 무엇인가요?","options":[{"t":"물의 부피","correct":true},{"t":"물의 모양","mis":"SC3-2-u1-X19"},{"t":"물이 담긴 높이","mis":"SC3-2-u1-X19"},{"t":"물을 담은 용기의 모양","mis":"SC3-2-u1-X15"}],"explanation":["처음 용기에 다시 부었어요.","높이가 같았어요.","부피는 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_basic#7','sci',3,2,'u1','L05','g3_2_sci_u1_L05_basic','lesson_basic','SC3-2-u1-C9',2,'blank','auto','액체는 (    ) 성질이 있어 손으로 잡을 수 없어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u1-X20']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C9","difficulty":2,"kind":"blank","stem":"액체는 (    ) 성질이 있어 손으로 잡을 수 없어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"흐르는","correct":true},{"t":"단단한","mis":"SC3-2-u1-X20"},{"t":"반짝이는","mis":"SC3-2-u1-X20"},{"t":"모양이 그대로인","mis":"SC3-2-u1-X20"}],"explanation":["물을 떠올려요.","손가락 사이로 빠져나가요.","흐르는 성질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_basic#8','sci',3,2,'u1','L05','g3_2_sci_u1_L05_basic','lesson_basic','SC3-2-u1-C8',2,'ox','auto','고체는 모두 단단해요.',ARRAY['SC3-2-u1-X17']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C8","difficulty":2,"kind":"ox","stem":"고체는 모두 단단해요.","answer":"X","reason_options":[{"t":"종이나 스펀지처럼 단단하지 않은 고체도 있기 때문에","correct":true},{"t":"손으로 잡을 수 있는 것은 모두 단단하기 때문에","mis":"SC3-2-u1-X17"}],"mis":"SC3-2-u1-X17","explanation":["스펀지를 떠올려요.","눌려도 고체예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_basic#9','sci',3,2,'u1','L05','g3_2_sci_u1_L05_basic','lesson_basic','SC3-2-u1-C9',2,'mc','auto','옮겨 담은 물의 부피가 변했는지 알아보는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u1-X19','SC3-2-u1-X15']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C9","difficulty":2,"kind":"mc","stem":"옮겨 담은 물의 부피가 변했는지 알아보는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"처음 용기에 다시 부어 처음 표시한 높이와 비교한다","correct":true},{"t":"넓은 그릇에 담긴 물의 높이만 본다","mis":"SC3-2-u1-X19"},{"t":"물의 색깔을 본다","mis":"SC3-2-u1-X15"},{"t":"옮겨 담은 용기의 모양만 본다","mis":"SC3-2-u1-X19"}],"explanation":["처음 높이를 표시했어요.","다시 부어요.","높이를 비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_basic#10','sci',3,2,'u1','L05','g3_2_sci_u1_L05_basic','lesson_basic','SC3-2-u1-C8',3,'mc','auto','모래를 여러 모양의 컵에 부으면 모양이 변해요. 모래에 대해 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X18']::text[],false,'{"seq":10,"concept":"SC3-2-u1-C8","difficulty":3,"kind":"mc","stem":"모래를 여러 모양의 컵에 부으면 모양이 변해요. 모래에 대해 알맞게 말한 것은 무엇인가요?","options":[{"t":"알갱이 하나하나의 모양과 부피가 변하지 않으므로 고체이다","correct":true},{"t":"모양이 변하니까 액체이다","mis":"SC3-2-u1-X18"},{"t":"고체도 액체도 아니다","mis":"SC3-2-u1-X18"},{"t":"손으로 잡을 수 없으니 액체이다","mis":"SC3-2-u1-X18"}],"explanation":["알갱이 하나를 들여다봐요.","하나하나는 그대로예요.","고체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_challenge#1','sci',3,2,'u1','L05','g3_2_sci_u1_L05_challenge','lesson_challenge','SC3-2-u1-C9',2,'sa','auto','우유, 간장, 주스처럼 흐르는 성질이 있는 물질의 상태를 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u1-C9","difficulty":2,"kind":"sa","stem":"우유, 간장, 주스처럼 흐르는 성질이 있는 물질의 상태를 두 글자로 쓰세요.","answer":["액체"],"explanation":["흘러요.","손으로 잡을 수 없어요.","액체예요."],"mis":"SC3-2-u1-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_challenge#2','sci',3,2,'u1','L05','g3_2_sci_u1_L05_challenge','lesson_challenge','SC3-2-u1-C8',2,'mc','auto','나무 블록을 둥근 컵에서 네모 통으로 옮겼을 때 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u1-X16']::text[],false,'{"seq":2,"concept":"SC3-2-u1-C8","difficulty":2,"kind":"mc","stem":"나무 블록을 둥근 컵에서 네모 통으로 옮겼을 때 알맞은 것은 무엇인가요?","options":[{"t":"모양과 크기가 그대로다","correct":true},{"t":"네모 통 모양으로 변한다","mis":"SC3-2-u1-X16"},{"t":"크기가 커진다","mis":"SC3-2-u1-X16"},{"t":"흘러내린다","mis":"SC3-2-u1-X16"}],"explanation":["나무 블록은 고체예요.","용기가 바뀌어도 그대로예요.","모양과 크기가 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_challenge#3','sci',3,2,'u1','L05','g3_2_sci_u1_L05_challenge','lesson_challenge','SC3-2-u1-C9',3,'error','auto','물 옮겨 담기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u1-X19']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C9","difficulty":3,"kind":"error","stem":"물 옮겨 담기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「길쭉한 병에서 물이 높아졌으니 물의 부피가 늘어났어.」","correct":true,"mis_target":"SC3-2-u1-X19"},{"t":"친구 나 — 「넓은 그릇에서는 낮아 보일 뿐이야.」","mis":"SC3-2-u1-X19"},{"t":"친구 다 — 「처음 용기에 다시 부으면 높이가 같아.」","mis":"SC3-2-u1-X19"}],"explanation":["높아 보이는 것을 떠올려요.","다시 부으면 같아요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_challenge#4','sci',3,2,'u1','L05','g3_2_sci_u1_L05_challenge','lesson_challenge','SC3-2-u1-C9',3,'mc','auto','기록 ④로 알 수 있는 것은 무엇인가요?',ARRAY['SC3-2-u1-X19','SC3-2-u1-X20']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C9","difficulty":3,"kind":"mc","stem":"기록 ④로 알 수 있는 것은 무엇인가요?","options":[{"t":"액체는 담는 용기에 따라 모양이 변해도 부피는 변하지 않는다","correct":true},{"t":"액체는 담는 용기에 따라 부피도 변한다","mis":"SC3-2-u1-X19"},{"t":"액체는 어디에 담아도 모양이 그대로다","mis":"SC3-2-u1-X20"},{"t":"넓은 그릇에 담으면 물이 줄어든다","mis":"SC3-2-u1-X19"}],"explanation":["④를 읽어요.","처음 높이와 같아요.","부피는 그대로예요."],"asset":{"type":"passage","lines":["① 처음 용기에 담긴 물의 높이를 유성펜으로 표시해요.","② 물을 넓은 그릇에 옮기니 높이가 낮아 보여요.","③ 물을 길쭉한 병에 옮기니 높이가 높아 보여요.","④ 처음 용기에 다시 부으니 처음 표시한 높이와 같아요."],"title":"물 옮겨 담기 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_challenge#5','sci',3,2,'u1','L05','g3_2_sci_u1_L05_challenge','lesson_challenge','SC3-2-u1-C8',3,'mc','auto','고체끼리만 묶은 것은 무엇인가요?',ARRAY['SC3-2-u1-X30','SC3-2-u1-X17']::text[],false,'{"seq":5,"concept":"SC3-2-u1-C8","difficulty":3,"kind":"mc","stem":"고체끼리만 묶은 것은 무엇인가요?","options":[{"t":"종이, 스펀지, 찌그러진 페트병","correct":true},{"t":"종이, 주스, 스펀지","mis":"SC3-2-u1-X30"},{"t":"우유, 간장, 참기름","mis":"SC3-2-u1-X30"},{"t":"스펀지, 물, 연필","mis":"SC3-2-u1-X17"}],"explanation":["단단하지 않아도 고체예요.","용기에 따라 모양이 변하지 않아요.","종이, 스펀지, 페트병이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_challenge#6','sci',3,2,'u1','L05','g3_2_sci_u1_L05_challenge','lesson_challenge','SC3-2-u1-C9',3,'match','auto','물을 옮겨 담은 곳과 보이는 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u1-C9","difficulty":3,"kind":"match","stem":"물을 옮겨 담은 곳과 보이는 모습을 알맞게 이으세요.","pairs":[{"l":"넓은 그릇","r":"높이가 낮아 보여요"},{"l":"길쭉한 병","r":"높이가 높아 보여요"},{"l":"처음 용기에 다시 부음","r":"처음 높이와 같아요"}],"mis":"SC3-2-u1-X19","explanation":["넓으면 낮아 보여요.","좁으면 높아 보여요.","다시 부으면 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_challenge#7','sci',3,2,'u1','L05','g3_2_sci_u1_L05_challenge','lesson_challenge','SC3-2-u1-C8',3,'mc','auto','고체와 액체에 모두 해당하는 것은 무엇인가요?',ARRAY['SC3-2-u1-X20','SC3-2-u1-X16']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C8","difficulty":3,"kind":"mc","stem":"고체와 액체에 모두 해당하는 것은 무엇인가요?","options":[{"t":"눈으로 볼 수 있다","correct":true},{"t":"손으로 잡을 수 있다","mis":"SC3-2-u1-X20"},{"t":"담는 용기에 관계없이 모양이 그대로다","mis":"SC3-2-u1-X16"},{"t":"흐르는 성질이 있다","mis":"SC3-2-u1-X16"}],"explanation":["나무 블록과 물을 견줘요.","둘 다 보여요.","눈으로 볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_challenge#8','sci',3,2,'u1','L05','g3_2_sci_u1_L05_challenge','lesson_challenge','SC3-2-u1-C9',4,'mc','auto','구불구불한 빨대로 주스를 마실 수 있는 까닭은 무엇인가요?',ARRAY['SC3-2-u1-X30','SC3-2-u1-X19','SC3-2-u1-X16']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C9","difficulty":4,"kind":"mc","stem":"구불구불한 빨대로 주스를 마실 수 있는 까닭은 무엇인가요?","options":[{"t":"주스는 액체라서 빨대 모양을 따라 모양이 변하며 올라오기 때문","correct":true},{"t":"주스는 고체라서 모양이 그대로이기 때문","mis":"SC3-2-u1-X30"},{"t":"빨대 속에서 주스의 부피가 줄어들기 때문","mis":"SC3-2-u1-X19"},{"t":"빨대가 주스 모양을 따라 변하기 때문","mis":"SC3-2-u1-X16"}],"explanation":["주스는 액체예요.","모양이 변해요.","빨대 모양을 따라 올라와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_challenge#9','sci',3,2,'u1','L05','g3_2_sci_u1_L05_challenge','lesson_challenge','SC3-2-u1-C8',4,'mc','auto','어떤 물질이 고체인지 액체인지 알아보려고 할 때 가장 알맞은 질문은 무엇인가요?',ARRAY['SC3-2-u1-X17','SC3-2-u1-X08','SC3-2-u1-X09']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C8","difficulty":4,"kind":"mc","stem":"어떤 물질이 고체인지 액체인지 알아보려고 할 때 가장 알맞은 질문은 무엇인가요?","options":[{"t":"담는 용기에 따라 모양이 변하나요?","correct":true},{"t":"단단한가요?","mis":"SC3-2-u1-X17"},{"t":"무거운가요?","mis":"SC3-2-u1-X08"},{"t":"반짝이나요?","mis":"SC3-2-u1-X09"}],"explanation":["고체와 액체가 다른 점을 찾아요.","모양이 변하는지예요.","용기에 따라 모양이 변하나요?예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L05_challenge#10','sci',3,2,'u1','L05','g3_2_sci_u1_L05_challenge','lesson_challenge','SC3-2-u1-C9',4,'essay','teacher','물을 넓은 그릇과 길쭉한 병에 옮겨 담았더니 높이가 달라 보였어요. 물의 부피가 변했는지 알아보는 방법과 그 결과를 쓰고, 액체의 성질을 고체와 견주어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u1-C9","difficulty":4,"kind":"essay","stem":"물을 넓은 그릇과 길쭉한 병에 옮겨 담았더니 높이가 달라 보였어요. 물의 부피가 변했는지 알아보는 방법과 그 결과를 쓰고, 액체의 성질을 고체와 견주어 쓰세요.","answer_guide":{"answer":"예: 처음 용기에 담긴 물의 높이를 유성펜으로 표시한 뒤, 옮겨 담았던 물을 처음 용기에 다시 부어 높이를 비교한다. 처음 표시한 높이와 같으므로 물의 부피는 변하지 않았다. 고체는 담는 용기에 관계없이 모양과 부피가 그대로이지만, 액체는 담는 용기에 따라 모양은 변하고 부피는 변하지 않는다.","scoring_points":["처음 용기에 다시 부어 비교하는 방법을 썼는가","부피가 변하지 않았다는 결과를 썼는가","액체와 고체의 성질을 견주어 썼는가"]},"explanation":["방법을 써요.","결과를 써요.","고체와 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_basic#1','sci',3,2,'u1','L06','g3_2_sci_u1_L06_basic','lesson_basic','SC3-2-u1-C11',1,'mc','auto','담는 용기에 따라 모양이 변하고 그 공간을 가득 채우는 물질의 상태는 무엇인가요?',ARRAY['SC3-2-u1-X30','SC3-2-u1-X15']::text[],false,'{"seq":1,"concept":"SC3-2-u1-C11","difficulty":1,"kind":"mc","stem":"담는 용기에 따라 모양이 변하고 그 공간을 가득 채우는 물질의 상태는 무엇인가요?","options":[{"t":"기체","correct":true},{"t":"고체","mis":"SC3-2-u1-X30"},{"t":"액체","mis":"SC3-2-u1-X30"},{"t":"부피","mis":"SC3-2-u1-X15"}],"explanation":["풍선 속 공기를 떠올려요.","공간을 가득 채워요.","기체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_basic#2','sci',3,2,'u1','L06','g3_2_sci_u1_L06_basic','lesson_basic','SC3-2-u1-C11',1,'sa','auto','풍선이나 축구공에 넣는 기체를 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u1-C11","difficulty":1,"kind":"sa","stem":"풍선이나 축구공에 넣는 기체를 두 글자로 쓰세요.","answer":["공기"],"explanation":["보이지 않아요.","숨 쉴 때도 있어요.","공기예요."],"mis":"SC3-2-u1-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_basic#3','sci',3,2,'u1','L06','g3_2_sci_u1_L06_basic','lesson_basic','SC3-2-u1-C10',1,'ox','auto','공기는 눈에 보이지 않지만 공간을 차지해요.',ARRAY['SC3-2-u1-X21']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C10","difficulty":1,"kind":"ox","stem":"공기는 눈에 보이지 않지만 공간을 차지해요.","answer":"O","reason_options":[{"t":"페트병 속 공기가 물을 밀어냈기 때문에","correct":true},{"t":"보이지 않는 것은 공간을 차지할 수 없기 때문에","mis":"SC3-2-u1-X21"}],"mis":"SC3-2-u1-X21","explanation":["탁구공 실험을 떠올려요.","물을 밀어냈어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_basic#4','sci',3,2,'u1','L06','g3_2_sci_u1_L06_basic','lesson_basic','SC3-2-u1-C11',1,'mc','auto','공기를 빼내어 쓰는 물체는 무엇인가요?',ARRAY['SC3-2-u1-X26']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C11","difficulty":1,"kind":"mc","stem":"공기를 빼내어 쓰는 물체는 무엇인가요?","options":[{"t":"이불 압축 팩","correct":true},{"t":"튜브","mis":"SC3-2-u1-X26"},{"t":"고무보트","mis":"SC3-2-u1-X26"},{"t":"바람 인형","mis":"SC3-2-u1-X26"}],"explanation":["부피를 줄여요.","공기를 빼요.","이불 압축 팩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_basic#5','sci',3,2,'u1','L06','g3_2_sci_u1_L06_basic','lesson_basic','SC3-2-u1-C10',2,'match','auto','탁구공 실험의 과정과 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u1-C10","difficulty":2,"kind":"match","stem":"탁구공 실험의 과정과 결과를 알맞게 이으세요.","pairs":[{"l":"처음","r":"물의 높이를 유성펜으로 표시해요"},{"l":"페트병을 바닥까지 밀어 넣음","r":"물 높이가 처음보다 높아져요"},{"l":"페트병 뚜껑을 엶","r":"물 높이가 처음과 같아져요"}],"mis":"SC3-2-u1-X22","explanation":["먼저 표시해요.","밀어 넣으면 높아져요.","뚜껑을 열면 처음과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_basic#6','sci',3,2,'u1','L06','g3_2_sci_u1_L06_basic','lesson_basic','SC3-2-u1-C10',2,'mc','auto','뚜껑을 닫은 페트병을 수조 바닥까지 밀어 넣으면 탁구공은 어떻게 되나요?',ARRAY['SC3-2-u1-X22']::text[],false,'{"seq":6,"concept":"SC3-2-u1-C10","difficulty":2,"kind":"mc","stem":"뚜껑을 닫은 페트병을 수조 바닥까지 밀어 넣으면 탁구공은 어떻게 되나요?","options":[{"t":"수조 바닥 쪽으로 내려간다","correct":true},{"t":"물 위로 더 높이 떠오른다","mis":"SC3-2-u1-X22"},{"t":"처음 자리에 그대로 있다","mis":"SC3-2-u1-X22"},{"t":"페트병 밖으로 튀어나온다","mis":"SC3-2-u1-X22"}],"explanation":["페트병 속에 공기가 있어요.","공기가 물을 밀어내요.","바닥 쪽으로 내려가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_basic#7','sci',3,2,'u1','L06','g3_2_sci_u1_L06_basic','lesson_basic','SC3-2-u1-C11',2,'blank','auto','기체는 담는 용기에 따라 모양이 변하고, 그 (    )을 가득 채워요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u1-X25']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C11","difficulty":2,"kind":"blank","stem":"기체는 담는 용기에 따라 모양이 변하고, 그 (    )을 가득 채워요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"공간","correct":true},{"t":"바닥","mis":"SC3-2-u1-X25"},{"t":"절반","mis":"SC3-2-u1-X25"},{"t":"입구","mis":"SC3-2-u1-X25"}],"explanation":["풍선을 떠올려요.","안을 가득 채워요.","공간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_basic#8','sci',3,2,'u1','L06','g3_2_sci_u1_L06_basic','lesson_basic','SC3-2-u1-C11',2,'ox','auto','기체와 공기는 같은 말이에요.',ARRAY['SC3-2-u1-X24']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C11","difficulty":2,"kind":"ox","stem":"기체와 공기는 같은 말이에요.","answer":"X","reason_options":[{"t":"기체는 물질의 상태이고 공기는 기체의 한 가지이기 때문에","correct":true},{"t":"공기 말고 다른 기체는 없기 때문에","mis":"SC3-2-u1-X24"}],"mis":"SC3-2-u1-X24","explanation":["기체는 상태예요.","공기는 그 가운데 하나예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_basic#9','sci',3,2,'u1','L06','g3_2_sci_u1_L06_basic','lesson_basic','SC3-2-u1-C10',2,'mc','auto','페트병의 잘린 부분을 절연 테이프로 감싸는 까닭은 무엇인가요?',ARRAY['SC3-2-u1-X23']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C10","difficulty":2,"kind":"mc","stem":"페트병의 잘린 부분을 절연 테이프로 감싸는 까닭은 무엇인가요?","options":[{"t":"잘린 부분에 다치지 않으려고","correct":true},{"t":"공기가 더 잘 들어가게 하려고","mis":"SC3-2-u1-X23"},{"t":"페트병을 무겁게 하려고","mis":"SC3-2-u1-X23"},{"t":"물의 높이를 표시하려고","mis":"SC3-2-u1-X23"}],"explanation":["잘린 부분은 날카로워요.","손을 보호해요.","다치지 않으려고예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_basic#10','sci',3,2,'u1','L06','g3_2_sci_u1_L06_basic','lesson_basic','SC3-2-u1-C11',3,'mc','auto','지퍼 백에 구멍이 났는지 알아보는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u1-X26']::text[],false,'{"seq":10,"concept":"SC3-2-u1-C11","difficulty":3,"kind":"mc","stem":"지퍼 백에 구멍이 났는지 알아보는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"공기를 넣었을 때 부풀지 않으면 구멍이 난 것이다","correct":true},{"t":"지퍼 백을 물에 담가 둔다","mis":"SC3-2-u1-X26"},{"t":"지퍼 백의 색깔을 살펴본다","mis":"SC3-2-u1-X26"},{"t":"지퍼 백을 접어 본다","mis":"SC3-2-u1-X26"}],"explanation":["공기는 공간을 차지해요.","구멍이 있으면 새어 나가요.","부풀지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_challenge#1','sci',3,2,'u1','L06','g3_2_sci_u1_L06_challenge','lesson_challenge','SC3-2-u1-C11',2,'sa','auto','담는 용기에 따라 모양이 변하고 그 공간을 가득 채우는 물질의 상태를 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u1-C11","difficulty":2,"kind":"sa","stem":"담는 용기에 따라 모양이 변하고 그 공간을 가득 채우는 물질의 상태를 두 글자로 쓰세요.","answer":["기체"],"explanation":["풍선 속을 채워요.","기◯예요.","기체예요."],"mis":"SC3-2-u1-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_challenge#2','sci',3,2,'u1','L06','g3_2_sci_u1_L06_challenge','lesson_challenge','SC3-2-u1-C10',2,'mc','auto','바닥까지 밀어 넣은 페트병의 뚜껑을 열면 탁구공은 어떻게 되나요?',ARRAY['SC3-2-u1-X22']::text[],false,'{"seq":2,"concept":"SC3-2-u1-C10","difficulty":2,"kind":"mc","stem":"바닥까지 밀어 넣은 페트병의 뚜껑을 열면 탁구공은 어떻게 되나요?","options":[{"t":"떠올라 처음 위치와 같아진다","correct":true},{"t":"바닥에 그대로 있다","mis":"SC3-2-u1-X22"},{"t":"더 깊이 내려간다","mis":"SC3-2-u1-X22"},{"t":"페트병 안에서 사라진다","mis":"SC3-2-u1-X22"}],"explanation":["뚜껑을 열면 공기가 빠져나가요.","물이 들어와요.","처음 위치로 떠올라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_challenge#3','sci',3,2,'u1','L06','g3_2_sci_u1_L06_challenge','lesson_challenge','SC3-2-u1-C10',3,'error','auto','탁구공 실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u1-X22','SC3-2-u1-X21']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C10","difficulty":3,"kind":"error","stem":"탁구공 실험을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「뚜껑을 열면 공기가 더 들어와서 물을 밀어내.」","correct":true,"mis_target":"SC3-2-u1-X22"},{"t":"친구 나 — 「뚜껑을 닫으면 페트병 속 공기가 물을 밀어내.」","mis":"SC3-2-u1-X22"},{"t":"친구 다 — 「공기는 보이지 않아도 공간을 차지해.」","mis":"SC3-2-u1-X21"}],"explanation":["뚜껑을 열면 어떻게 될까요?","공기가 빠져나가요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_challenge#4','sci',3,2,'u1','L06','g3_2_sci_u1_L06_challenge','lesson_challenge','SC3-2-u1-C10',3,'mc','auto','③에서 물 높이가 처음보다 높아진 까닭은 무엇인가요?',ARRAY['SC3-2-u1-X22','SC3-2-u1-X21','SC3-2-u1-X23']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C10","difficulty":3,"kind":"mc","stem":"③에서 물 높이가 처음보다 높아진 까닭은 무엇인가요?","options":[{"t":"페트병 속 공기가 공간을 차지해 물을 밀어냈기 때문에","correct":true},{"t":"탁구공이 물을 빨아들였기 때문에","mis":"SC3-2-u1-X22"},{"t":"공기는 공간을 차지하지 않기 때문에","mis":"SC3-2-u1-X21"},{"t":"페트병 뚜껑이 열려 있었기 때문에","mis":"SC3-2-u1-X23"}],"explanation":["페트병 속을 떠올려요.","공기가 있어요.","공기가 물을 밀어냈어요."],"asset":{"type":"passage","lines":["① 수조에 담긴 물의 높이를 유성펜으로 표시해요.","② 물 위에 탁구공을 띄우고, 뚜껑을 닫은 페트병으로 덮어요.","③ 페트병을 수조 바닥까지 천천히 밀어 넣어요.","④ 페트병의 뚜껑을 천천히 열어요."],"title":"탁구공 페트병 실험 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_challenge#5','sci',3,2,'u1','L06','g3_2_sci_u1_L06_challenge','lesson_challenge','SC3-2-u1-C11',3,'mc','auto','실험에 나온 것의 상태를 바르게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X30']::text[],false,'{"seq":5,"concept":"SC3-2-u1-C11","difficulty":3,"kind":"mc","stem":"실험에 나온 것의 상태를 바르게 말한 것은 무엇인가요?","options":[{"t":"탁구공 — 고체 · 수조의 물 — 액체 · 페트병 속 공기 — 기체","correct":true},{"t":"탁구공 — 기체 · 수조의 물 — 고체 · 페트병 속 공기 — 액체","mis":"SC3-2-u1-X30"},{"t":"탁구공 — 고체 · 수조의 물 — 액체 · 페트병 속 공기 — 고체","mis":"SC3-2-u1-X30"},{"t":"모두 고체","mis":"SC3-2-u1-X30"}],"explanation":["하나씩 따져요.","공기는 보이지 않아요.","고체, 액체, 기체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_challenge#6','sci',3,2,'u1','L06','g3_2_sci_u1_L06_challenge','lesson_challenge','SC3-2-u1-C11',3,'match','auto','물체와 공기를 쓰는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u1-C11","difficulty":3,"kind":"match","stem":"물체와 공기를 쓰는 방법을 알맞게 이으세요.","pairs":[{"l":"튜브","r":"공기를 넣어 물에 뜨게 해요"},{"l":"이불 압축 팩","r":"공기를 빼서 부피를 줄여요"},{"l":"축구공","r":"공기를 넣어 통통 튀게 해요"}],"mis":"SC3-2-u1-X26","explanation":["공기를 넣는 것과 빼는 것이에요.","압축 팩은 빼요.","튜브, 축구공은 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_challenge#7','sci',3,2,'u1','L06','g3_2_sci_u1_L06_challenge','lesson_challenge','SC3-2-u1-C11',3,'mc','auto','별 모양 풍선에 공기를 넣으면 어떻게 되나요?',ARRAY['SC3-2-u1-X25']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C11","difficulty":3,"kind":"mc","stem":"별 모양 풍선에 공기를 넣으면 어떻게 되나요?","options":[{"t":"별 모양으로 부풀어 오른다","correct":true},{"t":"둥근 모양으로 부풀어 오른다","mis":"SC3-2-u1-X25"},{"t":"공기가 한쪽에만 모인다","mis":"SC3-2-u1-X25"},{"t":"모양이 변하지 않는다","mis":"SC3-2-u1-X25"}],"explanation":["기체는 용기 모양을 따라요.","풍선이 용기예요.","별 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_challenge#8','sci',3,2,'u1','L06','g3_2_sci_u1_L06_challenge','lesson_challenge','SC3-2-u1-C10',4,'mc','auto','뚜껑을 연 채로 페트병을 탁구공 위에 덮어 바닥까지 밀어 넣으면 어떻게 될까요?',ARRAY['SC3-2-u1-X23','SC3-2-u1-X22','SC3-2-u1-X21']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C10","difficulty":4,"kind":"mc","stem":"뚜껑을 연 채로 페트병을 탁구공 위에 덮어 바닥까지 밀어 넣으면 어떻게 될까요?","options":[{"t":"공기가 빠져나가 물이 페트병 안으로 들어오고 탁구공은 내려가지 않는다","correct":true},{"t":"뚜껑을 닫았을 때와 똑같이 탁구공이 바닥 쪽으로 내려간다","mis":"SC3-2-u1-X23"},{"t":"물 높이가 뚜껑을 닫았을 때보다 더 높아진다","mis":"SC3-2-u1-X22"},{"t":"공기는 없으니 아무 일도 일어나지 않는다","mis":"SC3-2-u1-X21"}],"explanation":["뚜껑이 열려 있어요.","공기가 빠져나가요.","물이 들어와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_challenge#9','sci',3,2,'u1','L06','g3_2_sci_u1_L06_challenge','lesson_challenge','SC3-2-u1-C11',4,'mc','auto','공기가 공간을 차지하는 성질을 이용해 공기를 넣어 쓰는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u1-X26']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C11","difficulty":4,"kind":"mc","stem":"공기가 공간을 차지하는 성질을 이용해 공기를 넣어 쓰는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"튜브, 고무보트, 공기 미끄럼틀","correct":true},{"t":"튜브, 이불 압축 팩, 고무보트","mis":"SC3-2-u1-X26"},{"t":"유리컵, 나무 숟가락, 튜브","mis":"SC3-2-u1-X26"},{"t":"이불 압축 팩, 철 캔, 공기 미끄럼틀","mis":"SC3-2-u1-X26"}],"explanation":["공기를 넣어 부풀려요.","압축 팩은 빼요.","튜브, 고무보트, 공기 미끄럼틀이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L06_challenge#10','sci',3,2,'u1','L06','g3_2_sci_u1_L06_challenge','lesson_challenge','SC3-2-u1-C10',4,'essay','teacher','탁구공 실험에서 페트병을 밀어 넣었을 때와 뚜껑을 열었을 때의 결과를 쓰고, 이 결과로 알 수 있는 공기의 성질을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u1-C10","difficulty":4,"kind":"essay","stem":"탁구공 실험에서 페트병을 밀어 넣었을 때와 뚜껑을 열었을 때의 결과를 쓰고, 이 결과로 알 수 있는 공기의 성질을 쓰세요.","answer_guide":{"answer":"예: 뚜껑을 닫은 페트병을 바닥까지 밀어 넣으면 탁구공이 바닥 쪽으로 내려가고 수조의 물 높이가 처음보다 높아진다. 뚜껑을 열면 탁구공이 떠올라 처음 위치와 같아지고 물 높이도 처음과 같아진다. 페트병 속 공기가 공간을 차지해 물을 밀어냈으므로, 공기는 눈에 보이지 않지만 공간을 차지한다는 것을 알 수 있다.","scoring_points":["밀어 넣었을 때의 결과를 썼는가","뚜껑을 열었을 때의 결과를 썼는가","공기가 공간을 차지한다는 성질을 썼는가"]},"explanation":["두 결과를 써요.","까닭을 생각해요.","공기의 성질을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L07_basic#1','sci',3,2,'u1','L07','g3_2_sci_u1_L07_basic','lesson_basic','SC3-2-u1-C12',1,'mc','auto','고체, 액체, 기체가 모두 가진 성질은 무엇인가요?',ARRAY['SC3-2-u1-X27']::text[],false,'{"seq":1,"concept":"SC3-2-u1-C12","difficulty":1,"kind":"mc","stem":"고체, 액체, 기체가 모두 가진 성질은 무엇인가요?","options":[{"t":"공간을 차지한다","correct":true},{"t":"손으로 잡을 수 있다","mis":"SC3-2-u1-X27"},{"t":"눈으로 볼 수 없다","mis":"SC3-2-u1-X27"},{"t":"모양이 변하지 않는다","mis":"SC3-2-u1-X27"}],"explanation":["탁구공 실험을 떠올려요.","공기도 공간을 차지했어요.","공간을 차지해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L07_basic#2','sci',3,2,'u1','L07','g3_2_sci_u1_L07_basic','lesson_basic','SC3-2-u1-C12',1,'sa','auto','풍선 속 공기는 고체, 액체, 기체 가운데 무엇인가요?','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u1-C12","difficulty":1,"kind":"sa","stem":"풍선 속 공기는 고체, 액체, 기체 가운데 무엇인가요?","answer":["기체"],"explanation":["보이지 않아요.","풍선을 가득 채워요.","기체예요."],"mis":"SC3-2-u1-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L07_basic#3','sci',3,2,'u1','L07','g3_2_sci_u1_L07_basic','lesson_basic','SC3-2-u1-C12',1,'ox','auto','참기름에는 물이 들어 있지 않지만 액체예요.',ARRAY['SC3-2-u1-X28']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C12","difficulty":1,"kind":"ox","stem":"참기름에는 물이 들어 있지 않지만 액체예요.","answer":"O","reason_options":[{"t":"담는 용기에 따라 모양은 변하고 부피는 변하지 않기 때문에","correct":true},{"t":"물이 들어 있어야만 액체이기 때문에","mis":"SC3-2-u1-X28"}],"mis":"SC3-2-u1-X28","explanation":["참기름을 컵에 부어요.","모양이 변해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L07_basic#4','sci',3,2,'u1','L07','g3_2_sci_u1_L07_basic','lesson_basic','SC3-2-u1-C12',1,'mc','auto','분수대의 물은 어떤 상태인가요?',ARRAY['SC3-2-u1-X30','SC3-2-u1-X01']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C12","difficulty":1,"kind":"mc","stem":"분수대의 물은 어떤 상태인가요?","options":[{"t":"액체","correct":true},{"t":"고체","mis":"SC3-2-u1-X30"},{"t":"기체","mis":"SC3-2-u1-X30"},{"t":"물체","mis":"SC3-2-u1-X01"}],"explanation":["흐르는 성질이 있어요.","모양이 변해요.","액체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L07_basic#5','sci',3,2,'u1','L07','g3_2_sci_u1_L07_basic','lesson_basic','SC3-2-u1-C12',2,'match','auto','상태와 성질을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u1-C12","difficulty":2,"kind":"match","stem":"상태와 성질을 알맞게 이으세요.","pairs":[{"l":"고체","r":"용기에 관계없이 모양이 그대로예요"},{"l":"액체","r":"모양은 변하고 부피는 그대로예요"},{"l":"기체","r":"공간을 가득 채우고 모양이 변해요"}],"mis":"SC3-2-u1-X30","explanation":["나무 블록, 물, 공기를 떠올려요.","고체는 그대로예요.","기체는 가득 채워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L07_basic#6','sci',3,2,'u1','L07','g3_2_sci_u1_L07_basic','lesson_basic','SC3-2-u1-C12',2,'mc','auto','나뭇잎이 흔들리는 모습을 보고 알 수 있는 것은 무엇인가요?',ARRAY['SC3-2-u1-X30','SC3-2-u1-X27','SC3-2-u1-X21']::text[],false,'{"seq":6,"concept":"SC3-2-u1-C12","difficulty":2,"kind":"mc","stem":"나뭇잎이 흔들리는 모습을 보고 알 수 있는 것은 무엇인가요?","options":[{"t":"공기가 있다","correct":true},{"t":"나뭇잎은 액체이다","mis":"SC3-2-u1-X30"},{"t":"나뭇잎은 공간을 차지하지 않는다","mis":"SC3-2-u1-X27"},{"t":"눈에 보이지 않으니 아무것도 없다","mis":"SC3-2-u1-X21"}],"explanation":["무엇이 나뭇잎을 흔들까요?","바람이에요.","공기가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
