INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L07_basic#9','sci',3,2,'u1','L07','g3_2_sci_u1_L07_basic','lesson_basic','SC3-2-u1-C12',2,'mc','auto','담는 용기에 따라 모양이 변하는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u1-X30']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C12","difficulty":2,"kind":"mc","stem":"담는 용기에 따라 모양이 변하는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"우유, 풍선 속 공기","correct":true},{"t":"휠체어, 우유","mis":"SC3-2-u1-X30"},{"t":"책, 안경","mis":"SC3-2-u1-X30"},{"t":"간장, 휠체어","mis":"SC3-2-u1-X30"}],"explanation":["액체와 기체를 찾아요.","휠체어, 책은 고체예요.","우유, 풍선 속 공기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L07_basic#10','sci',3,2,'u1','L07','g3_2_sci_u1_L07_basic','lesson_basic','SC3-2-u1-C12',3,'mc','auto','교실에서 세 가지 상태를 알맞게 찾은 것은 무엇인가요?',ARRAY['SC3-2-u1-X30']::text[],false,'{"seq":10,"concept":"SC3-2-u1-C12","difficulty":3,"kind":"mc","stem":"교실에서 세 가지 상태를 알맞게 찾은 것은 무엇인가요?","options":[{"t":"연필 — 고체 · 우유 — 액체 · 축구공 속 공기 — 기체","correct":true},{"t":"책상 — 고체 · 물 — 기체 · 공기 — 액체","mis":"SC3-2-u1-X30"},{"t":"연필 — 액체 · 우유 — 고체 · 공기 — 기체","mis":"SC3-2-u1-X30"},{"t":"지우개 — 기체 · 주스 — 액체 · 공 — 고체","mis":"SC3-2-u1-X30"}],"explanation":["하나씩 따져요.","연필은 잡을 수 있어요.","연필, 우유, 공기 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
