INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L07_challenge#2','sci',3,2,'u1','L07','g3_2_sci_u1_L07_challenge','lesson_challenge','SC3-2-u1-C12',2,'mc','auto','담는 용기에 따라 부피까지 변하는 상태는 무엇인가요?',ARRAY['SC3-2-u1-X27','SC3-2-u1-X19']::text[],false,'{"seq":2,"concept":"SC3-2-u1-C12","difficulty":2,"kind":"mc","stem":"담는 용기에 따라 부피까지 변하는 상태는 무엇인가요?","options":[{"t":"기체","correct":true},{"t":"고체","mis":"SC3-2-u1-X27"},{"t":"액체","mis":"SC3-2-u1-X19"},{"t":"셋 다","mis":"SC3-2-u1-X27"}],"explanation":["용기를 가득 채워요.","부피도 변해요.","기체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L07_challenge#3','sci',3,2,'u1','L07','g3_2_sci_u1_L07_challenge','lesson_challenge','SC3-2-u1-C12',3,'error','auto','물질의 상태를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u1-X28','SC3-2-u1-X30','SC3-2-u1-X27']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C12","difficulty":3,"kind":"error","stem":"물질의 상태를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「간장, 주스, 식용유 같은 액체에는 모두 물이 들어 있어.」","correct":true,"mis_target":"SC3-2-u1-X28"},{"t":"친구 나 — 「풍선 속 공기는 기체야.」","mis":"SC3-2-u1-X30"},{"t":"친구 다 — 「세 가지 상태 모두 공간을 차지해.」","mis":"SC3-2-u1-X27"}],"explanation":["식용유를 떠올려요.","물이 없어도 액체예요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L07_challenge#4','sci',3,2,'u1','L07','g3_2_sci_u1_L07_challenge','lesson_challenge','SC3-2-u1-C12',3,'mc','auto','비교표의 ㉠과 ㉡에 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u1-X27','SC3-2-u1-X20','SC3-2-u1-X21']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C12","difficulty":3,"kind":"mc","stem":"비교표의 ㉠과 ㉡에 알맞은 것은 무엇인가요?","options":[{"t":"㉠ × · ㉡ ×","correct":true},{"t":"㉠ ○ · ㉡ ○","mis":"SC3-2-u1-X27"},{"t":"㉠ ○ · ㉡ ×","mis":"SC3-2-u1-X20"},{"t":"㉠ × · ㉡ ○","mis":"SC3-2-u1-X21"}],"explanation":["액체는 흘러요.","공기는 보이지 않아요.","둘 다 ×예요."],"asset":{"type":"passage","lines":["고체 — 눈으로 보여요 ○ · 손으로 잡혀요 ○ · 모양이 변해요 ×","액체 — 눈으로 보여요 ○ · 손으로 잡혀요 ㉠ · 모양이 변해요 ○","공기 — 눈으로 보여요 ㉡ · 손으로 잡혀요 × · 모양이 변해요 ○"],"title":"세 가지 상태 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L07_challenge#5','sci',3,2,'u1','L07','g3_2_sci_u1_L07_challenge','lesson_challenge','SC3-2-u1-C12',3,'mc','auto','자전거를 보고 상태를 바르게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X29','SC3-2-u1-X30']::text[],false,'{"seq":5,"concept":"SC3-2-u1-C12","difficulty":3,"kind":"mc","stem":"자전거를 보고 상태를 바르게 말한 것은 무엇인가요?","options":[{"t":"몸체와 타이어는 고체, 타이어 속 공기는 기체, 물통 속 물은 액체이다","correct":true},{"t":"타이어와 타이어 속 공기는 모두 고체이다","mis":"SC3-2-u1-X29"},{"t":"자전거는 고체 한 가지로만 이루어져 있다","mis":"SC3-2-u1-X29"},{"t":"물통 속 물은 기체이다","mis":"SC3-2-u1-X30"}],"explanation":["부분마다 따로 봐요.","타이어 속 공기는 보이지 않아요.","세 상태가 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L07_challenge#6','sci',3,2,'u1','L07','g3_2_sci_u1_L07_challenge','lesson_challenge','SC3-2-u1-C12',3,'match','auto','공원에서 찾은 것과 상태를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u1-C12","difficulty":3,"kind":"match","stem":"공원에서 찾은 것과 상태를 알맞게 이으세요.","pairs":[{"l":"안경","r":"고체"},{"l":"분수대의 물","r":"액체"},{"l":"비눗방울 속 공기","r":"기체"}],"mis":"SC3-2-u1-X30","explanation":["안경은 잡을 수 있어요.","물은 흘러요.","비눗방울 속은 공기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L07_challenge#7','sci',3,2,'u1','L07','g3_2_sci_u1_L07_challenge','lesson_challenge','SC3-2-u1-C12',3,'mc','auto','「담는 용기에 따라 부피가 변하나요?」로 나눌 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u1-X27','SC3-2-u1-X19','SC3-2-u1-X30']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C12","difficulty":3,"kind":"mc","stem":"「담는 용기에 따라 부피가 변하나요?」로 나눌 때 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"풍선 속 공기, 타이어 속 공기","correct":true},{"t":"책, 휠체어","mis":"SC3-2-u1-X27"},{"t":"강물, 주스","mis":"SC3-2-u1-X19"},{"t":"강물, 풍선 속 공기","mis":"SC3-2-u1-X30"}],"explanation":["부피까지 변하는 것을 찾아요.","기체예요.","공기 두 가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L07_challenge#8','sci',3,2,'u1','L07','g3_2_sci_u1_L07_challenge','lesson_challenge','SC3-2-u1-C12',4,'mc','auto','비눗방울을 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X29','SC3-2-u1-X21','SC3-2-u1-X30']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C12","difficulty":4,"kind":"mc","stem":"비눗방울을 알맞게 말한 것은 무엇인가요?","options":[{"t":"비눗방울 막은 눈에 보이지만 속을 가득 채운 공기는 보이지 않는다","correct":true},{"t":"비눗방울은 막과 속이 모두 같은 상태이다","mis":"SC3-2-u1-X29"},{"t":"비눗방울 속은 비어 있어 공간을 차지하는 것이 없다","mis":"SC3-2-u1-X21"},{"t":"비눗방울 속 공기는 눈에 보이는 액체이다","mis":"SC3-2-u1-X30"}],"explanation":["막과 속을 따로 봐요.","속에는 공기가 있어요.","공기는 보이지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L07_challenge#9','sci',3,2,'u1','L07','g3_2_sci_u1_L07_challenge','lesson_challenge','SC3-2-u1-C12',4,'mc','auto','「눈으로 볼 수 있고, 손으로 잡을 수 없고, 담는 용기에 따라 모양은 변하지만 부피는 변하지 않는다.」 이 물질로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u1-X30','SC3-2-u1-X17']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C12","difficulty":4,"kind":"mc","stem":"「눈으로 볼 수 있고, 손으로 잡을 수 없고, 담는 용기에 따라 모양은 변하지만 부피는 변하지 않는다.」 이 물질로 알맞은 것은 무엇인가요?","options":[{"t":"식용유","correct":true},{"t":"클립","mis":"SC3-2-u1-X30"},{"t":"타이어 속 공기","mis":"SC3-2-u1-X30"},{"t":"스펀지","mis":"SC3-2-u1-X17"}],"explanation":["보이고 잡히지 않아요.","모양만 변해요.","액체인 식용유예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L07_challenge#10','sci',3,2,'u1','L07','g3_2_sci_u1_L07_challenge','lesson_challenge','SC3-2-u1-C12',4,'essay','teacher','고체, 액체, 기체의 예를 하나씩 쓰고, 세 상태의 같은 점 한 가지와 다른 점 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u1-C12","difficulty":4,"kind":"essay","stem":"고체, 액체, 기체의 예를 하나씩 쓰고, 세 상태의 같은 점 한 가지와 다른 점 두 가지를 쓰세요.","answer_guide":{"answer":"예: 고체는 연필, 액체는 우유, 기체는 풍선 속 공기이다. 같은 점은 세 상태 모두 공간을 차지한다는 것이다. 다른 점은 고체와 액체는 눈에 보이지만 공기는 보이지 않는다는 것과, 고체는 담는 용기에 관계없이 모양이 그대로이지만 액체와 기체는 담는 용기에 따라 모양이 변한다는 것이다.","scoring_points":["세 상태의 예를 바르게 썼는가","같은 점(공간을 차지함)을 썼는가","다른 점 두 가지를 썼는가"]},"explanation":["예를 하나씩 써요.","같은 점을 써요.","다른 점 둘을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_basic#1','sci',3,2,'u1','L08','g3_2_sci_u1_L08_basic','lesson_basic','SC3-2-u1-C13',1,'mc','auto','무거운 책을 올려도 부러지지 않는 독서대 받침대에 알맞은 물질은 무엇인가요?',ARRAY['SC3-2-u1-X32']::text[],false,'{"seq":1,"concept":"SC3-2-u1-C13","difficulty":1,"kind":"mc","stem":"무거운 책을 올려도 부러지지 않는 독서대 받침대에 알맞은 물질은 무엇인가요?","options":[{"t":"철","correct":true},{"t":"유리","mis":"SC3-2-u1-X32"},{"t":"종이","mis":"SC3-2-u1-X32"},{"t":"고무","mis":"SC3-2-u1-X32"}],"explanation":["단단한 물질이에요.","무거운 책도 버텨요.","철이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_basic#2','sci',3,2,'u1','L08','g3_2_sci_u1_L08_basic','lesson_basic','SC3-2-u1-C13',1,'sa','auto','독서대 바닥이 책상 위에서 밀리지 않게 하는 물질을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u1-C13","difficulty":1,"kind":"sa","stem":"독서대 바닥이 책상 위에서 밀리지 않게 하는 물질을 두 글자로 쓰세요.","answer":["고무"],"explanation":["잘 미끄러지지 않아요.","지우개도 이것이에요.","고무예요."],"mis":"SC3-2-u1-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_basic#3','sci',3,2,'u1','L08','g3_2_sci_u1_L08_basic','lesson_basic','SC3-2-u1-C13',1,'ox','auto','가장 비싼 물질을 쓰면 가장 좋은 설계예요.',ARRAY['SC3-2-u1-X31']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C13","difficulty":1,"kind":"ox","stem":"가장 비싼 물질을 쓰면 가장 좋은 설계예요.","answer":"X","reason_options":[{"t":"쓰임새에 알맞은 성질의 물질을 쓰는 것이 중요하기 때문에","correct":true},{"t":"비쌀수록 쓰임새와 관계없이 좋기 때문에","mis":"SC3-2-u1-X31"}],"mis":"SC3-2-u1-X31","explanation":["설계에서 중요한 것은요?","쓰임새예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_basic#4','sci',3,2,'u1','L08','g3_2_sci_u1_L08_basic','lesson_basic','SC3-2-u1-C13',1,'mc','auto','가방에 넣어 들고 다니기 좋은 독서대 몸통에 알맞은 물질은 무엇인가요?',ARRAY['SC3-2-u1-X32']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C13","difficulty":1,"kind":"mc","stem":"가방에 넣어 들고 다니기 좋은 독서대 몸통에 알맞은 물질은 무엇인가요?","options":[{"t":"플라스틱","correct":true},{"t":"무거운 철","mis":"SC3-2-u1-X32"},{"t":"깨지기 쉬운 유리","mis":"SC3-2-u1-X32"},{"t":"향이 나는 나무","mis":"SC3-2-u1-X32"}],"explanation":["들고 다녀요.","가벼워야 해요.","플라스틱이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_basic#5','sci',3,2,'u1','L08','g3_2_sci_u1_L08_basic','lesson_basic','SC3-2-u1-C13',2,'match','auto','독서대의 부분과 알맞은 물질을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u1-C13","difficulty":2,"kind":"match","stem":"독서대의 부분과 알맞은 물질을 이으세요.","pairs":[{"l":"받침대","r":"철"},{"l":"몸통","r":"플라스틱"},{"l":"바닥","r":"고무"},{"l":"앞판","r":"유리"}],"mis":"SC3-2-u1-X32","explanation":["부분마다 쓰임새가 달라요.","바닥은 미끄러지지 않아야 해요.","철, 플라스틱, 고무, 유리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_basic#6','sci',3,2,'u1','L08','g3_2_sci_u1_L08_basic','lesson_basic','SC3-2-u1-C13',2,'mc','auto','쓰임새 있는 물체를 설계하는 차례로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u1-X31']::text[],false,'{"seq":6,"concept":"SC3-2-u1-C13","difficulty":2,"kind":"mc","stem":"쓰임새 있는 물체를 설계하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"필요한 물체 찾기 → 알맞은 물질의 성질 고르기 → 설계도 그리고 소개하기","correct":true},{"t":"설계도 그리기 → 필요한 물체 찾기 → 물질 고르기","mis":"SC3-2-u1-X31"},{"t":"가장 비싼 물질 고르기 → 설계도 그리기 → 소개하기","mis":"SC3-2-u1-X31"},{"t":"소개하기 → 설계도 그리기 → 필요한 물체 찾기","mis":"SC3-2-u1-X31"}],"explanation":["먼저 무엇이 필요한지 찾아요.","그다음 물질을 골라요.","마지막에 그리고 소개해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_basic#7','sci',3,2,'u1','L08','g3_2_sci_u1_L08_basic','lesson_basic','SC3-2-u1-C13',2,'blank','auto','설계한 물체의 좋은 점은 물질의 (    )과 이어서 말해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u1-X31']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C13","difficulty":2,"kind":"blank","stem":"설계한 물체의 좋은 점은 물질의 (    )과 이어서 말해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"성질","correct":true},{"t":"가격","mis":"SC3-2-u1-X31"},{"t":"이름","mis":"SC3-2-u1-X31"},{"t":"개수","mis":"SC3-2-u1-X31"}],"explanation":["철이 단단해서 좋아요.","단단함은 무엇일까요?","성질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_basic#8','sci',3,2,'u1','L08','g3_2_sci_u1_L08_basic','lesson_basic','SC3-2-u1-C13',2,'ox','auto','친구 설계의 보완할 점은 더 좋은 방법과 함께 말해요.',ARRAY['SC3-2-u1-X33']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C13","difficulty":2,"kind":"ox","stem":"친구 설계의 보완할 점은 더 좋은 방법과 함께 말해요.","answer":"O","reason_options":[{"t":"보완할 점은 설계를 더 좋게 만드는 도움말이기 때문에","correct":true},{"t":"보완할 점은 잘못을 찾아 흉보는 것이기 때문에","mis":"SC3-2-u1-X33"}],"mis":"SC3-2-u1-X33","explanation":["보완할 점의 뜻을 떠올려요.","더 좋게 만들어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_basic#9','sci',3,2,'u1','L08','g3_2_sci_u1_L08_basic','lesson_basic','SC3-2-u1-C13',2,'mc','auto','독서대 앞판을 유리로 만들면 좋은 점은 무엇인가요?',ARRAY['SC3-2-u1-X32']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C13","difficulty":2,"kind":"mc","stem":"독서대 앞판을 유리로 만들면 좋은 점은 무엇인가요?","options":[{"t":"투명해서 책 글씨가 잘 보인다","correct":true},{"t":"단단해서 무거운 책을 버틴다","mis":"SC3-2-u1-X32"},{"t":"잘 미끄러지지 않는다","mis":"SC3-2-u1-X32"},{"t":"가벼워서 들고 다니기 좋다","mis":"SC3-2-u1-X32"}],"explanation":["유리의 성질이에요.","속이 비쳐요.","글씨가 잘 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_basic#10','sci',3,2,'u1','L08','g3_2_sci_u1_L08_basic','lesson_basic','SC3-2-u1-C13',3,'mc','auto','친구 설계의 보완할 점을 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X33']::text[],false,'{"seq":10,"concept":"SC3-2-u1-C13","difficulty":3,"kind":"mc","stem":"친구 설계의 보완할 점을 알맞게 말한 것은 무엇인가요?","options":[{"t":"「유리는 깨질 수 있으니 테두리를 고무로 감싸면 어떨까?」","correct":true},{"t":"「그림이 이상해. 다시 그려.」","mis":"SC3-2-u1-X33"},{"t":"「이 설계는 별로야.」","mis":"SC3-2-u1-X33"},{"t":"「내 설계가 더 좋아.」","mis":"SC3-2-u1-X33"}],"explanation":["더 좋은 방법이 있나요?","대안을 찾아요.","고무로 감싸자는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_challenge#1','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',2,'sa','auto','책을 세워 두어 고개를 숙이지 않고 읽게 해 주는 물체를 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u1-C13","difficulty":2,"kind":"sa","stem":"책을 세워 두어 고개를 숙이지 않고 읽게 해 주는 물체를 세 글자로 쓰세요.","answer":["독서대"],"explanation":["책을 세워요.","독◯◯예요.","독서대예요."],"mis":"SC3-2-u1-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_challenge#2','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',2,'mc','auto','물질의 성질로 좋은 점을 설명한 것은 무엇인가요?',ARRAY['SC3-2-u1-X31']::text[],false,'{"seq":2,"concept":"SC3-2-u1-C13","difficulty":2,"kind":"mc","stem":"물질의 성질로 좋은 점을 설명한 것은 무엇인가요?","options":[{"t":"「철이 단단해서 무거운 책도 버텨요.」","correct":true},{"t":"「그냥 마음에 들어서 좋아요.」","mis":"SC3-2-u1-X31"},{"t":"「들고 다니면 멋있어 보여요.」","mis":"SC3-2-u1-X31"},{"t":"「비싼 물질이라서 좋아요.」","mis":"SC3-2-u1-X31"}],"explanation":["성질이 들어 있나요?","단단함이 성질이에요.","철이 단단하다는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_challenge#3','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',3,'error','auto','독서대 설계를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u1-X32']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C13","difficulty":3,"kind":"error","stem":"독서대 설계를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「밀리지 않게 독서대 바닥에 유리를 붙일래.」","correct":true,"mis_target":"SC3-2-u1-X32"},{"t":"친구 나 — 「손잡이는 플라스틱으로 하면 좋아하는 색으로 만들 수 있어.」","mis":"SC3-2-u1-X32"},{"t":"친구 다 — 「받침대는 단단한 철로 하자.」","mis":"SC3-2-u1-X32"}],"explanation":["미끄럼을 막는 물질은요?","고무예요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_challenge#4','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',3,'mc','auto','친구 나의 보관함 설계에서 쓰임새에 맞지 않는 부분과 바르게 고친 것은 무엇인가요?',ARRAY['SC3-2-u1-X32']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C13","difficulty":3,"kind":"mc","stem":"친구 나의 보관함 설계에서 쓰임새에 맞지 않는 부분과 바르게 고친 것은 무엇인가요?","options":[{"t":"㉣ 몸통 — 유리 대신 가벼운 플라스틱으로 바꾼다","correct":true},{"t":"㉠ 뚜껑 — 유리 대신 철로 바꾼다","mis":"SC3-2-u1-X32"},{"t":"㉡ 바닥 — 고무 대신 유리로 바꾼다","mis":"SC3-2-u1-X32"},{"t":"㉢ 손잡이 — 철 대신 유리로 바꾼다","mis":"SC3-2-u1-X32"}],"explanation":["쓰임새를 하나씩 따져요.","들고 다니려면 가벼워야 해요.","㉣이에요."],"asset":{"type":"passage","lines":["㉠ 속이 들여다보이는 뚜껑 — 유리","㉡ 책상에서 밀리지 않는 바닥 — 고무","㉢ 튼튼한 손잡이 — 철","㉣ 가볍게 들고 다니는 몸통 — 유리"],"title":"친구 나의 보관함 설계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_challenge#5','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',3,'mc','auto','친구 설계를 볼 때 살필 것으로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u1-X31','SC3-2-u1-X33']::text[],false,'{"seq":5,"concept":"SC3-2-u1-C13","difficulty":3,"kind":"mc","stem":"친구 설계를 볼 때 살필 것으로 알맞은 것은 무엇인가요?","options":[{"t":"여러 물질의 성질을 이용했나요?","correct":true},{"t":"가장 비싼 물질을 썼나요?","mis":"SC3-2-u1-X31"},{"t":"친구보다 빨리 끝냈나요?","mis":"SC3-2-u1-X33"},{"t":"색칠을 가장 많이 했나요?","mis":"SC3-2-u1-X31"}],"explanation":["생각이 잘 드러났는지 봐요.","생활에서 쓸 수 있는지 봐요.","성질을 이용했는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_challenge#6','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',3,'match','auto','물질의 성질과 독서대의 좋은 점을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u1-C13","difficulty":3,"kind":"match","stem":"물질의 성질과 독서대의 좋은 점을 알맞게 이으세요.","pairs":[{"l":"철이 단단해요","r":"무거운 책도 버텨요"},{"l":"플라스틱이 가벼운 편이에요","r":"들고 다니기 좋아요"},{"l":"고무가 잘 미끄러지지 않아요","r":"책상 위에서 밀리지 않아요"}],"mis":"SC3-2-u1-X31","explanation":["성질과 좋은 점을 이어요.","단단하면 버텨요.","가벼우면 들고 다녀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_challenge#7','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',3,'mc','auto','잘한 점과 보완할 점을 모두 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X33']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C13","difficulty":3,"kind":"mc","stem":"잘한 점과 보완할 점을 모두 알맞게 말한 것은 무엇인가요?","options":[{"t":"「받침대가 튼튼해서 좋아. 높이를 바꿀 수 있으면 더 좋겠어.」","correct":true},{"t":"「받침대가 튼튼해서 좋아.」","mis":"SC3-2-u1-X33"},{"t":"「높이가 이상해. 다시 만들어.」","mis":"SC3-2-u1-X33"},{"t":"「다 별로야.」","mis":"SC3-2-u1-X33"}],"explanation":["잘한 점이 있나요?","대안도 있나요?","둘 다 있는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_challenge#8','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',4,'mc','auto','어린이들이 들고 다니며 쓰는 물통을 설계해요. 가볍고, 떨어뜨려도 잘 깨지지 않고, 책상에서 잘 미끄러지지 않게 하려면 어떻게 설계하면 좋을까요?',ARRAY['SC3-2-u1-X32','SC3-2-u1-X31']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C13","difficulty":4,"kind":"mc","stem":"어린이들이 들고 다니며 쓰는 물통을 설계해요. 가볍고, 떨어뜨려도 잘 깨지지 않고, 책상에서 잘 미끄러지지 않게 하려면 어떻게 설계하면 좋을까요?","options":[{"t":"몸통은 플라스틱으로 하고 바닥에 고무를 붙인다","correct":true},{"t":"몸통을 유리로 하고 바닥에 유리를 붙인다","mis":"SC3-2-u1-X32"},{"t":"모든 부분을 무거운 철로만 만든다","mis":"SC3-2-u1-X32"},{"t":"가장 비싼 물질을 골라 만든다","mis":"SC3-2-u1-X31"}],"explanation":["필요한 성질을 찾아요.","가볍고 미끄러지지 않아야 해요.","플라스틱과 고무예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_challenge#9','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',4,'mc','auto','단원 낱말을 「물질의 종류」와 「물질의 상태」로 바르게 나눈 것은 무엇인가요?',ARRAY['SC3-2-u1-X30','SC3-2-u1-X05']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C13","difficulty":4,"kind":"mc","stem":"단원 낱말을 「물질의 종류」와 「물질의 상태」로 바르게 나눈 것은 무엇인가요?","options":[{"t":"종류: 플라스틱, 나무 / 상태: 고체, 기체","correct":true},{"t":"종류: 고체, 나무 / 상태: 플라스틱, 기체","mis":"SC3-2-u1-X30"},{"t":"종류: 고체, 기체 / 상태: 플라스틱, 나무","mis":"SC3-2-u1-X30"},{"t":"종류: 물체, 물질 / 상태: 플라스틱, 고체","mis":"SC3-2-u1-X05"}],"explanation":["무엇으로 되어 있나요?","어떤 상태인가요?","플라스틱·나무는 종류예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L08_challenge#10','sci',3,2,'u1','L08','g3_2_sci_u1_L08_challenge','lesson_challenge','SC3-2-u1-C13',4,'essay','teacher','생활에서 필요한 물체 하나를 설계하세요. 물체의 이름과 쓰임새를 쓰고, 부분 두 곳 이상에 어떤 물질을 쓸지와 그 물질의 성질 때문에 생기는 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u1-C13","difficulty":4,"kind":"essay","stem":"생활에서 필요한 물체 하나를 설계하세요. 물체의 이름과 쓰임새를 쓰고, 부분 두 곳 이상에 어떤 물질을 쓸지와 그 물질의 성질 때문에 생기는 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 비 오는 날 교실 앞에 두는 우산꽂이를 설계한다. 통은 단단한 철로 만들어 우산을 많이 꽂아도 넘어지거나 찌그러지지 않게 한다. 바닥에는 잘 미끄러지지 않는 고무를 붙여 밀리지 않게 한다. 이름표는 색깔을 다양하게 만들 수 있는 플라스틱으로 만들어 반마다 다른 색으로 꾸민다.","scoring_points":["물체의 이름과 쓰임새를 썼는가","부분 두 곳 이상에 물질을 정했는가","좋은 점을 물질의 성질과 이어 썼는가"]},"explanation":["물체를 정해요.","부분마다 물질을 골라요.","성질과 좋은 점을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L09_basic#1','sci',3,2,'u1','L09','g3_2_sci_u1_L09_basic','lesson_basic','SC3-2-u1-C14',1,'mc','auto','3D 프린터가 물체를 만드는 방법은 무엇인가요?',ARRAY['SC3-2-u1-X34']::text[],false,'{"seq":1,"concept":"SC3-2-u1-C14","difficulty":1,"kind":"mc","stem":"3D 프린터가 물체를 만드는 방법은 무엇인가요?","options":[{"t":"물질을 정해진 두께만큼 겹겹이 쌓아 올린다","correct":true},{"t":"물체를 깎아 없앤다","mis":"SC3-2-u1-X34"},{"t":"색종이를 접는다","mis":"SC3-2-u1-X34"},{"t":"사진을 찍는다","mis":"SC3-2-u1-X34"}],"explanation":["얇은 층을 떠올려요.","쌓아 올려요.","겹겹이 쌓아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L09_basic#2','sci',3,2,'u1','L09','g3_2_sci_u1_L09_basic','lesson_basic','SC3-2-u1-C14',1,'sa','auto','3D 프린터가 보고 물체를 만들 수 있도록 컴퓨터에 넣는 것을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u1-C14","difficulty":1,"kind":"sa","stem":"3D 프린터가 보고 물체를 만들 수 있도록 컴퓨터에 넣는 것을 세 글자로 쓰세요.","answer":["설계도"],"explanation":["물체를 그린 그림이에요.","설계◯예요.","설계도예요."],"mis":"SC3-2-u1-X34"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L09_basic#3','sci',3,2,'u1','L09','g3_2_sci_u1_L09_basic','lesson_basic','SC3-2-u1-C14',1,'ox','auto','3D 프린터로 과자 같은 음식도 만들 수 있어요.',ARRAY['SC3-2-u1-X35']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C14","difficulty":1,"kind":"ox","stem":"3D 프린터로 과자 같은 음식도 만들 수 있어요.","answer":"O","reason_options":[{"t":"식재료를 물질로 쓰면 음식도 만들 수 있기 때문에","correct":true},{"t":"3D 프린터는 플라스틱만 쓸 수 있기 때문에","mis":"SC3-2-u1-X35"}],"mis":"SC3-2-u1-X35","explanation":["식재료를 떠올려요.","먹을 수 있는 물질이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L09_basic#4','sci',3,2,'u1','L09','g3_2_sci_u1_L09_basic','lesson_basic','SC3-2-u1-C14',1,'mc','auto','3D 프린터로 만들 수 있다고 배운 것은 무엇인가요?',ARRAY['SC3-2-u1-X35']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C14","difficulty":1,"kind":"mc","stem":"3D 프린터로 만들 수 있다고 배운 것은 무엇인가요?","options":[{"t":"운동화","correct":true},{"t":"살아 있는 강아지","mis":"SC3-2-u1-X35"},{"t":"햇빛","mis":"SC3-2-u1-X35"},{"t":"바람","mis":"SC3-2-u1-X35"}],"explanation":["물질로 이루어진 물체예요.","신고 걸어요.","운동화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L09_basic#5','sci',3,2,'u1','L09','g3_2_sci_u1_L09_basic','lesson_basic','SC3-2-u1-C14',2,'match','auto','3D 프린터로 만든 것과 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u1-C14","difficulty":2,"kind":"match","stem":"3D 프린터로 만든 것과 쓰임을 알맞게 이으세요.","pairs":[{"l":"운동화","r":"신고 걸어요"},{"l":"건축물","r":"사람이 지내요"},{"l":"자동차 부품","r":"자동차를 만들어요"},{"l":"인공 치아","r":"환자에게 꼭 맞는 치아가 돼요"}],"mis":"SC3-2-u1-X36","explanation":["어디에 쓰는지 떠올려요.","부품은 자동차예요.","치아는 의료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L09_basic#6','sci',3,2,'u1','L09','g3_2_sci_u1_L09_basic','lesson_basic','SC3-2-u1-C14',2,'mc','auto','3D 프린터가 쓰는 재료끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u1-X35']::text[],false,'{"seq":6,"concept":"SC3-2-u1-C14","difficulty":2,"kind":"mc","stem":"3D 프린터가 쓰는 재료끼리 묶은 것은 무엇인가요?","options":[{"t":"플라스틱, 금속, 식재료","correct":true},{"t":"햇빛, 바람, 소리","mis":"SC3-2-u1-X35"},{"t":"플라스틱 한 가지뿐","mis":"SC3-2-u1-X35"},{"t":"살아 있는 생물","mis":"SC3-2-u1-X35"}],"explanation":["여러 재료를 써요.","먹을 수 있는 것도 있어요.","플라스틱, 금속, 식재료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L09_basic#7','sci',3,2,'u1','L09','g3_2_sci_u1_L09_basic','lesson_basic','SC3-2-u1-C14',2,'blank','auto','3D 프린터는 (    )에 따라 물질을 겹겹이 쌓아 물체를 만들어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u1-X34']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C14","difficulty":2,"kind":"blank","stem":"3D 프린터는 (    )에 따라 물질을 겹겹이 쌓아 물체를 만들어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"설계도","correct":true},{"t":"날씨","mis":"SC3-2-u1-X34"},{"t":"기분","mis":"SC3-2-u1-X34"},{"t":"소리","mis":"SC3-2-u1-X34"}],"explanation":["무엇을 보고 만들까요?","컴퓨터에 넣어요.","설계도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L09_basic#8','sci',3,2,'u1','L09','g3_2_sci_u1_L09_basic','lesson_basic','SC3-2-u1-C14',2,'ox','auto','3D 프린터는 재료가 없어도 물체를 만들 수 있어요.',ARRAY['SC3-2-u1-X34']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C14","difficulty":2,"kind":"ox","stem":"3D 프린터는 재료가 없어도 물체를 만들 수 있어요.","answer":"X","reason_options":[{"t":"설계도와 함께 물질(재료)이 꼭 있어야 하기 때문에","correct":true},{"t":"설계도만 있으면 물체가 저절로 생기기 때문에","mis":"SC3-2-u1-X34"}],"mis":"SC3-2-u1-X34","explanation":["무엇을 쌓을까요?","물질을 쌓아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
