INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L09_basic#10','sci',3,2,'u1','L09','g3_2_sci_u1_L09_basic','lesson_basic','SC3-2-u1-C14',3,'mc','auto','자동차 부품을 3D 프린터로 만들면 좋은 점은 무엇인가요?',ARRAY['SC3-2-u1-X36','SC3-2-u1-X34','SC3-2-u1-X35']::text[],false,'{"seq":10,"concept":"SC3-2-u1-C14","difficulty":3,"kind":"mc","stem":"자동차 부품을 3D 프린터로 만들면 좋은 점은 무엇인가요?","options":[{"t":"정교한 부품을 한 번에 만들 수 있어 부품 수가 줄고 자동차가 가벼워진다","correct":true},{"t":"부품이 더 많아져서 자동차가 무거워진다","mis":"SC3-2-u1-X36"},{"t":"설계도 없이 부품이 저절로 생긴다","mis":"SC3-2-u1-X34"},{"t":"살아 있는 부품을 만들 수 있다","mis":"SC3-2-u1-X35"}],"explanation":["정교한 부품이에요.","한 번에 만들어요.","가벼워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
