INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L09_challenge#3','sci',3,2,'u1','L09','g3_2_sci_u1_L09_challenge','lesson_challenge','SC3-2-u1-C14',3,'error','auto','3D 프린터를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u1-X34','SC3-2-u1-X36']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C14","difficulty":3,"kind":"error","stem":"3D 프린터를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「3D 프린터는 큰 덩어리를 깎아서 물체를 만들어.」","correct":true,"mis_target":"SC3-2-u1-X34"},{"t":"친구 나 — 「3D 프린터도 물질을 쌓아 물체를 만들어.」","mis":"SC3-2-u1-X34"},{"t":"친구 다 — 「3D 프린터는 건물을 짓는 데에도 쓰여.」","mis":"SC3-2-u1-X36"}],"explanation":["만드는 방법을 떠올려요.","쌓아 올려요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
