INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L09_challenge#7','sci',3,2,'u1','L09','g3_2_sci_u1_L09_challenge','lesson_challenge','SC3-2-u1-C14',3,'mc','auto','건축물을 3D 프린터로 지을 때 좋은 점은 무엇인가요?',ARRAY['SC3-2-u1-X34','SC3-2-u1-X35']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C14","difficulty":3,"kind":"mc","stem":"건축물을 3D 프린터로 지을 때 좋은 점은 무엇인가요?","options":[{"t":"시간과 재료를 아낄 수 있다","correct":true},{"t":"재료가 전혀 필요 없다","mis":"SC3-2-u1-X34"},{"t":"살아 있는 나무가 자란다","mis":"SC3-2-u1-X35"},{"t":"설계도가 없어도 된다","mis":"SC3-2-u1-X34"}],"explanation":["3D 프린터로 짓는 건물이에요.","빠르게 지어요.","시간과 재료를 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L09_challenge#8','sci',3,2,'u1','L09','g3_2_sci_u1_L09_challenge','lesson_challenge','SC3-2-u1-C14',4,'mc','auto','내 발에 꼭 맞는 운동화를 3D 프린터로 만들려면 무엇이 필요한가요?',ARRAY['SC3-2-u1-X34','SC3-2-u1-X35']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C14","difficulty":4,"kind":"mc","stem":"내 발에 꼭 맞는 운동화를 3D 프린터로 만들려면 무엇이 필요한가요?","options":[{"t":"내 발에 맞춘 설계도와 운동화에 알맞은 물질","correct":true},{"t":"설계도 없이 프린터만 있으면 된다","mis":"SC3-2-u1-X34"},{"t":"먹을 수 있는 식재료만 있으면 된다","mis":"SC3-2-u1-X35"},{"t":"발 사진 한 장만 있으면 저절로 만들어진다","mis":"SC3-2-u1-X34"}],"explanation":["두 가지가 꼭 있어야 해요.","설계도와 물질이에요.","발에 맞춘 설계도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L09_challenge#9','sci',3,2,'u1','L09','g3_2_sci_u1_L09_challenge','lesson_challenge','SC3-2-u1-C14',4,'mc','auto','3D 프린터로 만든 과자와 플라스틱 장난감을 견주어 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X34','SC3-2-u1-X35']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C14","difficulty":4,"kind":"mc","stem":"3D 프린터로 만든 과자와 플라스틱 장난감을 견주어 알맞게 말한 것은 무엇인가요?","options":[{"t":"둘 다 물질로 이루어진 물체이지만 쓰임새에 따라 다른 물질을 썼다","correct":true},{"t":"과자는 물질이 아니라서 재료가 필요 없다","mis":"SC3-2-u1-X34"},{"t":"둘 다 같은 플라스틱으로 만들었다","mis":"SC3-2-u1-X35"},{"t":"장난감은 물질이 없어도 만들어진다","mis":"SC3-2-u1-X34"}],"explanation":["둘 다 물체예요.","물질로 이루어져 있어요.","쓰임새에 따라 물질이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_L09_challenge#10','sci',3,2,'u1','L09','g3_2_sci_u1_L09_challenge','lesson_challenge','SC3-2-u1-C14',4,'essay','teacher','3D 프린터로 만들고 싶은 물체 하나를 쓰고, 그 물체를 만들 때 필요한 두 가지와 어떤 재료(물질)를 쓰면 좋을지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u1-C14","difficulty":4,"kind":"essay","stem":"3D 프린터로 만들고 싶은 물체 하나를 쓰고, 그 물체를 만들 때 필요한 두 가지와 어떤 재료(물질)를 쓰면 좋을지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 우리 반 이름표를 만들고 싶다. 이름표를 만들려면 이름표 모양을 그린 설계도와 재료가 되는 물질이 꼭 있어야 한다. 이름표는 가볍고 색깔과 모양을 다양하게 만들 수 있는 플라스틱으로 만들면 친구마다 좋아하는 색과 모양으로 만들 수 있어 좋다.","scoring_points":["만들고 싶은 물체를 썼는가","설계도와 물질이 필요함을 썼는가","재료를 성질·쓰임새와 이어 골랐는가"]},"explanation":["물체를 정해요.","필요한 두 가지를 써요.","재료와 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#1','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C2',1,'mc','auto','햇살반 일지 ①의 단서가 가리키는 물체는 무엇인가요?',ARRAY['SC3-2-u1-X02']::text[],false,'{"seq":1,"concept":"SC3-2-u1-C2","difficulty":1,"kind":"mc","stem":"햇살반 일지 ①의 단서가 가리키는 물체는 무엇인가요?","options":[{"t":"어항","correct":true},{"t":"플라스틱 바구니","mis":"SC3-2-u1-X02"},{"t":"철 캔","mis":"SC3-2-u1-X02"},{"t":"나무 숟가락","mis":"SC3-2-u1-X02"}],"explanation":["단서 ②를 봐요.","단서 ③을 봐요.","어항이에요."],"asset":{"type":"passage","lines":["단서 ① 단단하지만 떨어뜨리면 깨져요.","단서 ② 유리로 되어 있어 속이 비쳐 보여요.","단서 ③ 물을 담아 물고기를 길러요."],"title":"햇살반 일지 ① 탐정 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#2','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C3',1,'mc','auto','물체를 이루는 재료를 가리키는 말은 무엇인가요?',ARRAY['SC3-2-u1-X05','SC3-2-u1-X15','SC3-2-u1-X02']::text[],false,'{"seq":2,"concept":"SC3-2-u1-C3","difficulty":1,"kind":"mc","stem":"물체를 이루는 재료를 가리키는 말은 무엇인가요?","options":[{"t":"물질","correct":true},{"t":"물체","mis":"SC3-2-u1-X05"},{"t":"부피","mis":"SC3-2-u1-X15"},{"t":"단서","mis":"SC3-2-u1-X02"}],"explanation":["재료를 한 낱말로 불러요.","나무, 철, 유리예요.","물질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#3','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C4',1,'mc','auto','햇살반 일지 ②에서 학교 자전거의 타이어는 어떤 물질인가요?',ARRAY['SC3-2-u1-X07']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C4","difficulty":1,"kind":"mc","stem":"햇살반 일지 ②에서 학교 자전거의 타이어는 어떤 물질인가요?","options":[{"t":"고무","correct":true},{"t":"철","mis":"SC3-2-u1-X07"},{"t":"플라스틱","mis":"SC3-2-u1-X07"},{"t":"섬유","mis":"SC3-2-u1-X07"}],"explanation":["기록을 읽어요.","타이어 줄이에요.","고무예요."],"asset":{"type":"passage","lines":["몸체 — 철 · 바구니 — 플라스틱","타이어 — 고무 · 안장 덮개 — 섬유","타이어 속에는 공기를 넣었어요."],"title":"햇살반 일지 ② 학교 자전거 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#4','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C6',1,'mc','auto','광택이 있고 단단한 물질은 무엇인가요?',ARRAY['SC3-2-u1-X09']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C6","difficulty":1,"kind":"mc","stem":"광택이 있고 단단한 물질은 무엇인가요?","options":[{"t":"철","correct":true},{"t":"유리","mis":"SC3-2-u1-X09"},{"t":"나무","mis":"SC3-2-u1-X09"},{"t":"플라스틱","mis":"SC3-2-u1-X09"}],"explanation":["반짝여요.","단단해요.","철이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#5','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C7',1,'mc','auto','햇살반 일지 ④에서 잘못 넣은 물건은 무엇인가요?',ARRAY['SC3-2-u1-X13','SC3-2-u1-X14']::text[],false,'{"seq":5,"concept":"SC3-2-u1-C7","difficulty":1,"kind":"mc","stem":"햇살반 일지 ④에서 잘못 넣은 물건은 무엇인가요?","options":[{"t":"요구르트병","correct":true},{"t":"빈 잼 유리병","mis":"SC3-2-u1-X13"},{"t":"빈 철 캔","mis":"SC3-2-u1-X14"},{"t":"페트병","mis":"SC3-2-u1-X13"}],"explanation":["물질의 종류를 따져요.","요구르트병은 가벼워요.","플라스틱이라 잘못 넣었어요."],"asset":{"type":"passage","lines":["유리병류 — 빈 잼 유리병, 요구르트병","캔류 — 빈 철 캔","플라스틱류 — 페트병, 플라스틱 컵"],"title":"햇살반 일지 ④ 분리배출 당번 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
