INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#9','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C2',2,'mc','auto','「누르면 조금 말랑해요」는 어떤 감각으로 찾은 단서인가요?',ARRAY['SC3-2-u1-X03']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C2","difficulty":2,"kind":"mc","stem":"「누르면 조금 말랑해요」는 어떤 감각으로 찾은 단서인가요?","options":[{"t":"손","correct":true},{"t":"눈","mis":"SC3-2-u1-X03"},{"t":"코","mis":"SC3-2-u1-X03"},{"t":"귀","mis":"SC3-2-u1-X03"}],"explanation":["만져서 알아요.","말랑한 느낌이에요.","손이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#10','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C5',2,'mc','auto','햇살반 일지 ③의 덧붙임을 보고 알맞게 생각한 것은 무엇인가요?',ARRAY['SC3-2-u1-X08','SC3-2-u1-X07']::text[],false,'{"seq":10,"concept":"SC3-2-u1-C5","difficulty":2,"kind":"mc","stem":"햇살반 일지 ③의 덧붙임을 보고 알맞게 생각한 것은 무엇인가요?","options":[{"t":"무게는 크기에 따라 달라서 나무의 성질이라고 하기 어렵다","correct":true},{"t":"나무는 언제나 무거운 물질이다","mis":"SC3-2-u1-X08"},{"t":"도마는 나무가 아니다","mis":"SC3-2-u1-X08"},{"t":"젓가락은 철로 되어 있다","mis":"SC3-2-u1-X07"}],"explanation":["둘 다 나무예요.","크기가 달라요.","무게는 성질이 아니에요."],"asset":{"type":"passage","lines":["나무 젓가락 — 고유한 향과 무늬가 있다.","철 숟가락 — 광택이 있고 단단하다.","유리컵 — 투명하지만 깨지기 쉽다.","플라스틱 접시 — 색깔과 모양이 여러 가지이다.","덧붙임 — 큰 나무 도마는 나무 젓가락보다 무거웠다."],"title":"햇살반 일지 ③ 급식실 물질 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#11','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C6',2,'mc','auto','물체를 쓰임새에 알맞은 물질로 만든 것은 무엇인가요?',ARRAY['SC3-2-u1-X10']::text[],false,'{"seq":11,"concept":"SC3-2-u1-C6","difficulty":2,"kind":"mc","stem":"물체를 쓰임새에 알맞은 물질로 만든 것은 무엇인가요?","options":[{"t":"속이 보여야 하는 어항을 유리로 만든다","correct":true},{"t":"잘 깨지면 안 되는 컵을 유리로만 만든다","mis":"SC3-2-u1-X10"},{"t":"바깥을 보는 창문을 나무로 만든다","mis":"SC3-2-u1-X10"},{"t":"가볍게 들고 다닐 바구니를 무거운 철로 만든다","mis":"SC3-2-u1-X10"}],"explanation":["쓰임새를 먼저 봐요.","속이 보여야 해요.","유리 어항이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#12','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C7',2,'mc','auto','햇살반 일지 ④를 바르게 고친 것은 무엇인가요?',ARRAY['SC3-2-u1-X13','SC3-2-u1-X14']::text[],false,'{"seq":12,"concept":"SC3-2-u1-C7","difficulty":2,"kind":"mc","stem":"햇살반 일지 ④를 바르게 고친 것은 무엇인가요?","options":[{"t":"요구르트병을 플라스틱류로 옮긴다","correct":true},{"t":"페트병을 유리병류로 옮긴다","mis":"SC3-2-u1-X13"},{"t":"빈 철 캔을 플라스틱류로 옮긴다","mis":"SC3-2-u1-X14"},{"t":"고칠 것이 없다","mis":"SC3-2-u1-X13"}],"explanation":["물질의 종류대로 넣어요.","요구르트병은 플라스틱이에요.","플라스틱류로 옮겨요."],"asset":{"type":"passage","lines":["유리병류 — 빈 잼 유리병, 요구르트병","캔류 — 빈 철 캔","플라스틱류 — 페트병, 플라스틱 컵"],"title":"햇살반 일지 ④ 분리배출 당번 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#13','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C9',2,'mc','auto','햇살반 일지 ⑤의 ④로 알 수 있는 것은 무엇인가요?',ARRAY['SC3-2-u1-X19','SC3-2-u1-X20']::text[],false,'{"seq":13,"concept":"SC3-2-u1-C9","difficulty":2,"kind":"mc","stem":"햇살반 일지 ⑤의 ④로 알 수 있는 것은 무엇인가요?","options":[{"t":"물을 여러 용기에 옮겨 담아도 부피는 변하지 않는다","correct":true},{"t":"넓은 접시에 담으면 물의 부피가 줄어든다","mis":"SC3-2-u1-X19"},{"t":"길쭉한 병에 담으면 물의 부피가 늘어난다","mis":"SC3-2-u1-X19"},{"t":"물은 어디에 담아도 모양이 그대로다","mis":"SC3-2-u1-X20"}],"explanation":["④를 읽어요.","처음과 높이가 같아요.","부피는 그대로예요."],"asset":{"type":"passage","lines":["① 처음 컵에 담긴 물의 높이를 유성펜으로 표시했다.","② 넓은 접시에 옮기니 물이 낮게 퍼졌다.","③ 길쭉한 병에 옮기니 물이 높아 보였다.","④ 처음 컵에 다시 부으니 처음 표시와 높이가 같았다."],"title":"햇살반 일지 ⑤ 물 옮겨 담기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#14','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C10',2,'mc','auto','탁구공 실험에서 뚜껑을 닫은 페트병을 바닥까지 밀어 넣으면 수조의 물 높이는 어떻게 되나요?',ARRAY['SC3-2-u1-X22']::text[],false,'{"seq":14,"concept":"SC3-2-u1-C10","difficulty":2,"kind":"mc","stem":"탁구공 실험에서 뚜껑을 닫은 페트병을 바닥까지 밀어 넣으면 수조의 물 높이는 어떻게 되나요?","options":[{"t":"처음보다 높아진다","correct":true},{"t":"처음보다 낮아진다","mis":"SC3-2-u1-X22"},{"t":"처음과 똑같다","mis":"SC3-2-u1-X22"},{"t":"물이 모두 사라진다","mis":"SC3-2-u1-X22"}],"explanation":["공기가 물을 밀어내요.","물이 올라가요.","높아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
