INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#16','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C14',2,'mc','auto','3D 프린터를 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X34','SC3-2-u1-X35']::text[],false,'{"seq":16,"concept":"SC3-2-u1-C14","difficulty":2,"kind":"mc","stem":"3D 프린터를 알맞게 말한 것은 무엇인가요?","options":[{"t":"설계도에 따라 물질을 겹겹이 쌓아 물체를 만든다","correct":true},{"t":"물체를 깎아서 만든다","mis":"SC3-2-u1-X34"},{"t":"재료 없이 물체를 만든다","mis":"SC3-2-u1-X34"},{"t":"살아 있는 동물도 만든다","mis":"SC3-2-u1-X35"}],"explanation":["설계도가 있어요.","쌓아 올려요.","그게 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#17','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C4',3,'mc','auto','햇살반 일지 ②를 보고 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X06','SC3-2-u1-X07']::text[],false,'{"seq":17,"concept":"SC3-2-u1-C4","difficulty":3,"kind":"mc","stem":"햇살반 일지 ②를 보고 알맞게 말한 것은 무엇인가요?","options":[{"t":"자전거는 철, 플라스틱, 고무, 섬유 같은 여러 물질로 이루어져 있다","correct":true},{"t":"자전거는 철 한 가지 물질로만 이루어져 있다","mis":"SC3-2-u1-X06"},{"t":"타이어는 섬유, 안장 덮개는 고무이다","mis":"SC3-2-u1-X07"},{"t":"바구니와 몸체는 같은 물질이다","mis":"SC3-2-u1-X07"}],"explanation":["부분마다 읽어요.","네 가지 물질이에요.","여러 물질이에요."],"asset":{"type":"passage","lines":["몸체 — 철 · 바구니 — 플라스틱","타이어 — 고무 · 안장 덮개 — 섬유","타이어 속에는 공기를 넣었어요."],"title":"햇살반 일지 ② 학교 자전거 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#18','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C8',3,'mc','auto','설탕 가루를 여러 모양의 그릇에 부었더니 그릇 모양처럼 쌓였어요. 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X18','SC3-2-u1-X21','SC3-2-u1-X17']::text[],false,'{"seq":18,"concept":"SC3-2-u1-C8","difficulty":3,"kind":"mc","stem":"설탕 가루를 여러 모양의 그릇에 부었더니 그릇 모양처럼 쌓였어요. 알맞게 말한 것은 무엇인가요?","options":[{"t":"알갱이 하나하나의 모양과 부피가 그대로이므로 고체이다","correct":true},{"t":"그릇 모양을 따라 변했으니 액체이다","mis":"SC3-2-u1-X18"},{"t":"알갱이가 작아서 공간을 차지하지 않는다","mis":"SC3-2-u1-X21"},{"t":"단단하지 않으니 고체가 아니다","mis":"SC3-2-u1-X17"}],"explanation":["알갱이 하나를 봐요.","모양이 그대로예요.","고체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#19','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C11',3,'mc','auto','햇살반 일지 ⑥에서 묶은 비닐봉지를 눌러도 납작해지지 않은 까닭은 무엇인가요?',ARRAY['SC3-2-u1-X21','SC3-2-u1-X30','SC3-2-u1-X07']::text[],false,'{"seq":19,"concept":"SC3-2-u1-C11","difficulty":3,"kind":"mc","stem":"햇살반 일지 ⑥에서 묶은 비닐봉지를 눌러도 납작해지지 않은 까닭은 무엇인가요?","options":[{"t":"봉지 속 공기가 공간을 차지하고 있기 때문에","correct":true},{"t":"봉지 속이 비어 있기 때문에","mis":"SC3-2-u1-X21"},{"t":"공기가 고체이기 때문에","mis":"SC3-2-u1-X30"},{"t":"봉지가 철로 되어 있기 때문에","mis":"SC3-2-u1-X07"}],"explanation":["봉지 속에 무엇이 있나요?","공기가 있어요.","공간을 차지해요."],"asset":{"type":"passage","lines":["비닐봉지에 공기를 넣고 입구를 묶었더니 눌러도 납작해지지 않았다.","튜브에 공기를 넣으니 통통하게 부풀었다.","이불 압축 팩에서 공기를 빼니 이불이 납작해졌다."],"title":"햇살반 일지 ⑥ 공기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#20','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C12',3,'mc','auto','햇살반 일지 ⑦에서 친구 나의 말을 바르게 고친 것은 무엇인가요?',ARRAY['SC3-2-u1-X28','SC3-2-u1-X30']::text[],false,'{"seq":20,"concept":"SC3-2-u1-C12","difficulty":3,"kind":"mc","stem":"햇살반 일지 ⑦에서 친구 나의 말을 바르게 고친 것은 무엇인가요?","options":[{"t":"참기름은 물이 없어도 모양이 변하고 부피는 변하지 않으니 액체이다","correct":true},{"t":"참기름은 물이 없으니 고체이다","mis":"SC3-2-u1-X28"},{"t":"참기름에는 사실 물이 들어 있어서 액체이다","mis":"SC3-2-u1-X28"},{"t":"참기름은 기체이다","mis":"SC3-2-u1-X30"}],"explanation":["액체의 성질을 떠올려요.","물이 없어도 돼요.","참기름은 액체예요."],"asset":{"type":"passage","lines":["친구 가 — 「공기는 보이지 않으니 물질이 아니야.」","친구 나 — 「참기름은 물이 없으니 액체가 아니야.」","친구 다 — 「모래는 컵 모양 따라 변하니 액체야.」","선생님 — 세 친구의 말을 배운 것으로 하나씩 따져 보자."],"title":"햇살반 일지 ⑦ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#21','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C13',3,'mc','auto','햇살반 일지 ⑧에서 우산꽂이 통을 철로 만든 까닭은 무엇인가요?',ARRAY['SC3-2-u1-X09','SC3-2-u1-X31','SC3-2-u1-X32']::text[],false,'{"seq":21,"concept":"SC3-2-u1-C13","difficulty":3,"kind":"mc","stem":"햇살반 일지 ⑧에서 우산꽂이 통을 철로 만든 까닭은 무엇인가요?","options":[{"t":"철은 단단해서 우산을 많이 꽂아도 버티기 때문에","correct":true},{"t":"철은 투명해서 우산이 보이기 때문에","mis":"SC3-2-u1-X09"},{"t":"철이 가장 비싼 물질이기 때문에","mis":"SC3-2-u1-X31"},{"t":"철은 잘 미끄러지지 않기 때문에","mis":"SC3-2-u1-X32"}],"explanation":["철의 성질이에요.","단단해요.","많이 꽂아도 버텨요."],"asset":{"type":"passage","lines":["우산꽂이 통 — 철(단단함) · 바닥 — 고무(잘 미끄러지지 않음)","이름표 — 3D 프린터로 플라스틱을 겹겹이 쌓아 만듦","친구 의견 — 「통이 튼튼해서 좋아. 손잡이를 달면 옮기기 더 좋겠어.」"],"title":"햇살반 일지 ⑧ 우산꽂이 설계 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#22','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C14',3,'mc','auto','햇살반 일지 ⑧에서 이름표를 만든 방법을 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X34','SC3-2-u1-X35']::text[],false,'{"seq":22,"concept":"SC3-2-u1-C14","difficulty":3,"kind":"mc","stem":"햇살반 일지 ⑧에서 이름표를 만든 방법을 알맞게 말한 것은 무엇인가요?","options":[{"t":"설계도에 따라 플라스틱을 겹겹이 쌓아 만들었다","correct":true},{"t":"플라스틱 덩어리를 깎아 만들었다","mis":"SC3-2-u1-X34"},{"t":"재료 없이 프린터가 저절로 만들었다","mis":"SC3-2-u1-X34"},{"t":"식재료로만 만들었다","mis":"SC3-2-u1-X35"}],"explanation":["일지를 읽어요.","겹겹이 쌓았어요.","설계도와 플라스틱이에요."],"asset":{"type":"passage","lines":["우산꽂이 통 — 철(단단함) · 바닥 — 고무(잘 미끄러지지 않음)","이름표 — 3D 프린터로 플라스틱을 겹겹이 쌓아 만듦","친구 의견 — 「통이 튼튼해서 좋아. 손잡이를 달면 옮기기 더 좋겠어.」"],"title":"햇살반 일지 ⑧ 우산꽂이 설계 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#23','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C12',4,'mc','auto','햇살반 일지의 물 옮겨 담기(⑤)와 공기 놀이(⑥)를 함께 떠올려 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X30','SC3-2-u1-X19']::text[],false,'{"seq":23,"concept":"SC3-2-u1-C12","difficulty":4,"kind":"mc","stem":"햇살반 일지의 물 옮겨 담기(⑤)와 공기 놀이(⑥)를 함께 떠올려 알맞게 말한 것은 무엇인가요?","options":[{"t":"물은 담는 용기에 따라 모양만 변하고, 공기는 담는 용기를 가득 채우며 공간을 차지한다","correct":true},{"t":"물과 공기 모두 모양이 그대로이다","mis":"SC3-2-u1-X30"},{"t":"물은 부피가 변하고 공기는 공간을 차지하지 않는다","mis":"SC3-2-u1-X19"},{"t":"물과 공기는 같은 상태이다","mis":"SC3-2-u1-X30"}],"explanation":["⑤는 물이에요.","⑥은 공기예요.","두 상태를 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#24','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C4',4,'essay','teacher','햇살반 일지 ②의 자전거를 보고 부분마다 어떤 물질로 이루어졌는지 쓰고, 그 물질을 고른 까닭을 성질과 이어 두 가지 이상 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC3-2-u1-C4","difficulty":4,"kind":"essay","stem":"햇살반 일지 ②의 자전거를 보고 부분마다 어떤 물질로 이루어졌는지 쓰고, 그 물질을 고른 까닭을 성질과 이어 두 가지 이상 쓰세요.","answer_guide":{"answer":"예: 몸체는 철, 바구니는 플라스틱, 타이어는 고무, 안장 덮개는 섬유로 이루어져 있다. 몸체는 단단한 철이라서 사람이 타도 잘 버틴다. 바구니는 가벼운 편인 플라스틱이라서 자전거가 무거워지지 않는다. 타이어는 잘 미끄러지지 않는 고무라서 길에서 덜 미끄러진다.","scoring_points":["부분마다 물질을 바르게 썼는가","물질을 고른 까닭을 성질과 이어 썼는가","까닭을 두 가지 이상 썼는가"]},"explanation":["부분마다 써요.","성질을 떠올려요.","까닭과 이어요."],"asset":{"type":"passage","lines":["몸체 — 철 · 바구니 — 플라스틱","타이어 — 고무 · 안장 덮개 — 섬유","타이어 속에는 공기를 넣었어요."],"title":"햇살반 일지 ② 학교 자전거 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_a#25','sci',3,2,'u1','','g3_2_sci_u1_review_a','unit_review','SC3-2-u1-C12',4,'essay','teacher','햇살반 일지 ⑦의 세 친구 말을 하나씩 골라 바로잡으세요. 각각 배운 성질을 근거로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-2-u1-C12","difficulty":4,"kind":"essay","stem":"햇살반 일지 ⑦의 세 친구 말을 하나씩 골라 바로잡으세요. 각각 배운 성질을 근거로 쓰세요.","answer_guide":{"answer":"예: 친구 가 — 공기는 보이지 않지만 탁구공 실험에서 물을 밀어낸 것처럼 공간을 차지하므로 물질이다. 친구 나 — 참기름은 물이 없어도 담는 용기에 따라 모양은 변하고 부피는 변하지 않으므로 액체이다. 친구 다 — 모래 알갱이 하나하나는 모양과 부피가 변하지 않으므로 고체이다.","scoring_points":["세 친구의 말을 모두 바로잡았는가","각각 배운 성질을 근거로 들었는가","공기·참기름·모래의 상태를 바르게 썼는가"]},"explanation":["친구 가부터 따져요.","성질을 근거로 들어요.","셋 다 바로잡아요."],"asset":{"type":"passage","lines":["친구 가 — 「공기는 보이지 않으니 물질이 아니야.」","친구 나 — 「참기름은 물이 없으니 액체가 아니야.」","친구 다 — 「모래는 컵 모양 따라 변하니 액체야.」","선생님 — 세 친구의 말을 배운 것으로 하나씩 따져 보자."],"title":"햇살반 일지 ⑦ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#1','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C1',1,'sa','auto','모양이 있고 공간을 차지하는 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC3-2-u1-C1","difficulty":1,"kind":"sa","stem":"모양이 있고 공간을 차지하는 것을 두 글자로 쓰세요.","answer":["물체"],"explanation":["책상, 의자를 떠올려요.","물◯예요.","물체예요."],"mis":"SC3-2-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#2','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C3',1,'sa','auto','집게는 어떤 물질로 이루어져 있나요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-2-u1-C3","difficulty":1,"kind":"sa","stem":"집게는 어떤 물질로 이루어져 있나요? 한 글자로 쓰세요.","answer":["철"],"explanation":["단단하고 반짝여요.","집게를 떠올려요.","철이에요."],"mis":"SC3-2-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#3','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C4',1,'sa','auto','천처럼 부드러워 안장 덮개를 만든 물질을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC3-2-u1-C4","difficulty":1,"kind":"sa","stem":"천처럼 부드러워 안장 덮개를 만든 물질을 두 글자로 쓰세요.","answer":["섬유"],"explanation":["천이에요.","옷도 이것이에요.","섬유예요."],"mis":"SC3-2-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#4','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C6',1,'sa','auto','고유한 향과 무늬가 있는 물질을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-2-u1-C6","difficulty":1,"kind":"sa","stem":"고유한 향과 무늬가 있는 물질을 두 글자로 쓰세요.","answer":["나무"],"explanation":["나무 블록을 떠올려요.","향이 나요.","나무예요."],"mis":"SC3-2-u1-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#5','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C7',1,'sa','auto','비커는 어떤 물질로 분류하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-2-u1-C7","difficulty":1,"kind":"sa","stem":"비커는 어떤 물질로 분류하나요? 두 글자로 쓰세요.","answer":["유리"],"explanation":["투명해요.","깨질 수 있어요.","유리예요."],"mis":"SC3-2-u1-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#6','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C8',1,'sa','auto','물질이 차지하는 공간의 크기를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SC3-2-u1-C8","difficulty":1,"kind":"sa","stem":"물질이 차지하는 공간의 크기를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["부피"],"explanation":["공간의 크기예요.","부◯예요.","부피예요."],"mis":"SC3-2-u1-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#7','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C9',1,'sa','auto','물의 높이를 표시할 때 쓰는 펜을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SC3-2-u1-C9","difficulty":1,"kind":"sa","stem":"물의 높이를 표시할 때 쓰는 펜을 세 글자로 쓰세요.","answer":["유성펜"],"explanation":["물에 잘 지워지지 않아요.","◯◯펜이에요.","유성펜이에요."],"mis":"SC3-2-u1-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#8','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C11',1,'sa','auto','기체 가운데 우리가 오늘 살펴본 것을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SC3-2-u1-C11","difficulty":1,"kind":"sa","stem":"기체 가운데 우리가 오늘 살펴본 것을 두 글자로 쓰세요.","answer":["공기"],"explanation":["풍선 속을 채워요.","숨 쉴 때도 있어요.","공기예요."],"mis":"SC3-2-u1-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#9','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C2',2,'match','auto','재료와 쓰임새 단서를 보고 물체를 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SC3-2-u1-C2","difficulty":2,"kind":"match","stem":"재료와 쓰임새 단서를 보고 물체를 알맞게 이으세요.","pairs":[{"l":"철로 되어 있어 단단하고 국을 떠먹어요","r":"숟가락"},{"l":"유리로 되어 있어 속이 비치고 굴리며 놀아요","r":"유리구슬"},{"l":"종이로 되어 있어 넘길 수 있어요","r":"책"}],"mis":"SC3-2-u1-X02","explanation":["재료를 봐요.","쓰임새를 봐요.","숟가락, 유리구슬, 책이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#10','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C5',2,'match','auto','살펴본 것과 감각을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-2-u1-C5","difficulty":2,"kind":"match","stem":"살펴본 것과 감각을 알맞게 이으세요.","pairs":[{"l":"유리컵이 투명한 정도","r":"눈"},{"l":"나무 젓가락의 향","r":"코"},{"l":"철 숟가락이 단단한 정도","r":"손"}],"mis":"SC3-2-u1-X03","explanation":["보는 것, 맡는 것, 만지는 것이에요.","향은 코예요.","투명은 눈, 단단함은 손이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#11','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C6',2,'match','auto','물체와 그 물질을 고른 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SC3-2-u1-C6","difficulty":2,"kind":"match","stem":"물체와 그 물질을 고른 까닭을 알맞게 이으세요.","pairs":[{"l":"창문 — 유리","r":"투명해서 바깥이 보여요"},{"l":"열쇠 — 철","r":"단단해서 쉽게 부러지지 않아요"},{"l":"장난감 블록 — 플라스틱","r":"색깔과 모양을 다양하게 만들 수 있어요"}],"mis":"SC3-2-u1-X10","explanation":["물질의 성질을 떠올려요.","쓰임새와 이어요.","투명, 단단, 다양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#12','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C7',2,'match','auto','물체와 그 물체를 분류할 물질의 무리를 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"SC3-2-u1-C7","difficulty":2,"kind":"match","stem":"물체와 그 물체를 분류할 물질의 무리를 알맞게 이으세요.","pairs":[{"l":"야구 방망이","r":"나무"},{"l":"용수철","r":"철"},{"l":"유리 주전자","r":"유리"},{"l":"물뿌리개","r":"플라스틱"}],"mis":"SC3-2-u1-X13","explanation":["성질을 떠올려요.","용수철은 반짝여요.","나무, 철, 유리, 플라스틱이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#13','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C9',2,'match','auto','햇살반 일지 ⑤의 장면과 알 수 있는 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SC3-2-u1-C9","difficulty":2,"kind":"match","stem":"햇살반 일지 ⑤의 장면과 알 수 있는 것을 알맞게 이으세요.","pairs":[{"l":"넓은 접시","r":"모양이 접시 모양으로 변해요"},{"l":"길쭉한 병","r":"높아 보여도 부피는 같아요"},{"l":"처음 컵에 다시 부음","r":"처음 높이와 같아요"}],"mis":"SC3-2-u1-X19","explanation":["모양은 용기를 따라요.","높아 보일 뿐이에요.","다시 부으면 같아요."],"asset":{"type":"passage","lines":["① 처음 컵에 담긴 물의 높이를 유성펜으로 표시했다.","② 넓은 접시에 옮기니 물이 낮게 퍼졌다.","③ 길쭉한 병에 옮기니 물이 높아 보였다.","④ 처음 컵에 다시 부으니 처음 표시와 높이가 같았다."],"title":"햇살반 일지 ⑤ 물 옮겨 담기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#14','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C10',2,'match','auto','탁구공 실험에서 한 일과 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":14,"concept":"SC3-2-u1-C10","difficulty":2,"kind":"match","stem":"탁구공 실험에서 한 일과 까닭을 알맞게 이으세요.","pairs":[{"l":"물 높이를 유성펜으로 표시해요","r":"처음 높이와 비교하려고"},{"l":"잘린 부분을 절연 테이프로 감싸요","r":"다치지 않으려고"},{"l":"뚜껑을 닫고 밀어 넣어요","r":"공기가 빠져나가지 않게 하려고"}],"mis":"SC3-2-u1-X23","explanation":["표시는 비교하려고예요.","테이프는 안전이에요.","뚜껑은 공기를 가두려고예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#15','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C12',2,'match','auto','물질과 상태를 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SC3-2-u1-C12","difficulty":2,"kind":"match","stem":"물질과 상태를 알맞게 이으세요.","pairs":[{"l":"식용유","r":"액체"},{"l":"휠체어","r":"고체"},{"l":"타이어 속 공기","r":"기체"}],"mis":"SC3-2-u1-X30","explanation":["흐르면 액체예요.","잡히면 고체예요.","공기는 기체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#16','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C14',2,'match','auto','3D 프린터 재료와 만든 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":16,"concept":"SC3-2-u1-C14","difficulty":2,"kind":"match","stem":"3D 프린터 재료와 만든 것을 알맞게 이으세요.","pairs":[{"l":"식재료","r":"과자"},{"l":"금속","r":"자동차 부품"},{"l":"플라스틱","r":"장난감"}],"mis":"SC3-2-u1-X35","explanation":["먹는 것은 식재료예요.","부품은 금속이에요.","장난감은 플라스틱이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#17','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C12',3,'mc','auto','햇살반 일지 ②의 자전거에서 상태가 다른 하나는 무엇인가요?',ARRAY['SC3-2-u1-X29']::text[],false,'{"seq":17,"concept":"SC3-2-u1-C12","difficulty":3,"kind":"mc","stem":"햇살반 일지 ②의 자전거에서 상태가 다른 하나는 무엇인가요?","options":[{"t":"타이어 속 공기","correct":true},{"t":"타이어","mis":"SC3-2-u1-X29"},{"t":"몸체","mis":"SC3-2-u1-X29"},{"t":"바구니","mis":"SC3-2-u1-X29"}],"explanation":["셋은 손으로 잡혀요.","하나는 보이지 않아요.","타이어 속 공기예요."],"asset":{"type":"passage","lines":["몸체 — 철 · 바구니 — 플라스틱","타이어 — 고무 · 안장 덮개 — 섬유","타이어 속에는 공기를 넣었어요."],"title":"햇살반 일지 ② 학교 자전거 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#18','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C8',3,'ox','auto','모래는 컵 모양에 따라 모양이 변하니 액체예요.',ARRAY['SC3-2-u1-X18']::text[],false,'{"seq":18,"concept":"SC3-2-u1-C8","difficulty":3,"kind":"ox","stem":"모래는 컵 모양에 따라 모양이 변하니 액체예요.","answer":"X","reason_options":[{"t":"모래 알갱이 하나하나는 모양과 부피가 변하지 않는 고체이기 때문에","correct":true},{"t":"컵 모양을 따라 쌓이면 모두 액체이기 때문에","mis":"SC3-2-u1-X18"}],"mis":"SC3-2-u1-X18","explanation":["돋보기로 봐요.","알갱이는 그대로예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#19','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C11',3,'mc','auto','햇살반 일지 ⑥에서 공기를 빼내어 쓴 것은 무엇인가요?',ARRAY['SC3-2-u1-X26']::text[],false,'{"seq":19,"concept":"SC3-2-u1-C11","difficulty":3,"kind":"mc","stem":"햇살반 일지 ⑥에서 공기를 빼내어 쓴 것은 무엇인가요?","options":[{"t":"이불 압축 팩","correct":true},{"t":"튜브","mis":"SC3-2-u1-X26"},{"t":"비닐봉지","mis":"SC3-2-u1-X26"},{"t":"모두 공기를 넣어 썼다","mis":"SC3-2-u1-X26"}],"explanation":["납작해진 것을 찾아요.","공기를 뺐어요.","이불 압축 팩이에요."],"asset":{"type":"passage","lines":["비닐봉지에 공기를 넣고 입구를 묶었더니 눌러도 납작해지지 않았다.","튜브에 공기를 넣으니 통통하게 부풀었다.","이불 압축 팩에서 공기를 빼니 이불이 납작해졌다."],"title":"햇살반 일지 ⑥ 공기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#20','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C12',3,'mc','auto','햇살반 일지 ⑦에서 친구 가의 말을 바르게 고친 것은 무엇인가요?',ARRAY['SC3-2-u1-X21','SC3-2-u1-X30','SC3-2-u1-X24']::text[],false,'{"seq":20,"concept":"SC3-2-u1-C12","difficulty":3,"kind":"mc","stem":"햇살반 일지 ⑦에서 친구 가의 말을 바르게 고친 것은 무엇인가요?","options":[{"t":"공기는 보이지 않지만 공간을 차지하는 물질이다","correct":true},{"t":"공기는 보이지 않으니 공간을 차지하지 않는다","mis":"SC3-2-u1-X21"},{"t":"공기는 고체라서 물질이다","mis":"SC3-2-u1-X30"},{"t":"공기와 기체는 같은 말이라서 물질이 아니다","mis":"SC3-2-u1-X24"}],"explanation":["탁구공 실험을 떠올려요.","공간을 차지했어요.","공기도 물질이에요."],"asset":{"type":"passage","lines":["친구 가 — 「공기는 보이지 않으니 물질이 아니야.」","친구 나 — 「참기름은 물이 없으니 액체가 아니야.」","친구 다 — 「모래는 컵 모양 따라 변하니 액체야.」","선생님 — 세 친구의 말을 배운 것으로 하나씩 따져 보자."],"title":"햇살반 일지 ⑦ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#21','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C13',3,'mc','auto','햇살반 일지 ⑧의 친구 의견이 좋은 까닭은 무엇인가요?',ARRAY['SC3-2-u1-X33','SC3-2-u1-X31']::text[],false,'{"seq":21,"concept":"SC3-2-u1-C13","difficulty":3,"kind":"mc","stem":"햇살반 일지 ⑧의 친구 의견이 좋은 까닭은 무엇인가요?","options":[{"t":"잘한 점을 먼저 말하고 보완할 점을 대안과 함께 말했기 때문에","correct":true},{"t":"잘못된 점만 골라 말했기 때문에","mis":"SC3-2-u1-X33"},{"t":"자기 설계가 더 좋다고 말했기 때문에","mis":"SC3-2-u1-X33"},{"t":"비싼 물질로 바꾸라고 했기 때문에","mis":"SC3-2-u1-X31"}],"explanation":["「튼튼해서 좋아」가 있어요.","「손잡이를 달면」이 있어요.","대안이 있어요."],"asset":{"type":"passage","lines":["우산꽂이 통 — 철(단단함) · 바닥 — 고무(잘 미끄러지지 않음)","이름표 — 3D 프린터로 플라스틱을 겹겹이 쌓아 만듦","친구 의견 — 「통이 튼튼해서 좋아. 손잡이를 달면 옮기기 더 좋겠어.」"],"title":"햇살반 일지 ⑧ 우산꽂이 설계 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#22','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C14',3,'mc','auto','이름표를 3D 프린터로 만들 때 플라스틱을 쓰면 좋은 까닭은 무엇인가요?',ARRAY['SC3-2-u1-X09','SC3-2-u1-X35','SC3-2-u1-X08']::text[],false,'{"seq":22,"concept":"SC3-2-u1-C14","difficulty":3,"kind":"mc","stem":"이름표를 3D 프린터로 만들 때 플라스틱을 쓰면 좋은 까닭은 무엇인가요?","options":[{"t":"색깔과 모양을 다양하게 만들 수 있어서","correct":true},{"t":"투명하고 깨지기 쉬워서","mis":"SC3-2-u1-X09"},{"t":"먹을 수 있는 재료라서","mis":"SC3-2-u1-X35"},{"t":"가장 무거운 물질이라서","mis":"SC3-2-u1-X08"}],"explanation":["플라스틱의 성질이에요.","여러 색이에요.","다양하게 만들 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#23','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C7',4,'mc','auto','햇살반 일지 ③의 물체를 물질의 종류로 분류하고 까닭을 바르게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X13','SC3-2-u1-X14','SC3-2-u1-X12']::text[],false,'{"seq":23,"concept":"SC3-2-u1-C7","difficulty":4,"kind":"mc","stem":"햇살반 일지 ③의 물체를 물질의 종류로 분류하고 까닭을 바르게 말한 것은 무엇인가요?","options":[{"t":"나무 젓가락 — 나무(향과 무늬) · 철 숟가락 — 철(광택, 단단함) · 유리컵 — 유리(투명함)","correct":true},{"t":"나무 젓가락 — 철(무거움) · 철 숟가락 — 나무 · 유리컵 — 유리","mis":"SC3-2-u1-X13"},{"t":"모두 그릇이니 한 무리 · 까닭은 없음","mis":"SC3-2-u1-X14"},{"t":"색깔이 예쁜 것과 안 예쁜 것으로 두 무리","mis":"SC3-2-u1-X12"}],"explanation":["성질을 봐요.","물질 종류로 나눠요.","까닭도 성질로 말해요."],"asset":{"type":"passage","lines":["나무 젓가락 — 고유한 향과 무늬가 있다.","철 숟가락 — 광택이 있고 단단하다.","유리컵 — 투명하지만 깨지기 쉽다.","플라스틱 접시 — 색깔과 모양이 여러 가지이다.","덧붙임 — 큰 나무 도마는 나무 젓가락보다 무거웠다."],"title":"햇살반 일지 ③ 급식실 물질 관찰표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#24','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C9',4,'essay','teacher','햇살반 일지 ⑤를 보고 물의 부피가 변했는지 판단하고, 그렇게 판단한 근거를 쓰세요. 「높아 보인다」와 「부피가 늘었다」가 어떻게 다른지도 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC3-2-u1-C9","difficulty":4,"kind":"essay","stem":"햇살반 일지 ⑤를 보고 물의 부피가 변했는지 판단하고, 그렇게 판단한 근거를 쓰세요. 「높아 보인다」와 「부피가 늘었다」가 어떻게 다른지도 쓰세요.","answer_guide":{"answer":"예: 물의 부피는 변하지 않았다. 처음 컵에 다시 부었을 때 처음 표시한 높이와 같았기 때문이다. 길쭉한 병에서 높아 보인 것은 병이 좁아서 물의 모양이 위로 길어졌을 뿐이고, 물이 차지하는 공간의 크기인 부피가 늘어난 것은 아니다.","scoring_points":["부피가 변하지 않았다고 판단했는가","다시 부은 결과를 근거로 들었는가","높아 보이는 것과 부피를 구별해 썼는가"]},"explanation":["판단을 써요.","④를 근거로 들어요.","높이와 부피를 나눠요."],"asset":{"type":"passage","lines":["① 처음 컵에 담긴 물의 높이를 유성펜으로 표시했다.","② 넓은 접시에 옮기니 물이 낮게 퍼졌다.","③ 길쭉한 병에 옮기니 물이 높아 보였다.","④ 처음 컵에 다시 부으니 처음 표시와 높이가 같았다."],"title":"햇살반 일지 ⑤ 물 옮겨 담기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_b#25','sci',3,2,'u1','','g3_2_sci_u1_review_b','unit_review','SC3-2-u1-C13',4,'essay','teacher','햇살반 일지 ⑧의 우산꽂이 설계를 보고 잘한 점 하나를 물질의 성질과 이어 쓰고, 보완할 점 하나를 더 좋은 방법과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-2-u1-C13","difficulty":4,"kind":"essay","stem":"햇살반 일지 ⑧의 우산꽂이 설계를 보고 잘한 점 하나를 물질의 성질과 이어 쓰고, 보완할 점 하나를 더 좋은 방법과 함께 쓰세요.","answer_guide":{"answer":"예: 잘한 점 — 바닥에 잘 미끄러지지 않는 고무를 붙여 우산꽂이가 바닥에서 밀리지 않는다. 보완할 점 — 통이 철이라 무거울 수 있으니, 옮기기 쉽게 가벼운 플라스틱 손잡이를 달면 더 좋겠다.","scoring_points":["잘한 점을 썼는가","잘한 점을 물질의 성질과 이어 썼는가","보완할 점을 대안과 함께 썼는가"]},"explanation":["잘한 점부터 써요.","성질과 이어요.","대안을 함께 써요."],"asset":{"type":"passage","lines":["우산꽂이 통 — 철(단단함) · 바닥 — 고무(잘 미끄러지지 않음)","이름표 — 3D 프린터로 플라스틱을 겹겹이 쌓아 만듦","친구 의견 — 「통이 튼튼해서 좋아. 손잡이를 달면 옮기기 더 좋겠어.」"],"title":"햇살반 일지 ⑧ 우산꽂이 설계 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#1','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C2',1,'ox','auto','탐정놀이에서는 어려운 단서부터 하나씩 말해요.',ARRAY['SC3-2-u1-X04']::text[],false,'{"seq":1,"concept":"SC3-2-u1-C2","difficulty":1,"kind":"ox","stem":"탐정놀이에서는 어려운 단서부터 하나씩 말해요.","answer":"O","reason_options":[{"t":"쉬운 단서를 먼저 주면 놀이가 금방 끝나기 때문에","correct":true},{"t":"정답을 먼저 알려 주어야 하기 때문에","mis":"SC3-2-u1-X04"}],"mis":"SC3-2-u1-X04","explanation":["단서 차례를 떠올려요.","어려운 것부터예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#2','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C3',1,'ox','auto','윷은 물질이고 나무는 물체예요.',ARRAY['SC3-2-u1-X05']::text[],false,'{"seq":2,"concept":"SC3-2-u1-C3","difficulty":1,"kind":"ox","stem":"윷은 물질이고 나무는 물체예요.","answer":"X","reason_options":[{"t":"윷은 물체이고 윷을 이루는 나무가 물질이기 때문에","correct":true},{"t":"모양이 있는 것을 물질이라고 하기 때문에","mis":"SC3-2-u1-X05"}],"mis":"SC3-2-u1-X05","explanation":["윷은 모양이 있어요.","나무는 재료예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#3','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C4',1,'ox','auto','한 물체가 여러 가지 물질로 이루어질 수 있어요.',ARRAY['SC3-2-u1-X06']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C4","difficulty":1,"kind":"ox","stem":"한 물체가 여러 가지 물질로 이루어질 수 있어요.","answer":"O","reason_options":[{"t":"가위처럼 손잡이와 날의 물질이 다른 물체가 있기 때문에","correct":true},{"t":"물체는 언제나 한 가지 물질로만 만들기 때문에","mis":"SC3-2-u1-X06"}],"mis":"SC3-2-u1-X06","explanation":["가위를 떠올려요.","손잡이와 날이 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#4','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C6',1,'ox','auto','유리는 투명해요.',ARRAY['SC3-2-u1-X09']::text[],false,'{"seq":4,"concept":"SC3-2-u1-C6","difficulty":1,"kind":"ox","stem":"유리는 투명해요.","answer":"O","reason_options":[{"t":"유리는 속이 비쳐 보이기 때문에","correct":true},{"t":"유리는 광택만 있고 속이 보이지 않기 때문에","mis":"SC3-2-u1-X09"}],"mis":"SC3-2-u1-X09","explanation":["창문을 떠올려요.","바깥이 보여요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#5','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C7',1,'ox','auto','「보기에 예쁜가요?」는 누가 나누어도 같은 결과가 나오는 기준이에요.',ARRAY['SC3-2-u1-X12']::text[],false,'{"seq":5,"concept":"SC3-2-u1-C7","difficulty":1,"kind":"ox","stem":"「보기에 예쁜가요?」는 누가 나누어도 같은 결과가 나오는 기준이에요.","answer":"X","reason_options":[{"t":"예쁜지는 사람마다 다르게 생각하기 때문에","correct":true},{"t":"예쁜 것은 모두 같은 물질이기 때문에","mis":"SC3-2-u1-X12"}],"mis":"SC3-2-u1-X12","explanation":["사람마다 달라요.","결과가 달라져요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#6','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C8',1,'ox','auto','스펀지는 단단하지 않지만 고체예요.',ARRAY['SC3-2-u1-X17']::text[],false,'{"seq":6,"concept":"SC3-2-u1-C8","difficulty":1,"kind":"ox","stem":"스펀지는 단단하지 않지만 고체예요.","answer":"O","reason_options":[{"t":"담는 용기에 따라 모양과 부피가 변하지 않기 때문에","correct":true},{"t":"단단한 것만 고체이기 때문에","mis":"SC3-2-u1-X17"}],"mis":"SC3-2-u1-X17","explanation":["스펀지를 컵에 넣어요.","모양이 그대로예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#7','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C9',1,'ox','auto','액체는 손으로 잡을 수 있어요.',ARRAY['SC3-2-u1-X20']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C9","difficulty":1,"kind":"ox","stem":"액체는 손으로 잡을 수 있어요.","answer":"X","reason_options":[{"t":"액체는 흐르는 성질이 있기 때문에","correct":true},{"t":"액체는 모양이 그대로이기 때문에","mis":"SC3-2-u1-X20"}],"mis":"SC3-2-u1-X20","explanation":["물을 잡아 봐요.","빠져나가요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#8','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C11',1,'ox','auto','기체는 담는 용기를 가득 채워요.',ARRAY['SC3-2-u1-X25']::text[],false,'{"seq":8,"concept":"SC3-2-u1-C11","difficulty":1,"kind":"ox","stem":"기체는 담는 용기를 가득 채워요.","answer":"O","reason_options":[{"t":"풍선 속 공기가 풍선 안을 가득 채우기 때문에","correct":true},{"t":"기체는 용기의 바닥에만 모이기 때문에","mis":"SC3-2-u1-X25"}],"mis":"SC3-2-u1-X25","explanation":["풍선을 떠올려요.","가득 부풀어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#9','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C2',2,'error','auto','단서를 두고 친구들이 이야기했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u1-X02','SC3-2-u1-X03']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C2","difficulty":2,"kind":"error","stem":"단서를 두고 친구들이 이야기했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「생김새만 말해도 재료를 말할 때와 똑같이 잘 맞혀.」","correct":true,"mis_target":"SC3-2-u1-X02"},{"t":"친구 가 — 「재료를 말하면 물체를 맞히기 쉬워.」","mis":"SC3-2-u1-X02"},{"t":"친구 다 — 「눈, 손, 귀로도 단서를 찾을 수 있어.」","mis":"SC3-2-u1-X03"}],"explanation":["재료 단서를 떠올려요.","더 잘 맞혀요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#10','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C5',2,'ox','auto','무게는 물질마다 정해져 있는 성질이에요.',ARRAY['SC3-2-u1-X08']::text[],false,'{"seq":10,"concept":"SC3-2-u1-C5","difficulty":2,"kind":"ox","stem":"무게는 물질마다 정해져 있는 성질이에요.","answer":"X","reason_options":[{"t":"같은 물질이라도 크기와 모양에 따라 무게가 달라지기 때문에","correct":true},{"t":"같은 물질은 크기와 관계없이 무게가 같기 때문에","mis":"SC3-2-u1-X08"}],"mis":"SC3-2-u1-X08","explanation":["통나무와 블록을 떠올려요.","무게가 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#11','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C6',2,'error','auto','물질과 쓰임새를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u1-X11','SC3-2-u1-X10']::text[],false,'{"seq":11,"concept":"SC3-2-u1-C6","difficulty":2,"kind":"error","stem":"물질과 쓰임새를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「플라스틱은 한 가지 색으로만 만들 수 있어서 장난감에 써.」","correct":true,"mis_target":"SC3-2-u1-X11"},{"t":"친구 가 — 「유리는 투명해서 창문에 써.」","mis":"SC3-2-u1-X10"},{"t":"친구 나 — 「철은 단단해서 열쇠에 써.」","mis":"SC3-2-u1-X10"}],"explanation":["플라스틱의 성질이에요.","색깔이 다양해요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#12','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C7',2,'error','auto','물체 나누기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u1-X14','SC3-2-u1-X12','SC3-2-u1-X13']::text[],false,'{"seq":12,"concept":"SC3-2-u1-C7","difficulty":2,"kind":"error","stem":"물체 나누기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「나눈 까닭은 말하지 않아도 돼.」","correct":true,"mis_target":"SC3-2-u1-X14"},{"t":"친구 가 — 「철로 이루어져 있나요?로 나누면 누가 해도 같아.」","mis":"SC3-2-u1-X12"},{"t":"친구 나 — 「꽃병은 투명하고 깨질 수 있어서 유리야.」","mis":"SC3-2-u1-X13"}],"explanation":["분류할 때 함께 말할 것이 있어요.","까닭이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
