INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#17','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C4',3,'error','auto','햇살반 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u1-X29','SC3-2-u1-X07']::text[],false,'{"seq":17,"concept":"SC3-2-u1-C4","difficulty":3,"kind":"error","stem":"햇살반 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「타이어와 타이어 속 공기는 둘 다 고무야.」","correct":true,"mis_target":"SC3-2-u1-X29"},{"t":"친구 가 — 「몸체는 철이라 단단해.」","mis":"SC3-2-u1-X07"},{"t":"친구 나 — 「바구니는 플라스틱이라 가벼워.」","mis":"SC3-2-u1-X07"}],"explanation":["타이어 속을 따로 봐요.","속에는 공기가 있어요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["몸체 — 철 · 바구니 — 플라스틱","타이어 — 고무 · 안장 덮개 — 섬유","타이어 속에는 공기를 넣었어요."],"title":"햇살반 일지 ② 학교 자전거 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#18','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C8',3,'error','auto','고체를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u1-X17','SC3-2-u1-X18','SC3-2-u1-X16']::text[],false,'{"seq":18,"concept":"SC3-2-u1-C8","difficulty":3,"kind":"error","stem":"고체를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「종이는 쉽게 구겨지니까 고체가 아니야.」","correct":true,"mis_target":"SC3-2-u1-X17"},{"t":"친구 나 — 「모래 알갱이 하나는 모양이 그대로야.」","mis":"SC3-2-u1-X18"},{"t":"친구 다 — 「고체는 손으로 잡을 수 있어.」","mis":"SC3-2-u1-X16"}],"explanation":["종이를 떠올려요.","단단하지 않아도 고체예요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#19','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C11',3,'error','auto','햇살반 일지 ⑥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u1-X25','SC3-2-u1-X24']::text[],false,'{"seq":19,"concept":"SC3-2-u1-C11","difficulty":3,"kind":"error","stem":"햇살반 일지 ⑥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「튜브 속 공기는 튜브의 아랫부분만 채워.」","correct":true,"mis_target":"SC3-2-u1-X25"},{"t":"친구 가 — 「튜브 속 공기는 튜브 모양을 따라 가득 채워.」","mis":"SC3-2-u1-X25"},{"t":"친구 다 — 「공기는 기체의 한 가지야.」","mis":"SC3-2-u1-X24"}],"explanation":["기체는 가득 채워요.","일부만 채우지 않아요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["비닐봉지에 공기를 넣고 입구를 묶었더니 눌러도 납작해지지 않았다.","튜브에 공기를 넣으니 통통하게 부풀었다.","이불 압축 팩에서 공기를 빼니 이불이 납작해졌다."],"title":"햇살반 일지 ⑥ 공기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#20','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C12',3,'mc','auto','햇살반 일지 ⑦에서 친구 다의 말을 바르게 고친 것은 무엇인가요?',ARRAY['SC3-2-u1-X18','SC3-2-u1-X17','SC3-2-u1-X27']::text[],false,'{"seq":20,"concept":"SC3-2-u1-C12","difficulty":3,"kind":"mc","stem":"햇살반 일지 ⑦에서 친구 다의 말을 바르게 고친 것은 무엇인가요?","options":[{"t":"모래 알갱이 하나하나는 모양과 부피가 그대로이니 고체이다","correct":true},{"t":"모래는 흐르니 액체가 맞다","mis":"SC3-2-u1-X18"},{"t":"모래는 단단하지 않으니 고체가 아니다","mis":"SC3-2-u1-X17"},{"t":"모래는 공간을 차지하지 않는다","mis":"SC3-2-u1-X27"}],"explanation":["알갱이 하나를 봐요.","모양이 그대로예요.","모래는 고체예요."],"asset":{"type":"passage","lines":["친구 가 — 「공기는 보이지 않으니 물질이 아니야.」","친구 나 — 「참기름은 물이 없으니 액체가 아니야.」","친구 다 — 「모래는 컵 모양 따라 변하니 액체야.」","선생님 — 세 친구의 말을 배운 것으로 하나씩 따져 보자."],"title":"햇살반 일지 ⑦ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#21','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C13',3,'error','auto','햇살반 일지 ⑧을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u1-X32','SC3-2-u1-X31']::text[],false,'{"seq":21,"concept":"SC3-2-u1-C13","difficulty":3,"kind":"error","stem":"햇살반 일지 ⑧을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「바닥은 유리로 바꿔야 덜 미끄러져.」","correct":true,"mis_target":"SC3-2-u1-X32"},{"t":"친구 나 — 「바닥 고무 덕분에 밀리지 않아.」","mis":"SC3-2-u1-X32"},{"t":"친구 다 — 「통이 단단해서 넘어져도 찌그러지지 않겠어.」","mis":"SC3-2-u1-X31"}],"explanation":["미끄럼을 막는 물질은요?","고무예요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["우산꽂이 통 — 철(단단함) · 바닥 — 고무(잘 미끄러지지 않음)","이름표 — 3D 프린터로 플라스틱을 겹겹이 쌓아 만듦","친구 의견 — 「통이 튼튼해서 좋아. 손잡이를 달면 옮기기 더 좋겠어.」"],"title":"햇살반 일지 ⑧ 우산꽂이 설계 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#22','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C14',3,'error','auto','3D 프린터의 재료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-2-u1-X34','SC3-2-u1-X35']::text[],false,'{"seq":22,"concept":"SC3-2-u1-C14","difficulty":3,"kind":"error","stem":"3D 프린터의 재료를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「3D 프린터는 물질이 아닌 것도 만들어 내.」","correct":true,"mis_target":"SC3-2-u1-X34"},{"t":"친구 가 — 「설계도에 따라 물질을 쌓아.」","mis":"SC3-2-u1-X34"},{"t":"친구 나 — 「쓰임새에 알맞은 재료를 골라.」","mis":"SC3-2-u1-X35"}],"explanation":["모든 물체는 물질로 이루어져요.","물질을 쌓아요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#23','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C13',4,'mc','auto','들고 다니는 독서대를 설계할 때 가장 알맞게 고른 것은 무엇인가요?',ARRAY['SC3-2-u1-X32','SC3-2-u1-X31','SC3-2-u1-X06']::text[],false,'{"seq":23,"concept":"SC3-2-u1-C13","difficulty":4,"kind":"mc","stem":"들고 다니는 독서대를 설계할 때 가장 알맞게 고른 것은 무엇인가요?","options":[{"t":"몸통 — 가벼운 플라스틱 · 바닥 — 미끄러지지 않는 고무 · 받침대 — 단단한 철","correct":true},{"t":"몸통 — 무거운 철 · 바닥 — 유리 · 받침대 — 섬유","mis":"SC3-2-u1-X32"},{"t":"모든 부분 — 가장 비싼 물질","mis":"SC3-2-u1-X31"},{"t":"몸통 — 유리 · 바닥 — 유리 · 받침대 — 유리","mis":"SC3-2-u1-X06"}],"explanation":["부분마다 쓰임새가 달라요.","성질을 맞춰요.","플라스틱, 고무, 철이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#24','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C11',4,'essay','teacher','햇살반 일지 ⑥의 세 가지 놀이를 공기의 성질로 설명하세요. 공기를 넣어 쓰는 물체와 빼내어 쓰는 물체를 하나씩 들어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC3-2-u1-C11","difficulty":4,"kind":"essay","stem":"햇살반 일지 ⑥의 세 가지 놀이를 공기의 성질로 설명하세요. 공기를 넣어 쓰는 물체와 빼내어 쓰는 물체를 하나씩 들어 쓰세요.","answer_guide":{"answer":"예: 공기는 눈에 보이지 않지만 공간을 차지한다. 그래서 공기를 넣고 묶은 비닐봉지는 눌러도 납작해지지 않고, 튜브는 공기를 넣으면 통통하게 부푼다. 이불 압축 팩은 공기를 빼면 공기가 차지하던 공간이 없어져 납작해진다. 공기를 넣어 쓰는 물체는 튜브, 빼내어 쓰는 물체는 이불 압축 팩이다.","scoring_points":["공기가 공간을 차지한다는 성질을 썼는가","세 놀이를 그 성질로 설명했는가","넣어 쓰는 물체와 빼내어 쓰는 물체를 하나씩 썼는가"]},"explanation":["성질을 먼저 써요.","세 놀이를 설명해요.","예를 하나씩 들어요."],"asset":{"type":"passage","lines":["비닐봉지에 공기를 넣고 입구를 묶었더니 눌러도 납작해지지 않았다.","튜브에 공기를 넣으니 통통하게 부풀었다.","이불 압축 팩에서 공기를 빼니 이불이 납작해졌다."],"title":"햇살반 일지 ⑥ 공기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_c#25','sci',3,2,'u1','','g3_2_sci_u1_review_c','unit_review','SC3-2-u1-C14',4,'essay','teacher','햇살반에서 3D 프린터로 만들고 싶은 물체를 하나 정해, 만드는 방법과 알맞은 재료를 쓰세요. 재료를 고른 까닭도 성질과 이어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-2-u1-C14","difficulty":4,"kind":"essay","stem":"햇살반에서 3D 프린터로 만들고 싶은 물체를 하나 정해, 만드는 방법과 알맞은 재료를 쓰세요. 재료를 고른 까닭도 성질과 이어 쓰세요.","answer_guide":{"answer":"예: 교실 화분에 꽂을 이름 팻말을 만들고 싶다. 팻말 모양을 그린 설계도를 컴퓨터에 넣으면 3D 프린터가 물질을 정해진 두께만큼 겹겹이 쌓아 만든다. 재료는 플라스틱이 알맞다. 플라스틱은 가벼운 편이고 색깔과 모양을 다양하게 만들 수 있어 화분마다 다른 색으로 꾸밀 수 있다.","scoring_points":["만들고 싶은 물체를 정했는가","설계도와 겹겹이 쌓는 방법을 썼는가","재료를 성질과 이어 골랐는가"]},"explanation":["물체를 정해요.","만드는 방법을 써요.","재료와 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#1','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C1',1,'mc','auto','물체인 것은 무엇인가요?',ARRAY['SC3-2-u1-X01']::text[],false,'{"seq":1,"concept":"SC3-2-u1-C1","difficulty":1,"kind":"mc","stem":"물체인 것은 무엇인가요?","options":[{"t":"의자","correct":true},{"t":"빨간색","mis":"SC3-2-u1-X01"},{"t":"달콤한 냄새","mis":"SC3-2-u1-X01"},{"t":"종소리","mis":"SC3-2-u1-X01"}],"explanation":["모양이 있나요?","공간을 차지하나요?","의자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
