INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#3','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C4',1,'mc','auto','손잡이와 날의 물질이 서로 다른 물체는 무엇인가요?',ARRAY['SC3-2-u1-X06']::text[],false,'{"seq":3,"concept":"SC3-2-u1-C4","difficulty":1,"kind":"mc","stem":"손잡이와 날의 물질이 서로 다른 물체는 무엇인가요?","options":[{"t":"가위","correct":true},{"t":"구슬","mis":"SC3-2-u1-X06"},{"t":"집게","mis":"SC3-2-u1-X06"},{"t":"자","mis":"SC3-2-u1-X06"}],"explanation":["부분마다 봐요.","손잡이와 날이 있어요.","가위예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
