INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#5','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C7',1,'mc','auto','물질의 종류에 따라 물체를 분류할 때 바탕으로 삼는 것은 무엇인가요?',ARRAY['SC3-2-u1-X12']::text[],false,'{"seq":5,"concept":"SC3-2-u1-C7","difficulty":1,"kind":"mc","stem":"물질의 종류에 따라 물체를 분류할 때 바탕으로 삼는 것은 무엇인가요?","options":[{"t":"물질의 성질","correct":true},{"t":"물체의 가격","mis":"SC3-2-u1-X12"},{"t":"물체를 산 날짜","mis":"SC3-2-u1-X12"},{"t":"물체의 주인","mis":"SC3-2-u1-X12"}],"explanation":["나무는 무늬, 철은 광택이에요.","성질을 봐요.","물질의 성질이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
