INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#7','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C9',1,'blank','auto','액체는 담는 용기에 따라 (    )은 변하지만 부피는 변하지 않아요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-2-u1-X19','SC3-2-u1-X20','SC3-2-u1-X08']::text[],false,'{"seq":7,"concept":"SC3-2-u1-C9","difficulty":1,"kind":"blank","stem":"액체는 담는 용기에 따라 (    )은 변하지만 부피는 변하지 않아요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"모양","correct":true},{"t":"부피","mis":"SC3-2-u1-X19"},{"t":"색깔","mis":"SC3-2-u1-X20"},{"t":"무게","mis":"SC3-2-u1-X08"}],"explanation":["컵에 따라 달라져요.","부피는 그대로예요.","모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
