INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#9','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C2',2,'mc','auto','탐정놀이를 하는 태도로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u1-X04']::text[],false,'{"seq":9,"concept":"SC3-2-u1-C2","difficulty":2,"kind":"mc","stem":"탐정놀이를 하는 태도로 알맞은 것은 무엇인가요?","options":[{"t":"친구가 단서를 말할 때 끝까지 듣는다","correct":true},{"t":"친구 말을 끊고 먼저 말한다","mis":"SC3-2-u1-X04"},{"t":"많이 맞힌 친구를 놀린다","mis":"SC3-2-u1-X04"},{"t":"정답부터 말해 준다","mis":"SC3-2-u1-X04"}],"explanation":["함께하는 놀이예요.","끝까지 들어요.","그게 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
