INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#11','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C6',2,'mc','auto','나무 그릇과 플라스틱 그릇에 모두 해당하는 것은 무엇인가요?',ARRAY['SC3-2-u1-X09']::text[],false,'{"seq":11,"concept":"SC3-2-u1-C6","difficulty":2,"kind":"mc","stem":"나무 그릇과 플라스틱 그릇에 모두 해당하는 것은 무엇인가요?","options":[{"t":"다른 그릇보다 가벼운 편이다","correct":true},{"t":"투명해서 속이 비친다","mis":"SC3-2-u1-X09"},{"t":"광택이 있고 매우 단단하다","mis":"SC3-2-u1-X09"},{"t":"떨어뜨리면 쉽게 깨진다","mis":"SC3-2-u1-X09"}],"explanation":["두 그릇을 떠올려요.","들어 보면 가벼워요.","가벼운 편이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#12','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C7',2,'mc','auto','「플라스틱으로 이루어져 있나요?」에서 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u1-X13']::text[],false,'{"seq":12,"concept":"SC3-2-u1-C7","difficulty":2,"kind":"mc","stem":"「플라스틱으로 이루어져 있나요?」에서 ⭕ 쪽에 들어가는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"탁구공, 플라스틱 바구니, 요구르트병","correct":true},{"t":"탁구공, 비커, 요구르트병","mis":"SC3-2-u1-X13"},{"t":"철 고리, 플라스틱 바구니, 탁구공","mis":"SC3-2-u1-X13"},{"t":"꽃병, 어항, 비커","mis":"SC3-2-u1-X13"}],"explanation":["가볍고 색깔이 다양한 것을 찾아요.","비커, 철 고리는 빼요.","탁구공, 바구니, 요구르트병이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#13','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C9',2,'mc','auto','액체를 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X16','SC3-2-u1-X19','SC3-2-u1-X20']::text[],false,'{"seq":13,"concept":"SC3-2-u1-C9","difficulty":2,"kind":"mc","stem":"액체를 알맞게 말한 것은 무엇인가요?","options":[{"t":"흐르는 성질이 있어 담는 용기에 따라 모양이 변한다","correct":true},{"t":"모양과 부피가 모두 그대로다","mis":"SC3-2-u1-X16"},{"t":"담는 용기에 따라 부피가 늘었다 줄었다 한다","mis":"SC3-2-u1-X19"},{"t":"손으로 잡을 수 있다","mis":"SC3-2-u1-X20"}],"explanation":["물을 떠올려요.","흘러요.","모양이 변해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#14','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C10',2,'mc','auto','탁구공 실험에서 뚜껑을 열면 물 높이는 어떻게 되나요?',ARRAY['SC3-2-u1-X22','SC3-2-u1-X23']::text[],false,'{"seq":14,"concept":"SC3-2-u1-C10","difficulty":2,"kind":"mc","stem":"탁구공 실험에서 뚜껑을 열면 물 높이는 어떻게 되나요?","options":[{"t":"처음 높이와 같아진다","correct":true},{"t":"더 높아진다","mis":"SC3-2-u1-X22"},{"t":"처음보다 훨씬 낮아진다","mis":"SC3-2-u1-X22"},{"t":"뚜껑을 열 때와 관계없이 그대로 높다","mis":"SC3-2-u1-X23"}],"explanation":["공기가 빠져나가요.","물이 들어와요.","처음과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#15','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C12',2,'mc','auto','한 물체에 여러 상태가 함께 있는 예로 알맞은 것은 무엇인가요?',ARRAY['SC3-2-u1-X29']::text[],false,'{"seq":15,"concept":"SC3-2-u1-C12","difficulty":2,"kind":"mc","stem":"한 물체에 여러 상태가 함께 있는 예로 알맞은 것은 무엇인가요?","options":[{"t":"공기를 넣은 축구공 — 공은 고체, 속은 기체","correct":true},{"t":"나무 블록 — 모두 액체","mis":"SC3-2-u1-X29"},{"t":"유리구슬 — 모두 기체","mis":"SC3-2-u1-X29"},{"t":"철 집게 — 모두 액체","mis":"SC3-2-u1-X29"}],"explanation":["물체와 속을 따로 봐요.","공 속에 공기가 있어요.","축구공이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#16','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C14',2,'mc','auto','3D 프린터가 쓰이는 분야끼리 묶은 것은 무엇인가요?',ARRAY['SC3-2-u1-X36','SC3-2-u1-X35']::text[],false,'{"seq":16,"concept":"SC3-2-u1-C14","difficulty":2,"kind":"mc","stem":"3D 프린터가 쓰이는 분야끼리 묶은 것은 무엇인가요?","options":[{"t":"의료, 건축, 자동차","correct":true},{"t":"날씨, 바람, 햇빛","mis":"SC3-2-u1-X36"},{"t":"의료 한 분야뿐","mis":"SC3-2-u1-X36"},{"t":"살아 있는 동물 기르기","mis":"SC3-2-u1-X35"}],"explanation":["만든 것을 떠올려요.","치아, 건물, 부품이에요.","의료, 건축, 자동차예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#17','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C12',3,'ox','auto','햇살반 일지 ②의 자전거에는 고체와 기체가 함께 있어요.',ARRAY['SC3-2-u1-X29']::text[],false,'{"seq":17,"concept":"SC3-2-u1-C12","difficulty":3,"kind":"ox","stem":"햇살반 일지 ②의 자전거에는 고체와 기체가 함께 있어요.","answer":"O","reason_options":[{"t":"몸체·타이어는 고체이고 타이어 속 공기는 기체이기 때문에","correct":true},{"t":"한 물체에는 한 가지 상태만 있기 때문에","mis":"SC3-2-u1-X29"}],"mis":"SC3-2-u1-X29","explanation":["부분마다 따져요.","타이어 속은 공기예요.","그래서 O예요."],"asset":{"type":"passage","lines":["몸체 — 철 · 바구니 — 플라스틱","타이어 — 고무 · 안장 덮개 — 섬유","타이어 속에는 공기를 넣었어요."],"title":"햇살반 일지 ② 학교 자전거 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#18','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C8',3,'mc','auto','모래를 넣어 고체끼리만 묶은 것은 무엇인가요?',ARRAY['SC3-2-u1-X18','SC3-2-u1-X17','SC3-2-u1-X30']::text[],false,'{"seq":18,"concept":"SC3-2-u1-C8","difficulty":3,"kind":"mc","stem":"모래를 넣어 고체끼리만 묶은 것은 무엇인가요?","options":[{"t":"모래, 스펀지, 종이","correct":true},{"t":"모래, 물, 종이","mis":"SC3-2-u1-X18"},{"t":"스펀지, 간장, 연필","mis":"SC3-2-u1-X17"},{"t":"종이, 풍선 속 공기, 클립","mis":"SC3-2-u1-X30"}],"explanation":["하나씩 따져요.","모래도 스펀지도 고체예요.","모래, 스펀지, 종이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#19','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C11',3,'ox','auto','햇살반 일지 ⑥의 세 가지 모두 공기가 공간을 차지하는 성질과 관계있어요.',ARRAY['SC3-2-u1-X21']::text[],false,'{"seq":19,"concept":"SC3-2-u1-C11","difficulty":3,"kind":"ox","stem":"햇살반 일지 ⑥의 세 가지 모두 공기가 공간을 차지하는 성질과 관계있어요.","answer":"O","reason_options":[{"t":"공기를 넣으면 부풀고 빼면 납작해지기 때문에","correct":true},{"t":"공기는 보이지 않아 공간을 차지하지 않기 때문에","mis":"SC3-2-u1-X21"}],"mis":"SC3-2-u1-X21","explanation":["넣으면 부풀어요.","빼면 납작해요.","그래서 O예요."],"asset":{"type":"passage","lines":["비닐봉지에 공기를 넣고 입구를 묶었더니 눌러도 납작해지지 않았다.","튜브에 공기를 넣으니 통통하게 부풀었다.","이불 압축 팩에서 공기를 빼니 이불이 납작해졌다."],"title":"햇살반 일지 ⑥ 공기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#20','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C12',3,'mc','auto','햇살반 일지 ⑦의 세 친구 말을 바로잡을 때 공통으로 떠올릴 것은 무엇인가요?',ARRAY['SC3-2-u1-X21','SC3-2-u1-X28','SC3-2-u1-X18']::text[],false,'{"seq":20,"concept":"SC3-2-u1-C12","difficulty":3,"kind":"mc","stem":"햇살반 일지 ⑦의 세 친구 말을 바로잡을 때 공통으로 떠올릴 것은 무엇인가요?","options":[{"t":"고체, 액체, 기체는 모두 공간을 차지하며 상태마다 성질이 다르다","correct":true},{"t":"눈에 보이는 것만 물질이다","mis":"SC3-2-u1-X21"},{"t":"물이 들어 있어야 액체이다","mis":"SC3-2-u1-X28"},{"t":"모양이 변하면 모두 액체이다","mis":"SC3-2-u1-X18"}],"explanation":["세 상태를 떠올려요.","모두 공간을 차지해요.","성질로 따져요."],"asset":{"type":"passage","lines":["친구 가 — 「공기는 보이지 않으니 물질이 아니야.」","친구 나 — 「참기름은 물이 없으니 액체가 아니야.」","친구 다 — 「모래는 컵 모양 따라 변하니 액체야.」","선생님 — 세 친구의 말을 배운 것으로 하나씩 따져 보자."],"title":"햇살반 일지 ⑦ 교실 토론"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#21','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C13',3,'ox','auto','햇살반 일지 ⑧의 우산꽂이는 부분마다 다른 물질을 썼어요.',ARRAY['SC3-2-u1-X32']::text[],false,'{"seq":21,"concept":"SC3-2-u1-C13","difficulty":3,"kind":"ox","stem":"햇살반 일지 ⑧의 우산꽂이는 부분마다 다른 물질을 썼어요.","answer":"O","reason_options":[{"t":"통은 철, 바닥은 고무, 이름표는 플라스틱이기 때문에","correct":true},{"t":"좋은 설계는 한 가지 물질만 쓰기 때문에","mis":"SC3-2-u1-X32"}],"mis":"SC3-2-u1-X32","explanation":["부분마다 읽어요.","세 가지 물질이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["우산꽂이 통 — 철(단단함) · 바닥 — 고무(잘 미끄러지지 않음)","이름표 — 3D 프린터로 플라스틱을 겹겹이 쌓아 만듦","친구 의견 — 「통이 튼튼해서 좋아. 손잡이를 달면 옮기기 더 좋겠어.」"],"title":"햇살반 일지 ⑧ 우산꽂이 설계 발표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#22','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C14',3,'ox','auto','3D 프린팅 전문가는 제품을 디자인하고 인쇄한 뒤 다듬어요.',ARRAY['SC3-2-u1-X36']::text[],false,'{"seq":22,"concept":"SC3-2-u1-C14","difficulty":3,"kind":"ox","stem":"3D 프린팅 전문가는 제품을 디자인하고 인쇄한 뒤 다듬어요.","answer":"O","reason_options":[{"t":"3D 프린터로 제품을 만드는 일을 하기 때문에","correct":true},{"t":"환자를 진찰하는 일을 하기 때문에","mis":"SC3-2-u1-X36"}],"mis":"SC3-2-u1-X36","explanation":["3D 프린터와 관련된 일이에요.","디자인하고 인쇄해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#23','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C3',4,'mc','auto','「공원의 분수대 물, 풍선 속 공기, 나무 의자」를 알맞게 말한 것은 무엇인가요?',ARRAY['SC3-2-u1-X21','SC3-2-u1-X30','SC3-2-u1-X05']::text[],false,'{"seq":23,"concept":"SC3-2-u1-C3","difficulty":4,"kind":"mc","stem":"「공원의 분수대 물, 풍선 속 공기, 나무 의자」를 알맞게 말한 것은 무엇인가요?","options":[{"t":"셋 다 공간을 차지하는 물질이며, 차례로 액체, 기체, 고체이다","correct":true},{"t":"나무 의자만 물질이고 나머지는 물질이 아니다","mis":"SC3-2-u1-X21"},{"t":"셋 다 액체이다","mis":"SC3-2-u1-X30"},{"t":"셋 다 물체이고 물질은 하나도 없다","mis":"SC3-2-u1-X05"}],"explanation":["모두 공간을 차지해요.","상태를 하나씩 따져요.","액체, 기체, 고체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#24','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C7',4,'essay','teacher','햇살반 일지 ④의 분리배출 기록에서 잘못된 곳을 찾아 바르게 고치고, 그렇게 고친 까닭을 물질의 성질로 쓰세요. 분리배출을 물질의 종류대로 해야 하는 까닭도 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC3-2-u1-C7","difficulty":4,"kind":"essay","stem":"햇살반 일지 ④의 분리배출 기록에서 잘못된 곳을 찾아 바르게 고치고, 그렇게 고친 까닭을 물질의 성질로 쓰세요. 분리배출을 물질의 종류대로 해야 하는 까닭도 쓰세요.","answer_guide":{"answer":"예: 요구르트병은 유리병류가 아니라 플라스틱류에 넣어야 한다. 요구르트병은 가볍고 색깔과 모양이 다양한 플라스틱이기 때문이다. 분리배출은 같은 물질끼리 모아야 다시 쓰기 쉬우므로 물질의 종류대로 해야 한다.","scoring_points":["잘못된 곳을 찾아 고쳤는가","고친 까닭을 물질의 성질로 썼는가","분리배출을 물질의 종류대로 해야 하는 까닭을 썼는가"]},"explanation":["잘못 넣은 것을 찾아요.","성질로 까닭을 써요.","분리배출의 까닭을 써요."],"asset":{"type":"passage","lines":["유리병류 — 빈 잼 유리병, 요구르트병","캔류 — 빈 철 캔","플라스틱류 — 페트병, 플라스틱 컵"],"title":"햇살반 일지 ④ 분리배출 당번 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_sci_u1_review_d#25','sci',3,2,'u1','','g3_2_sci_u1_review_d','unit_review','SC3-2-u1-C6',4,'essay','teacher','「물체와 물질」 단원에서 배운 것을 바탕으로, 교실에서 쓰는 물체 하나를 골라 어떤 물질로 이루어졌는지 쓰고, 그 물질의 성질이 물체의 쓰임새에 어떻게 도움이 되는지 쓰세요. 물체 속에 고체가 아닌 상태가 있다면 그것도 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-2-u1-C6","difficulty":4,"kind":"essay","stem":"「물체와 물질」 단원에서 배운 것을 바탕으로, 교실에서 쓰는 물체 하나를 골라 어떤 물질로 이루어졌는지 쓰고, 그 물질의 성질이 물체의 쓰임새에 어떻게 도움이 되는지 쓰세요. 물체 속에 고체가 아닌 상태가 있다면 그것도 쓰세요.","answer_guide":{"answer":"예: 교실의 물병을 골랐다. 물병 몸통은 플라스틱으로 이루어져 있다. 플라스틱은 가벼운 편이라 들고 다니기 좋고 잘 깨지지 않아 떨어뜨려도 안전하다. 물병 속의 물은 액체라서 물병 모양을 따라 모양이 변하고, 물을 마시고 남은 공간에는 공기(기체)가 가득 차 있다.","scoring_points":["물체와 물질을 바르게 썼는가","물질의 성질을 쓰임새와 이어 썼는가","고체가 아닌 상태를 찾아 썼는가"]},"explanation":["물체를 골라요.","성질과 쓰임새를 이어요.","다른 상태도 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
